/* MathQuest — Sciences de la vie et de la Terre (collège) : 32 chapitres reconstruits (6e, 5e, 4e, 3e), année scolaire 2026-2027.
   Programme(s) appliqué(s) :
   - 6e : programme de sciences et technologie du cycle 3, annexe de l’arrêté du 15 juin 2023 (NOR MENE2314101A) publiée au BO n°25 du 22 juin 2023
     (version « d’après le BOEN n°31 du 30 juillet 2020 et le BOEN n°25 du 22 juin 2023 »), thèmes « Le vivant, sa diversité et les fonctions qui le
     caractérisent » et « La Terre, une planète peuplée par des êtres vivants ». Le nouveau programme de cycle 3 (arrêté du 5 juin 2026, NOR MENE2611650A,
     BO n°24 du 11 juin 2026) ne s’applique en 6e qu’à la rentrée 2027 (article 3 de l’arrêté ; Éduscol : « l’ancien programme du cycle 3, entré en vigueur
     à la rentrée 2023, reste en vigueur pour l’année scolaire 2026-2027 pour les classes de CM2 et 6e ») : il n’est donc pas utilisé ici.
   - 5e, 4e, 3e : programme de sciences de la vie et de la Terre du cycle 4, BO n°31 du 30 juillet 2020 (tableau Éduscol « Les programmes du cycle 4 à la
     rentrée de l’année scolaire 2026-2027 » : SVT = BO n°31 du 30 juillet 2020 pour les trois niveaux). Le projet de programme de SVT du CSP (10 juillet 2025)
     n’a pas fait l’objet d’un arrêté applicable en 2026-2027.
   - Chapitres sur la puberté, la reproduction et la sexualité (svt5f, svt4c, svt3d) : contenu limité au programme de SVT du cycle 4 (« Puberté, organes
     reproducteurs, production de cellules reproductrices, contrôles hormonaux » ; « fertilité, grossesse, respect de l’autre, choix raisonné de la procréation,
     contraception, prévention des infections sexuellement transmissibles »), en cohérence avec le programme d’EVARS du collège (BO n°6 du 6 février 2025).
   Vérifié le 7 octobre 2026 sur legifrance.gouv.fr (JORFTEXT000054218988), education.gouv.fr (BO n°25 du 22 juin 2023, MENE2314101A) et
   eduscol.education.gouv.fr (« Enseigner au cycle 3 », « Enseigner au cycle 4 », ressources d’accompagnement SVT cycle 4, programmes PDF). */
(function(){
'use strict';
const MQ=window.MQCollege;if(!MQ)return;const H=MQ.H;
const {R,P,ch,num,order,bank,sort,seq,mix,pickN,shuffle,nf,dec}=H;
const cap=x=>x.charAt(0).toUpperCase()+x.slice(1);
const pairs=(l,o={})=>H.pairs(l,{e:(a,b)=>`${cap(a)} : ${b}.`,...o});
const C=(d,u,ex,m,a,r)=>({d,u,ex,m,a,r});const T=(t,h)=>({t,h});
const REF6='Cycle 3 — programme de sciences et technologie, arrêté du 15 juin 2023 (MENE2314101A), BO n°25 du 22 juin 2023 : programme applicable en 6e en 2026-2027';
const E6=s=>`Éduscol — « Enseigner au cycle 3 » (programme de 6e d’après le BOEN n°31 du 30 juillet 2020 et le BOEN n°25 du 22 juin 2023), thème « ${s} »`;
const REF4='Cycle 4 — programme de sciences de la vie et de la Terre, BO n°31 du 30 juillet 2020 : programme applicable en 5e, 4e et 3e en 2026-2027';
const E4=s=>`Éduscol — ressources d’accompagnement du programme de SVT au cycle 4, thème « ${s} »`;
const TH1='La planète Terre, l’environnement et l’action humaine',TH2='Le vivant et son évolution',TH3='Le corps humain et la santé';
const REFEV='Programme d’éducation à la vie affective et relationnelle, et à la sexualité (collège), BO n°6 du 6 février 2025';

/* ===== Outils communs ===== */
const rd=(x,k=6)=>Math.round(x*10**k)/10**k;
const F=x=>dec(x,6);
// Classement avec explication propre à chaque catégorie.
const S=(cats,q,why)=>sort(cats,{q,e:(x,c)=>`« ${x} » → <b>${c}</b>. ${why[c]||''}`});
// Plusieurs suites ordonnées : on choisit une suite, puis « après », « avant » ou « remettre dans l’ordre ».
function seqs(list){return d=>{const [name,items]=P(list);
  const r=Math.random();
  if(d>=2&&r<.4){const n=Math.min(items.length,d===2?3:4),s=R(0,items.length-n),part=items.slice(s,s+n);return order(`${name} : remets dans l’ordre.`,part,{expl:part.join(' → ')+'.',hint:'Commence par la première étape.'});}
  const i=R(0,items.length-2);
  if(r<.7)return ch(`${name} : quelle étape vient juste après « ${items[i]} » ?`,items[i+1],pickN(items.filter((x,k)=>k!==i+1&&k!==i),3),{expl:`Dans l’ordre : ${items.join(' → ')}.`,hint:'Pense à ce qui se passe ensuite.'});
  return ch(`${name} : quelle étape vient juste avant « ${items[i+1]} » ?`,items[i],pickN(items.filter((x,k)=>k!==i+1&&k!==i),3),{expl:`Dans l’ordre : ${items.join(' → ')}.`,hint:'Pense à ce qui se passe avant.'});};}

/* ===== Données partagées ===== */
// Classification : chemin des groupes emboîtés (du plus large au plus petit).
const GRP={V:['les vertébrés','un squelette interne avec une colonne vertébrale'],T:['les tétrapodes','quatre membres'],M:['les mammifères','des poils et des mamelles'],O:['les oiseaux','des plumes'],
  A:['les arthropodes','un squelette externe et des pattes articulées'],I:['les insectes','six pattes'],Ar:['les arachnides','huit pattes'],Cr:['les crustacés','deux paires d’antennes'],Mo:['les mollusques','un corps mou']};
const ANI={'le chat':['V','T','M'],'la souris':['V','T','M'],'le lapin':['V','T','M'],'l’être humain':['V','T','M'],'la chauve-souris':['V','T','M'],
  'le pigeon':['V','T','O'],'la poule':['V','T','O'],'le manchot':['V','T','O'],'la grenouille':['V','T'],'le lézard':['V','T'],
  'la truite':['V'],'le requin':['V'],'la sardine':['V'],'le criquet':['A','I'],'l’abeille':['A','I'],'le papillon':['A','I'],
  'l’araignée':['A','Ar'],'le scorpion':['A','Ar'],'le crabe':['A','Cr'],'la crevette':['A','Cr'],'l’escargot':['Mo'],'la moule':['Mo'],'la pieuvre':['Mo']};
const deN=n=>/^le /.test(n)?'du '+n.slice(3):'de '+n;
const shared=(a,b)=>{const x=ANI[a],y=ANI[b];let k=0;while(k<x.length&&k<y.length&&x[k]===y[k])k++;return k;};
function parente(d){
  const names=Object.keys(ANI);
  for(let t=0;t<60;t++){
    const X=P(names);const others=names.filter(n=>n!==X);const ok=others.filter(n=>shared(X,n)>=(d===1?2:1));if(!ok.length)continue;
    const good=P(ok),k=shared(X,good);const bad=pickN(others.filter(n=>shared(X,n)<k),3);if(bad.length<2)continue;
    const g=GRP[ANI[X][k-1]];
    const expl=`${cap(good)} et ${X} possèdent tous deux <b>${g[1]}</b> : ils appartiennent au même groupe emboîté le plus petit (${g[0]}). ${bad.join(', ')} ne partage${bad.length>1?'nt':''} avec ${X} que des attributs plus généraux (ou aucun attribut de ce tableau) : ${bad.length>1?'ils sont':'il est'} plus éloigné${bad.length>1?'s':''}.`;
    return ch(`Parmi ces êtres vivants, lequel est le <b>plus proche parent</b> ${deN(X)} ?`,good,bad,{expl,hint:'Cherche celui qui partage avec lui l’attribut le plus « exclusif » (le groupe le plus petit).'});
  }
  return ch('Quel attribut partagent le chat et la souris, mais pas le pigeon ?','des poils et des mamelles',['des plumes','quatre membres','un squelette interne'],{expl:'Le chat et la souris sont des mammifères (poils, mamelles) ; le pigeon a des plumes.'});
}
// Chaînes alimentaires : la flèche signifie « est mangé par ».
const CHAINS=[['salade','escargot','hérisson'],['herbe','lapin','renard'],['feuilles de chêne','chenille','mésange','épervier'],['phytoplancton','zooplancton','sardine','thon'],
  ['graines','mulot','chouette'],['herbe','criquet','grenouille','héron'],['algues','oursin','loutre de mer'],['feuilles de ronce','puceron','coccinelle','mésange']];
const ROLE=['producteur','consommateur primaire (herbivore)','consommateur secondaire','consommateur tertiaire'];
function chaine(d){const c=P(CHAINS.filter(x=>d===1?x.length===3:true));const s=c.join(' → ');const i=R(0,c.length-1);const r=Math.random();
  if(r<.55)return ch(`Dans la chaîne alimentaire <b>${s}</b>, quel est le rôle de « ${c[i]} » ?`,ROLE[i],[...ROLE.filter((x,k)=>k!==i&&k<Math.max(3,c.length)),'décomposeur'],{expl:i===0?`${c[0]} est un être vivant chlorophyllien (ou ses organes) : il produit sa matière à partir de la lumière, de l’eau, des sels minéraux et du CO₂. C’est le <b>producteur</b>, toujours au début de la chaîne.`:`« ${c[i]} » mange ${c[i-1]} : il est au rang ${i+1} de la chaîne, donc <b>${ROLE[i]}</b>.`,hint:'Le premier maillon est toujours un végétal (producteur).'});
  if(r<.8||c.length<3){const j=R(1,c.length-1);return ch(`Dans la chaîne <b>${s}</b>, de quoi se nourrit « ${c[j]} » ?`,c[j-1],[...c.filter((x,k)=>k!==j-1&&k!==j),'de matière minérale du sol','de la lumière du soleil'],{expl:`La flèche signifie « est mangé par » : ${c[j-1]} → ${c[j]}, donc ${c[j]} mange <b>${c[j-1]}</b>.`,hint:'La flèche va du mangé vers le mangeur.'});}
  const j=R(1,c.length-2);return ch(`Dans la chaîne <b>${s}</b>, la population de « ${c[j]} » disparaît. Que devient d’abord la population de « ${c[j+1]} » ?`,'elle diminue (elle manque de nourriture)',['elle augmente','elle ne change pas','elle devient productrice'],{expl:`« ${c[j+1]} » se nourrit de « ${c[j]} » : privée de nourriture, sa population <b>diminue</b> (ou elle doit changer de proie). À l’inverse, « ${c[j-1]} », moins consommé, peut devenir plus abondant.`,hint:'Qui mange qui ?'});}

MQ.add('svt','6',[
/* ===================== 6e ===================== */
{id:'svt6a',name:'Besoins alimentaires et équilibre nutritionnel',icon:'🍎',domain:'Nutrition',
 refs:[REF6,E6('Le vivant, sa diversité et les fonctions qui le caractérisent — Alimentation humaine')],
 tip:'Pour chaque aliment, demande-toi d’abord à quel groupe il appartient, puis ce qu’il apporte surtout : matériaux pour construire (protéines, calcium) ou énergie (glucides, lipides).',
 c:C(`Pourquoi un adolescent sportif de 12 ans a-t-il besoin de manger davantage qu’un enfant de 6 ans ? Et pourquoi la pâte à pain gonfle-t-elle alors que le lait devient yaourt ? Les aliments apportent la <b>matière</b> et l’<b>énergie</b> nécessaires à l’organisme, et certains sont fabriqués grâce à des <b>micro-organismes</b>.`,
  [T('Les groupes d’aliments et leur rôle',`<p>On classe les aliments en groupes : <b>fruits et légumes</b> (vitamines, fibres, sels minéraux), <b>féculents</b> (pain, pâtes, riz : glucides qui fournissent de l’énergie), <b>produits laitiers</b> (calcium pour les os et les dents, protéines), <b>viandes, poissons, œufs</b> (protéines pour construire et réparer le corps), <b>matières grasses</b> (lipides : énergie, à consommer en petite quantité), <b>produits sucrés</b> (à limiter). L’<b>eau</b> est la seule boisson indispensable.</p><p>Les <b>protéines</b> servent surtout à construire (croissance, muscles) ; les <b>glucides</b> et les <b>lipides</b> fournissent l’énergie ; l’eau, les vitamines et les sels minéraux permettent le bon fonctionnement de l’organisme.</p>`),
   T('Des besoins qui varient',`<p>Les besoins alimentaires dépendent de l’<b>âge</b> (pendant la croissance, il faut de la matière pour fabriquer de nouveaux tissus), de la <b>taille</b>, du <b>sexe</b> et surtout de l’<b>activité physique</b>. L’énergie apportée se mesure en kilojoules (kJ) ou en kilocalories (kcal).</p><p>Un repas est <b>équilibré</b> quand il apporte des aliments variés, en quantité adaptée aux dépenses. Trop d’apports par rapport aux dépenses : le surplus est stocké sous forme de graisses. Pas assez : fatigue, amaigrissement. Après la digestion, la <b>circulation sanguine</b> apporte les nutriments à tous les organes.</p>`),
   T('Des micro-organismes pour produire et conserver',`<p>Le <b>pain</b> lève grâce à la <b>levure</b>, un champignon microscopique : sa fermentation produit du dioxyde de carbone qui fait gonfler la pâte. Le <b>yaourt</b> est obtenu grâce à des <b>ferments lactiques</b> (bactéries) qui transforment le sucre du lait en acide lactique : le lait épaissit et devient acide. La température et la durée influencent le résultat.</p><p>Pour <b>conserver</b> les aliments, on empêche les micro-organismes indésirables de se développer : froid (le réfrigérateur ralentit leur multiplication, le congélateur la bloque), chaleur (stérilisation, pasteurisation : elles tuent les micro-organismes), salage, sucrage, séchage, mise sous vide.</p>`)],
  [{q:'L’étiquette d’un paquet de pâtes indique 150 kcal pour 100 g de pâtes cuites. Quelle énergie apporte une assiette de 250 g ?',s:['L’énergie est proportionnelle à la masse.','250 g = 2,5 × 100 g.','Énergie : 2,5 × 150 = 375 kcal.']},
   {q:'Pourquoi un yaourt maison ne prend-il pas si on le laisse au réfrigérateur au lieu de la yaourtière ?',s:['Le yaourt est fabriqué par des bactéries (ferments lactiques).','Au froid, leur activité est très ralentie.','Elles ne produisent presque pas d’acide lactique : le lait ne s’épaissit pas.']}],
  ['Je repère le groupe de chaque aliment.','Je relie chaque groupe à son rôle principal (construire, fournir de l’énergie, bien fonctionner).','Je compare les apports aux besoins (âge, activité).','Pour une transformation ou une conservation, je me demande ce que deviennent les micro-organismes.'],
  ['Croire qu’un aliment « fait grossir » à lui seul : c’est l’excès d’apports par rapport aux dépenses qui fait stocker des graisses.','Penser que tous les micro-organismes sont dangereux : la levure et les ferments lactiques sont utiles.','Croire que le congélateur tue les microbes : il bloque leur multiplication, mais beaucoup survivent et redémarrent à la décongélation.'],
  ['Les protéines construisent ; les glucides et les lipides fournissent l’énergie.','Les besoins varient avec l’âge, la taille, le sexe et l’activité physique.','La levure (pain) et les ferments lactiques (yaourt) sont des micro-organismes utiles.','Froid, chaleur, sel, sucre, séchage limitent le développement des micro-organismes.']),
 g:mix([d=>{const [f,k,ms]=P([['pâtes cuites',150,[150,200,250,300]],['riz cuit',130,[150,200,250]],['pain',270,[40,50,60,80]],['yaourt nature',60,[125,150,250]],['pomme',50,[120,150,180,200]],['emmental',380,[20,30,40]],['chocolat noir',540,[10,20,30]],['banane',90,[100,120,150]],['steak haché',130,[100,120,150]]]);const m=P(ms);const e=k*m/100;
    return num(`L’étiquette indique <b>${k} kcal pour 100 g</b> ${/^[aeiouyéèêàâîïôûh]/i.test(f)?'d’':'de '}${f}. Quelle énergie apporte une portion de <b>${m} g</b> ?`,e,{unit:'kcal',expl:`L’énergie est proportionnelle à la masse : ${k} × ${m} ÷ 100 = <b>${nf(e)} kcal</b>.`,hint:'Calcule d’abord l’énergie apportée par 1 g, ou cherche combien de fois 100 g il y a dans la portion.'});},3],
  [S({'fruits et légumes':['la pomme','la carotte','les haricots verts','l’orange','la tomate'],'féculents':['les pâtes','le riz','le pain','les pommes de terre','la semoule'],'produits laitiers':['le yaourt','le fromage','le lait'],'viandes, poissons, œufs':['le poulet','la sardine','l’œuf','le steak'],'matières grasses':['le beurre','l’huile d’olive']},
    'Dans quel groupe d’aliments ranges-tu « %s » ?',{'fruits et légumes':'Ils apportent vitamines, fibres et sels minéraux.','féculents':'Riches en glucides (amidon), ils fournissent de l’énergie durable.','produits laitiers':'Ils apportent du calcium et des protéines.','viandes, poissons, œufs':'Riches en protéines, ils servent à construire le corps.','matières grasses':'Riches en lipides, très énergétiques : à consommer en petite quantité.'}),3],
  [pairs([['les protéines','construire et réparer les organes (croissance, muscles)'],['les glucides','fournir de l’énergie, surtout aux muscles et au cerveau'],['les lipides','fournir beaucoup d’énergie et former des réserves'],['le calcium','construire et solidifier les os et les dents'],['les fibres','faciliter le transit intestinal'],['l’eau','constituer la majeure partie du corps et transporter les substances']],{q:'Quel est le rôle principal de ce constituant des aliments : %s ?',rq:'Quel constituant des aliments sert surtout à : « %s » ?'}),2],
  [bank([['Quelle est la seule boisson indispensable ?','l’eau',['le jus de fruits','le lait','le soda'],'L’eau compense les pertes (urine, sueur, respiration) ; les autres boissons ne sont pas indispensables.',1],
   ['Quel micro-organisme fait lever la pâte à pain ?','la levure (un champignon microscopique)',['un ferment lactique','un virus','la farine'],'La levure réalise une fermentation qui produit du dioxyde de carbone : les bulles de gaz font gonfler la pâte.',1],
   ['Quels micro-organismes transforment le lait en yaourt ?','des bactéries (ferments lactiques)',['des levures','des virus','des moisissures'],'Les ferments lactiques transforment le sucre du lait (lactose) en acide lactique, qui fait épaissir le lait.',1],
   ['Lucas, 13 ans, fait 6 heures de sport par semaine ; son frère de 7 ans n’en fait pas. Qui a les besoins énergétiques les plus élevés ?','Lucas',['son frère','ils ont exactement les mêmes besoins','on ne peut rien dire'],'Les besoins augmentent avec la taille, la croissance et surtout l’activité physique.',2],
   ['Pourquoi les besoins en protéines sont-ils élevés pendant l’adolescence ?','parce que le corps grandit et fabrique de nouveaux tissus',['parce que les protéines donnent surtout de l’énergie','parce que les adolescents bougent moins','parce que les protéines remplacent l’eau'],'Les protéines sont les matériaux de construction du corps : la croissance en demande beaucoup.',2],
   ['Pourquoi met-on les yaourts au réfrigérateur après leur fabrication ?','pour ralentir l’activité des bactéries et la multiplication de micro-organismes indésirables',['pour tuer toutes les bactéries','pour les rendre plus sucrés','pour faire lever le yaourt'],'Le froid ralentit les micro-organismes : le yaourt ne s’acidifie plus trop et se conserve plus longtemps.',2],
   ['Quel procédé de conservation tue la plupart des micro-organismes ?','la stérilisation (chauffage à haute température dans un récipient fermé)',['la réfrigération','la congélation','l’emballage dans du papier'],'La chaleur intense tue les micro-organismes ; le froid ne fait que ralentir ou bloquer leur multiplication.',2],
   ['Une yaourtière fonctionne vers 40 °C. Si on la règle à 90 °C, le yaourt…','ne prend pas, car les ferments lactiques sont tués par la chaleur',['prend plus vite','prend normalement','devient du fromage'],'Les bactéries du yaourt ont une température d’activité favorable (vers 40 à 45 °C) ; à 90 °C, elles meurent.',3],
   ['Pourquoi le saucisson ou le jambon sec se conservent-ils longtemps ?','le sel et le séchage retirent l’eau dont les micro-organismes ont besoin',['le sel tue tous les virus','ils sont stérilisés','ils contiennent des antibiotiques'],'Sans assez d’eau disponible, les micro-organismes ne peuvent pas se multiplier.',3],
   ['Un élève a mangé beaucoup plus d’énergie qu’il n’en a dépensé pendant plusieurs semaines. Que se passe-t-il ?','le surplus est stocké sous forme de graisses',['le surplus disparaît dans l’urine','il grandit forcément plus vite','rien, l’énergie en trop est éliminée'],'Quand les apports dépassent régulièrement les dépenses, l’organisme met en réserve le surplus sous forme de graisses.',3],
   {tf:'Le sang transporte les nutriments issus de la digestion jusqu’à tous les organes.',v:true,e:'Les nutriments passent de l’intestin dans le sang, qui les distribue à tous les organes.',d:2},
   {tf:'Un aliment très sucré apporte surtout des protéines.',v:false,e:'Le sucre est un glucide : il apporte de l’énergie, pas des protéines.',d:1}]),3])},

{id:'svt6b',name:'Organisation du vivant : de l’organisme à la cellule',icon:'🔬',domain:'Le vivant',
 refs:[REF6,E6('Le vivant, sa diversité et les fonctions qui le caractérisent — Organisation des êtres vivants')],
 tip:'Range toujours du plus grand au plus petit : organisme → appareil → organe → cellule. Pour le microscope, grossissement = oculaire × objectif.',
 c:C(`Un chêne, un chat et une paramécie qui nage dans une goutte d’eau semblent n’avoir rien en commun. Pourtant, au microscope, on découvre que tous sont faits de la même « brique » : la <b>cellule</b>. Comment le vivant est-il organisé, du corps entier jusqu’à cette brique ?`,
  [T('Les niveaux d’organisation',`<p>Un être vivant entier est un <b>organisme</b>. Chez un animal, il est formé d’<b>appareils</b> (appareil digestif, respiratoire…), chacun composé d’<b>organes</b> (estomac, intestin…). Une plante à fleurs a aussi des organes : racine, tige, feuille, fleur.</p><p>Chaque organe est lui-même fait de très nombreuses <b>cellules</b>. La cellule est l’<b>unité structurale commune à tous les êtres vivants</b>. Certains organismes ne sont formés que d’<b>une seule cellule</b> : ce sont des <b>unicellulaires</b> (paramécie, levure, bactérie).</p>`),
   T('Observer et décrire une cellule',`<p>Une cellule est trop petite pour être vue à l’œil nu : on l’observe au <b>microscope</b>. Sa taille se mesure en <b>micromètres</b> (1 mm = 1 000 µm) ; beaucoup de cellules mesurent entre 10 et 100 µm.</p><p>Toute cellule possède une <b>membrane</b> qui la limite et un <b>cytoplasme</b> ; la plupart ont un <b>noyau</b>. Les cellules végétales ont en plus une <b>paroi</b> rigide, souvent des <b>chloroplastes</b> verts (dans les parties vertes) et une grande <b>vacuole</b>. Les bactéries n’ont pas de noyau.</p>`),
   T('Calculer avec le microscope',`<p>Le <b>grossissement</b> du microscope est le produit du grossissement de l’oculaire par celui de l’objectif : oculaire ×10 et objectif ×40 donnent un grossissement de <b>×400</b>.</p><p>Pour retrouver la <b>taille réelle</b> d’un objet, on divise sa taille sur l’image par le grossissement : une cellule qui mesure 20 mm sur une photo prise à ×400 mesure en réalité 20 ÷ 400 = 0,05 mm, soit <b>50 µm</b>.</p>`)],
  [{q:'Au grossissement ×400, une cellule d’épiderme d’oignon mesure 40 mm sur l’image. Quelle est sa taille réelle ?',s:['Taille réelle = taille sur l’image ÷ grossissement.','40 mm ÷ 400 = 0,1 mm.','0,1 mm = 0,1 × 1 000 µm = 100 µm.']}],
  ['Je repère le niveau d’organisation (organisme, appareil, organe, cellule).','Au microscope, je fais la mise au point avec le plus faible grossissement, puis j’augmente.','Je dessine ce que j’observe avec un titre, des légendes et le grossissement.','Pour une taille réelle, je divise par le grossissement et je convertis en µm.'],
  ['Confondre organe et appareil : l’estomac est un organe, l’appareil digestif est un ensemble d’organes.','Croire que seuls les animaux sont faits de cellules : les végétaux, les champignons et les bactéries aussi.','Multiplier par le grossissement au lieu de diviser pour trouver la taille réelle.'],
  ['Organisme → appareil → organe → cellule.','La cellule est l’unité commune à tous les êtres vivants.','Toute cellule a une membrane et un cytoplasme ; la plupart ont un noyau ; les cellules végétales ont une paroi et souvent des chloroplastes.','Grossissement = oculaire × objectif ; taille réelle = taille sur l’image ÷ grossissement.']),
 g:mix([d=>{const oc=P([5,10,15]),ob=P([4,10,40,100]);return num(`Un microscope possède un oculaire <b>×${oc}</b> et un objectif <b>×${ob}</b>. Quel est le grossissement total ?`,oc*ob,{expl:`Grossissement = oculaire × objectif = ${oc} × ${ob} = <b>×${oc*ob}</b>.`,hint:'On multiplie les deux grossissements.'});},2],
  [d=>{const G=P([100,400,1000]);const real=P(G===1000?[2,5,10,20]:[10,20,25,40,50,80,100]);const img=rd(real*G/1000);
    return num(`Sur une photographie prise au microscope (grossissement <b>×${G}</b>), une cellule mesure <b>${nf(img)} mm</b>. Quelle est sa taille réelle en micromètres (µm) ?`,real,{unit:'µm',expl:`Taille réelle = ${nf(img)} ÷ ${G} = ${nf(rd(img/G))} mm ; 1 mm = 1 000 µm, donc <b>${real} µm</b>.`,hint:'Divise par le grossissement, puis convertis en µm (× 1 000).'});},3],
  [S({'cellule animale et cellule végétale':['la membrane','le cytoplasme','le noyau'],'cellule végétale seulement':['la paroi','les chloroplastes','la grande vacuole']},'Dans quel type de cellule trouve-t-on « %s » ?',{'cellule animale et cellule végétale':'C’est un élément commun à presque toutes les cellules.','cellule végétale seulement':'C’est une particularité des cellules végétales.'}),2],
  [S({'organisme':['un chat','un chêne','une paramécie'],'appareil':['l’appareil digestif','l’appareil respiratoire','l’appareil circulatoire'],'organe':['le cœur','l’estomac','une feuille','une racine','un poumon'],'cellule':['un globule rouge','une cellule d’épiderme d’oignon','un neurone']},'« %s » est…',{'organisme':'C’est un être vivant entier.','appareil':'C’est un ensemble d’organes qui assurent ensemble une fonction.','organe':'C’est une partie du corps formée de nombreuses cellules, avec une fonction précise.','cellule':'C’est l’unité de base du vivant, visible au microscope.'}),2],
  [bank([['Quel est l’ordre correct du plus grand au plus petit ?','organisme, appareil, organe, cellule',['cellule, organe, appareil, organisme','organisme, organe, appareil, cellule','appareil, organisme, cellule, organe'],'Un organisme contient des appareils, faits d’organes, eux-mêmes formés de cellules.',1],
   ['Comment appelle-t-on un être vivant formé d’une seule cellule ?','un unicellulaire',['un pluricellulaire','un organe','un tissu'],'La paramécie, la levure ou une bactérie sont des unicellulaires.',1],
   ['Combien de micromètres y a-t-il dans 1 mm ?','1 000',['100','10','10 000'],'1 mm = 1 000 µm.',1],
   ['Quelle structure, colorée en vert, n’existe que dans certaines cellules végétales ?','le chloroplaste',['le noyau','la membrane','le cytoplasme'],'Les chloroplastes contiennent la chlorophylle verte ; on les trouve dans les parties vertes des plantes.',1],
   ['On observe une cellule avec une paroi, des chloroplastes et un noyau. Elle provient…','d’une feuille de plante',['de la joue d’un humain','d’une bactérie','d’un muscle de grenouille'],'Paroi et chloroplastes sont caractéristiques des cellules végétales des parties vertes.',2],
   ['On observe une cellule sans noyau, très petite (2 µm). Il s’agit probablement…','d’une bactérie',['d’une cellule végétale','d’un neurone','d’un ovule'],'Les bactéries sont des cellules sans noyau, beaucoup plus petites que les cellules animales ou végétales.',3],
   ['Pourquoi colore-t-on souvent une préparation avant de l’observer ?','pour rendre visibles des éléments transparents comme le noyau',['pour tuer les cellules','pour augmenter le grossissement','pour faire grossir les cellules'],'Les colorants (bleu de méthylène, eau iodée…) se fixent sur certaines structures et les rendent visibles.',2],
   ['Une cellule de 50 µm est observée au grossissement ×400. Quelle taille aura-t-elle sur l’image ?','20 mm',['2 mm','200 mm','0,125 mm'],'50 µm = 0,05 mm ; 0,05 × 400 = 20 mm.',3],
   {tf:'Les cellules d’une racine de plante contiennent des chloroplastes.',v:false,e:'La racine est dans le sol, à l’obscurité : ses cellules n’ont pas de chloroplastes.',d:3},
   {tf:'Tous les êtres vivants sont formés d’au moins une cellule.',v:true,e:'La cellule est l’unité structurale commune à tous les êtres vivants.',d:1}]),3])},

{id:'svt6c',name:'Classer les êtres vivants et comprendre les liens de parenté',icon:'🌳',domain:'Biodiversité',
 refs:[REF6,E6('Le vivant, sa diversité et les fonctions qui le caractérisent — Classification du vivant')],
 tip:'On classe avec ce que les êtres vivants POSSÈDENT (attributs), jamais avec ce qu’ils n’ont pas ni avec leur mode de vie. Plus deux espèces partagent d’attributs, plus elles sont proches parentes.',
 c:C(`La chauve-souris vole comme un oiseau, la baleine nage comme un poisson… Pourtant, les scientifiques les rangent avec les mammifères. Pourquoi ? Parce que la classification scientifique ne repose pas sur le mode de vie, mais sur les <b>attributs partagés</b>, qui révèlent les <b>liens de parenté</b>.`,
  [T('Classer avec des attributs',`<p>Un <b>attribut</b> est une caractéristique que l’on observe et que l’être vivant <b>possède</b> : squelette interne, quatre membres, poils, plumes, six pattes… On ne classe jamais avec ce qu’un être vivant n’a pas (« sans pattes ») ni avec son milieu ou son alimentation.</p><p>On construit des <b>groupes emboîtés</b> : tous les animaux ayant un squelette interne avec une colonne vertébrale forment les <b>vertébrés</b> ; parmi eux, ceux qui ont quatre membres forment les <b>tétrapodes</b> ; parmi eux, ceux qui ont des poils et des mamelles forment les <b>mammifères</b>. Un groupe ne chevauche jamais un autre groupe : il est inclus dedans ou à côté.</p>`),
   T('Groupes et parenté',`<p>Deux espèces qui partagent un attribut l’ont hérité d’un <b>ancêtre commun</b>. Plus elles partagent d’attributs (plus le groupe commun est petit), plus elles sont <b>proches parentes</b>. Ainsi, le chat est plus proche parent de la souris (mammifères) que du pigeon (seulement tétrapodes en commun).</p><p>Un <b>arbre de parenté</b> représente ces liens : les espèces sont au bout des branches ; un nœud représente un ancêtre commun. D’autres classements existent (utilitaire : comestible ou non ; écologique : selon le milieu) mais ils ne disent rien de la parenté. Une <b>clé de détermination</b> sert à <b>identifier</b> une espèce, pas à établir des parentés.</p>`)],
  [{q:'Qui est le plus proche parent du chat : la souris, le pigeon ou la truite ?',s:['Le chat a un squelette interne, quatre membres, des poils et des mamelles.','La souris partage tous ces attributs ; le pigeon partage squelette interne et quatre membres ; la truite seulement le squelette interne.','La souris partage le groupe le plus petit (mammifères) : c’est le plus proche parent du chat.']}],
  ['Je fais la liste des attributs de chaque être vivant (ce qu’il possède).','Je regroupe ceux qui partagent un même attribut, en emboîtant les groupes du plus large au plus petit.','Je cherche le plus petit groupe commun à deux espèces pour juger leur parenté.','Je vérifie qu’aucun groupe ne chevauche un autre.'],
  ['Classer selon le mode de vie : « les animaux qui volent » mélange oiseaux, chauves-souris et insectes, qui ne sont pas proches parents.','Utiliser des attributs négatifs (« n’a pas de plumes ») : on ne classe qu’avec ce qui est présent.','Dire que l’être humain descend de la souris : ils partagent seulement un ancêtre commun.'],
  ['On classe les êtres vivants selon les attributs qu’ils possèdent.','Les groupes sont emboîtés : vertébrés ⊃ tétrapodes ⊃ mammifères.','Plus deux espèces partagent d’attributs, plus elles sont proches parentes (ancêtre commun plus récent).','Une clé de détermination identifie ; une classification établit des parentés.']),
 g:mix([parente,4],
  [pairs([['un squelette interne avec une colonne vertébrale','les vertébrés'],['quatre membres','les tétrapodes'],['des poils et des mamelles','les mammifères'],['des plumes','les oiseaux'],['un squelette externe et des pattes articulées','les arthropodes'],['six pattes','les insectes'],['huit pattes','les arachnides']],{q:'Quel groupe est défini par l’attribut « %s » ?',rq:'Quel attribut définit le groupe « %s » ?',e:(a,b)=>`Tous les êtres vivants qui possèdent ${a} appartiennent au groupe des ${b.replace(/^les /,'')}.`}),2],
  [bank([['Sur quoi repose la classification scientifique des êtres vivants ?','sur les attributs qu’ils possèdent',['sur leur mode de déplacement','sur leur milieu de vie','sur ce qu’ils mangent'],'Les attributs partagés traduisent des liens de parenté ; le mode de vie, non.',1],
   ['La chauve-souris a des poils et allaite ses petits. Elle appartient aux…','mammifères',['oiseaux','insectes','arachnides'],'Poils et mamelles : ce sont les attributs des mammifères. Voler n’est pas un critère de classification.',1],
   ['L’araignée a huit pattes articulées. Est-ce un insecte ?','non, c’est un arachnide (mais c’est un arthropode comme les insectes)',['oui, comme toutes les petites bêtes','oui, car elle a des pattes articulées','non, c’est un mollusque'],'Les insectes ont six pattes ; les arachnides en ont huit. Tous deux sont des arthropodes.',2],
   ['Quel classement indique des liens de parenté ?','le classement en groupes emboîtés selon les attributs partagés',['le classement « comestible / non comestible »','le classement selon le milieu de vie','le classement par ordre alphabétique'],'Seuls les attributs partagés, hérités d’un ancêtre commun, traduisent la parenté.',2],
   ['À quoi sert une clé de détermination ?','à identifier le nom d’une espèce',['à montrer les liens de parenté','à classer les espèces selon leur âge','à fabriquer un arbre généalogique'],'Une clé de détermination pose des questions successives pour trouver le nom d’un être vivant.',2],
   ['Le manchot ne vole pas. Fait-il partie des oiseaux ?','oui, car il possède des plumes',['non, car il ne vole pas','non, c’est un mammifère marin','non, c’est un poisson'],'Le critère est l’attribut « plumes », pas la capacité de voler.',2],
   ['Dans un arbre de parenté, que représente un nœud (point de séparation des branches) ?','un ancêtre commun aux espèces situées au-dessus',['une espèce actuelle','une espèce disparue sans descendants','le milieu de vie'],'Chaque nœud représente un ancêtre commun ayant transmis les attributs du groupe.',3],
   ['Pourquoi l’être humain et le chimpanzé sont-ils de proches parents ?','ils partagent de nombreux attributs hérités d’un ancêtre commun récent',['l’être humain descend du chimpanzé','ils vivent dans les mêmes milieux','ils ont le même nom de genre'],'Ils ont un ancêtre commun ; aucun ne descend de l’autre.',3],
   ['Le groupe « animaux qui volent » est-il un groupe scientifique ?','non, il mélange des êtres vivants éloignés (oiseaux, chauves-souris, insectes)',['oui, car voler est un attribut','oui, c’est le groupe des oiseaux','non, car tous les animaux volent'],'Voler est une manière de vivre, pas un attribut hérité commun : ce groupe n’indique pas de parenté.',3],
   {tf:'Les mammifères sont inclus dans le groupe des tétrapodes, lui-même inclus dans celui des vertébrés.',v:true,e:'Les groupes sont emboîtés : tout mammifère a quatre membres et un squelette interne.',d:2}]),3])},

{id:'svt6d',name:'Biodiversité actuelle et passée',icon:'🦋',domain:'Biodiversité',
 refs:[REF6,E6('Le vivant, sa diversité et les fonctions qui le caractérisent — Biodiversité actuelle et passée')],
 tip:'Ne confonds pas le nombre d’ESPÈCES (diversité) et le nombre d’INDIVIDUS (abondance) : 100 pâquerettes = 1 seule espèce.',
 c:C(`Dans une haie, on peut compter des dizaines d’espèces d’insectes, d’oiseaux et de plantes ; dans une pelouse tondue, beaucoup moins. Et il y a 70 millions d’années, des dinosaures vivaient là où nous sommes. Qu’appelle-t-on la <b>biodiversité</b>, et comment a-t-elle changé au cours de l’histoire de la Terre ?`,
  [T('La biodiversité aujourd’hui',`<p>La <b>biodiversité</b> désigne la diversité du vivant : la diversité des <b>espèces</b> dans un milieu, la diversité des <b>milieux</b> (forêt, mare, prairie…) et la diversité des <b>individus au sein d’une même espèce</b> (couleur, taille : c’est la diversité intraspécifique).</p><p>Une <b>espèce</b> regroupe des individus qui se ressemblent et qui peuvent se reproduire entre eux en donnant une descendance fertile. Pour connaître la biodiversité d’un lieu, on réalise un <b>inventaire</b> et on identifie les espèces avec une <b>clé de détermination</b>. Le nombre d’espèces mesure la diversité ; le nombre d’individus mesure l’abondance.</p>`),
   T('La biodiversité du passé',`<p>Les <b>fossiles</b> sont des restes ou des traces d’êtres vivants conservés dans les roches. Ils montrent que la biodiversité a beaucoup changé : des espèces sont apparues, d’autres ont disparu.</p><p>L’histoire de la Terre se mesure en <b>temps géologiques</b> (millions d’années) : la Terre s’est formée il y a environ 4,6 milliards d’années ; les premières traces de vie datent d’environ 3,5 milliards d’années ; les dinosaures non volants ont disparu il y a 66 millions d’années, lors d’une <b>crise biologique</b> (extinction massive) ; notre espèce, <i>Homo sapiens</i>, n’existe que depuis environ 300 000 ans. Il faut distinguer ce temps très long de l’échelle de l’histoire humaine.</p>`)],
  [{q:'Relevé dans une mare : 12 grenouilles vertes, 30 gerris, 5 tritons palmés, 30 nénuphars. Combien d’espèces ?',s:['On compte les noms différents, pas les individus.','Espèces : grenouille verte, gerris, triton palmé, nénuphar.','Il y a 4 espèces (et 77 individus en tout).']}],
  ['Je fais l’inventaire des êtres vivants du milieu.','J’identifie chaque espèce avec une clé de détermination.','Je compte séparément le nombre d’espèces et le nombre d’individus.','Pour le passé, je place fossiles et événements sur une échelle des temps.'],
  ['Confondre le nombre d’individus et le nombre d’espèces.','Croire que les êtres humains ont côtoyé les dinosaures non volants : 66 millions d’années les séparent.','Penser que deux individus d’aspect différent (chiens de races différentes) sont deux espèces : ils peuvent se reproduire entre eux, c’est la même espèce.'],
  ['La biodiversité, c’est la diversité des espèces, des milieux et des individus d’une même espèce.','Une espèce = des individus qui peuvent se reproduire entre eux avec une descendance fertile.','Les fossiles montrent que la biodiversité change : apparitions, disparitions, crises biologiques.','Les temps géologiques se comptent en millions d’années ; Homo sapiens est très récent.']),
 g:mix([d=>{const pool=['grenouilles vertes','gerris','tritons palmés','nénuphars','libellules','escargots','pâquerettes','coccinelles','fourmis','merles','orties','cloportes'];const sp=pickN(pool,R(3,d===1?4:6));const n=sp.map(()=>R(1,d===1?9:40));const tot=n.reduce((a,b)=>a+b,0);
    const list=sp.map((s,i)=>`${n[i]} ${s}`).join(', ');
    if(Math.random()<.5)return num(`Inventaire d’un milieu : ${list}. Combien d’<b>espèces</b> différentes a-t-on trouvées ?`,sp.length,{expl:`On compte les espèces différentes, pas les individus : <b>${sp.length} espèces</b> (pour ${tot} individus).`,hint:'Compte les noms différents.'});
    return num(`Inventaire d’un milieu : ${list}. Combien d’<b>individus</b> a-t-on comptés au total ?`,tot,{expl:`${n.join(' + ')} = <b>${tot} individus</b>, répartis en ${sp.length} espèces.`,hint:'Additionne les effectifs.'});},3],
  [d=>{const a=R(3,9),b=R(3,9);if(a===b)return ch('Deux relevés ont le même nombre d’espèces. Que peut-on dire de leur diversité spécifique ?','elle est identique',['la première est plus élevée','la seconde est plus élevée','on ne peut jamais comparer'],{expl:'La diversité des espèces se compare par le nombre d’espèces.'});
    return ch(`Une haie abrite <b>${a} espèces</b> (${a*12} individus) ; une pelouse tondue abrite <b>${b} espèces</b> (${b*30} individus). Quel milieu a la plus grande diversité d’espèces ?`,a>b?'la haie':'la pelouse',[a>b?'la pelouse':'la haie','les deux sont égales'],{expl:`La diversité se mesure au nombre d’espèces : ${Math.max(a,b)} > ${Math.min(a,b)}. Le nombre d’individus mesure seulement l’abondance.`,hint:'Compare le nombre d’espèces, pas d’individus.'});},2],
  [seqs([['Histoire de la vie sur Terre',['formation de la Terre (4,6 milliards d’années)','premières traces de vie (vers 3,5 milliards d’années)','premiers vertébrés (vers 500 millions d’années)','apparition des dinosaures (vers 230 millions d’années)','disparition des dinosaures non volants (66 millions d’années)','apparition d’Homo sapiens (vers 300 000 ans)']]]),2],
  [bank([['Qu’est-ce qu’un fossile ?','un reste ou une trace d’être vivant conservé dans une roche',['un être vivant très âgé','une roche en forme d’animal fabriquée par l’être humain','un squelette actuel'],'Coquilles, os, empreintes de pas ou de feuilles conservés dans les roches sont des fossiles.',1],
   ['Deux chiens de races très différentes peuvent avoir des chiots fertiles. Ils appartiennent…','à la même espèce',['à deux espèces différentes','à deux groupes sans parenté','à des genres différents'],'Pouvoir se reproduire et avoir une descendance fertile définit l’espèce ; les différences de race relèvent de la diversité intraspécifique.',2],
   ['Que mesure le nombre d’espèces différentes dans un milieu ?','la diversité spécifique',['l’abondance','la taille du milieu','l’âge du milieu'],'Le nombre d’espèces mesure la diversité ; le nombre d’individus mesure l’abondance.',1],
   ['Qu’appelle-t-on une crise biologique ?','la disparition d’un grand nombre d’espèces en peu de temps à l’échelle géologique',['l’apparition d’une nouvelle espèce','une maladie d’un seul individu','un hiver très froid'],'Exemple : il y a 66 millions d’années, de très nombreuses espèces dont les dinosaures non volants ont disparu.',2],
   ['Les êtres humains ont-ils vu des dinosaures non volants vivants ?','non, car 66 millions d’années séparent leur disparition de l’apparition d’Homo sapiens',['oui, au temps des cavernes','oui, il y a 10 000 ans','on ne le sait pas'],'Homo sapiens n’existe que depuis environ 300 000 ans.',2],
   ['Des coquillages fossiles marins sont trouvés au sommet d’une colline. Que peut-on en déduire ?','la région était autrefois recouverte par la mer',['les oiseaux les ont transportés','ils sont tombés du ciel','la colline est un ancien volcan'],'On reconstitue un paléoenvironnement : ces animaux vivaient dans la mer à cet endroit.',3],
   ['Des coccinelles d’une même espèce ont des taches de nombres différents. Il s’agit…','de diversité au sein d’une même espèce (diversité intraspécifique)',['de plusieurs espèces','d’une maladie','d’individus de groupes sans parenté'],'Les individus d’une même espèce ne sont pas tous identiques.',3],
   ['Quelle durée est la plus grande ?','l’âge de la Terre (environ 4,6 milliards d’années)',['l’existence d’Homo sapiens (environ 300 000 ans)','le temps depuis la disparition des dinosaures non volants (66 millions d’années)','l’histoire écrite de l’humanité (environ 5 000 ans)'],'4,6 milliards d’années, c’est 4 600 millions d’années : bien plus que toutes les autres durées.',3],
   {tf:'Une pelouse avec 2 000 pâquerettes est plus riche en espèces qu’une haie avec 25 espèces différentes.',v:false,e:'2 000 pâquerettes, c’est une seule espèce : la haie a une diversité bien plus grande.',d:2}]),3])},

{id:'svt6e',name:'Cycles de vie et développement des êtres vivants',icon:'🐛',domain:'Reproduction et développement',
 refs:[REF6,E6('Le vivant, sa diversité et les fonctions qui le caractérisent — Cycle de vie et reproduction des êtres vivants')],
 tip:'Un cycle de vie se lit comme une boucle : naissance → croissance (et développement) → reproduction → nouvelle génération. Repère si le jeune ressemble ou non à l’adulte.',
 c:C(`La chenille qui dévore une feuille deviendra un papillon ; le têtard qui nage dans la mare deviendra une grenouille ; le gland tombé du chêne deviendra un arbre. Comment un être vivant passe-t-il de l’œuf ou de la graine à l’adulte capable de se reproduire ? C’est son <b>cycle de vie</b>.`,
  [T('Les étapes d’un cycle de vie',`<p>Tout être vivant naît, grandit (<b>croissance</b> : augmentation de taille et de masse), se transforme (<b>développement</b>), se reproduit, vieillit puis meurt. La reproduction fait naître une nouvelle génération : le cycle recommence.</p><p>Chez une plante à fleurs : graine → germination → plantule → plante adulte → fleurs → fruits contenant des graines. Chez un animal : œuf (ou cellule-œuf) → embryon → jeune (ou larve) → adulte.</p>`),
   T('Développement direct ou métamorphose',`<p>Quand le jeune ressemble à l’adulte en plus petit (chat, poule, escargot), le développement est <b>direct</b>. Quand le jeune (appelé <b>larve</b>) est très différent de l’adulte, il subit une <b>métamorphose</b> : têtard → grenouille ; chenille → chrysalide (nymphe) → papillon.</p><p>Les arthropodes (insectes, crustacés) ont un squelette externe rigide : pour grandir, ils doivent le remplacer, c’est la <b>mue</b>. Le criquet, par exemple, grandit par mues successives, la larve ressemblant déjà un peu à l’adulte.</p>`),
   T('Pondre ou porter ses petits',`<p>Les animaux <b>ovipares</b> pondent des œufs qui se développent hors du corps de la mère (oiseaux, la plupart des poissons, des insectes). Les animaux <b>vivipares</b> gardent l’embryon dans leur corps jusqu’à la naissance (la plupart des mammifères).</p><p>Chez l’être humain, la fécondation est <b>interne</b> ; l’embryon puis le fœtus se développent dans l’<b>utérus</b> pendant environ 9 mois et reçoivent nutriments et dioxygène de la mère par le <b>placenta</b>, qui rejette aussi leurs déchets dans le sang maternel.</p>`)],
  [{q:'Une plantule mesure 12 mm le lundi et 40 mm le vendredi suivant (4 jours plus tard). Quelle est sa croissance moyenne par jour ?',s:['Croissance totale : 40 − 12 = 28 mm.','Durée : 4 jours.','Croissance moyenne : 28 ÷ 4 = 7 mm par jour.']}],
  ['Je repère l’œuf ou la graine de départ.','Je décris les formes successives (larve, nymphe, jeune, plantule…).','Je repère si le jeune ressemble à l’adulte (développement direct) ou non (métamorphose).','Je termine le cycle par la reproduction qui produit une nouvelle génération.'],
  ['Croire que la chenille et le papillon sont deux espèces différentes : ce sont deux formes du même animal.','Oublier que les plantes aussi ont un cycle de vie avec naissance (germination), croissance, reproduction et mort.','Penser que tous les animaux pondent des œufs : la plupart des mammifères sont vivipares.'],
  ['Un cycle de vie : naissance, croissance, développement, reproduction, vieillissement, mort.','Développement direct : le jeune ressemble à l’adulte ; métamorphose : la larve est très différente.','Ovipare : pond des œufs ; vivipare : l’embryon se développe dans le corps de la mère.','Chez l’être humain, le placenta assure les échanges entre la mère et le fœtus.']),
 g:mix([d=>{const rate=R(2,d===1?5:12),days=R(2,d===1?4:10),h1=R(5,30),h2=h1+rate*days;return num(`Une plantule mesure <b>${h1} mm</b> au jour 0 et <b>${h2} mm</b> ${days} jours plus tard. Quelle est sa croissance moyenne par jour ?`,rate,{unit:'mm/jour',expl:`(${h2} − ${h1}) ÷ ${days} = ${h2-h1} ÷ ${days} = <b>${rate} mm par jour</b>.`,hint:'Calcule la croissance totale, puis divise par le nombre de jours.'});},2],
  [seqs([['Cycle de vie du papillon',['œuf','chenille (larve)','chrysalide (nymphe)','papillon adulte']],['Cycle de vie de la grenouille',['œuf','têtard sans pattes','têtard avec pattes','jeune grenouille','grenouille adulte']],['Cycle de vie d’une plante à fleurs',['graine','germination','plantule','plante adulte','fleur','fruit contenant des graines']],['Développement humain',['fécondation','cellule-œuf','embryon','fœtus','naissance','enfant']]]),3],
  [S({'développement direct (le jeune ressemble à l’adulte)':['le chat','la poule','l’escargot','le lézard'],'métamorphose (larve très différente de l’adulte)':['le papillon','la grenouille','la coccinelle','le moustique']},'Comment se développe « %s » ?',{'développement direct (le jeune ressemble à l’adulte)':'Le jeune a déjà la forme de l’adulte et grandit.','métamorphose (larve très différente de l’adulte)':'La larve change profondément de forme pour devenir adulte.'}),2],
  [S({'ovipare':['la poule','la truite','le criquet','la tortue'],'vivipare':['le chat','la vache','l’être humain','le dauphin']},'Cet animal, « %s », est-il ovipare ou vivipare ?',{'ovipare':'Il pond des œufs qui se développent hors du corps de la mère.','vivipare':'L’embryon se développe dans le corps de la mère.'}),2],
  [bank([['Comment appelle-t-on la transformation d’une larve en adulte très différent ?','la métamorphose',['la mue','la germination','la fécondation'],'Exemple : têtard → grenouille, chenille → papillon.',1],
   ['Comment un criquet grandit-il malgré son squelette externe rigide ?','par des mues successives',['par métamorphose complète','en perdant ses pattes','il ne grandit pas'],'À chaque mue, il abandonne son ancien squelette externe et en fabrique un plus grand.',2],
   ['Chez l’être humain, quel organe permet les échanges entre la mère et le fœtus ?','le placenta',['l’estomac','le poumon du fœtus','l’ovaire'],'Le placenta apporte au fœtus nutriments et dioxygène et évacue ses déchets vers le sang maternel.',2],
   ['Quelle est la première étape de la vie d’une plante issue d’une graine ?','la germination',['la floraison','la pollinisation','la fructification'],'La graine germe : la jeune plantule sort et commence à grandir.',1],
   ['Combien de temps dure environ la grossesse chez l’être humain ?','environ 9 mois',['environ 3 mois','environ 2 ans','environ 21 jours'],'La grossesse humaine dure environ 9 mois (environ 38 semaines après la fécondation).',1],
   ['Pourquoi dit-on que le cycle de vie est un « cycle » ?','parce que la reproduction produit une nouvelle génération qui recommence les mêmes étapes',['parce que l’animal tourne en rond','parce que chaque individu vit éternellement','parce que les saisons reviennent'],'Les descendants repassent par les mêmes étapes que leurs parents.',2],
   ['La chrysalide du papillon semble immobile. Que s’y passe-t-il ?','l’organisme se transforme profondément pour devenir un papillon',['l’animal est mort','il pond des œufs','il hiberne sans changer'],'Pendant la nymphose, les organes de la larve sont réorganisés en organes d’adulte.',3],
   ['Un têtard vit dans l’eau et respire par des branchies ; la grenouille adulte vit aussi sur terre. Que montre cet exemple ?','la métamorphose s’accompagne d’un changement de mode de vie',['le têtard est une autre espèce','la grenouille est un poisson','les branchies apparaissent chez l’adulte'],'La larve et l’adulte ont des milieux et des organes différents.',3],
   {tf:'Tous les mammifères sont vivipares.',v:false,e:'Quelques mammifères, comme l’ornithorynque, pondent des œufs : on dit « la plupart des mammifères sont vivipares ».',d:3}]),3])},

{id:'svt6f',name:'Reproduction des plantes à fleurs',icon:'🌸',domain:'Reproduction et développement',
 refs:[REF6,E6('Le vivant, sa diversité et les fonctions qui le caractérisent — Cycle de vie (pollinisation)')],
 tip:'Retiens la transformation : après la pollinisation et la fécondation, l’OVAIRE devient le FRUIT et les OVULES deviennent les GRAINES.',
 c:C(`Au printemps, les cerisiers se couvrent de fleurs et les abeilles s’y activent ; en été, on récolte des cerises. Quel lien y a-t-il entre la fleur, l’abeille et le fruit ? Et pourquoi la diminution des insectes pollinisateurs inquiète-t-elle les agriculteurs ?`,
  [T('La fleur, organe de la reproduction',`<p>Une fleur comprend des <b>sépales</b> (protection du bouton), des <b>pétales</b> (souvent colorés, ils attirent les insectes), des <b>étamines</b> qui produisent le <b>pollen</b> (partie mâle) et un <b>pistil</b> (partie femelle) formé du <b>stigmate</b> et de l’<b>ovaire</b> qui contient les <b>ovules</b>.</p><p>La <b>pollinisation</b> est le transport du pollen des étamines jusqu’au pistil d’une fleur de la même espèce, par le vent ou par des animaux (abeilles, bourdons, papillons…). Ensuite a lieu la <b>fécondation</b>.</p>`),
   T('De la fleur au fruit, du fruit à la graine',`<p>Après la fécondation, les pétales et les étamines fanent ; l’<b>ovaire</b> se transforme en <b>fruit</b> et les <b>ovules</b> deviennent des <b>graines</b>. Sans pollinisation, pas de fruit (sauf cas particuliers).</p><p>Les graines sont ensuite <b>dispersées</b> (dissémination) : par le vent (pissenlit, érable), par les animaux qui mangent les fruits ou les transportent accrochés à leur pelage (cerise, bardane), par l’eau (noix de coco). Une graine qui germe donne une nouvelle plante.</p>`),
   T('Une coopération menacée',`<p>Entre la plante et l’insecte pollinisateur existe une <b>coopération</b> (relation mutualiste) : l’insecte trouve de la nourriture (nectar, pollen) et la plante est pollinisée. Beaucoup de cultures (pommiers, fraisiers, colza…) dépendent des pollinisateurs.</p><p>Or le nombre de pollinisateurs diminue, notamment à cause de certains <b>pesticides</b>, de la disparition des haies et des fleurs sauvages. Moins de pollinisateurs signifie moins de fruits et de graines récoltés.</p>`)],
  [{q:'Expérience : on enferme 40 fleurs de fraisier dans des sacs en tulle fin (les insectes ne passent pas) et on laisse 40 fleurs libres. Fruits obtenus : 6 et 34. Que conclure ?',s:['Seule différence : l’accès des insectes aux fleurs.','Fleurs libres : 34 fruits sur 40 = 85 % ; fleurs ensachées : 6 sur 40 = 15 %.','Les insectes pollinisateurs sont nécessaires à la formation de la plupart des fruits.']}],
  ['Je repère les organes de la fleur et leur rôle (mâle, femelle, attraction, protection).','Je suis le trajet du pollen : étamine → pistil (pollinisation), puis fécondation.','Je relie : ovaire → fruit, ovule → graine.','Dans une expérience, je compare un lot témoin et un lot test qui ne diffèrent que par un seul facteur.'],
  ['Confondre pollinisation (transport du pollen) et fécondation (union qui a lieu ensuite dans l’ovule).','Croire que le fruit vient des pétales : il vient de l’ovaire.','Penser que l’abeille « aide » volontairement la plante : elle cherche sa nourriture, la pollinisation est une conséquence.'],
  ['Étamines → pollen (mâle) ; pistil → ovaire et ovules (femelle).','Pollinisation = transport du pollen vers le pistil, par le vent ou les animaux.','Après fécondation : ovaire → fruit ; ovules → graines.','La plante et le pollinisateur coopèrent ; certains pesticides menacent les pollinisateurs et les récoltes.']),
 g:mix([d=>{const N=P([20,25,40,50,100]),k=R(1,N-1);const p=rd(k/N*100);return num(`Sur <b>${N} fleurs</b> laissées accessibles aux insectes, <b>${k}</b> ont donné un fruit. Quel est le pourcentage de fleurs ayant donné un fruit ?`,p,{unit:'%',expl:`${k} ÷ ${N} × 100 = <b>${nf(p)} %</b>.`,hint:'Pourcentage = partie ÷ total × 100.'});},2],
  [d=>{const N=P([20,40,50]),a=R(Math.ceil(N*0.6),N),b=R(0,Math.floor(N*0.3));return ch(`On compare ${N} fleurs <b>libres</b> (${a} fruits) et ${N} fleurs <b>enfermées dans un sac de tulle</b> que les insectes ne traversent pas (${b} fruits). Que montre cette expérience ?`,'les insectes pollinisateurs favorisent la formation des fruits',['le tulle tue les fleurs','les fleurs n’ont pas besoin des insectes','le vent est le seul pollinisateur'],{expl:`Le seul facteur qui change est l’accès des insectes : ${a} fruits contre ${b}. Les insectes, en transportant le pollen, permettent la formation des fruits.`,hint:'Quelle est la seule différence entre les deux lots ?'});},2],
  [pairs([['les étamines','production du pollen (partie mâle)'],['le stigmate','réception du pollen au sommet du pistil'],['les pétales','attraction des insectes par la couleur et l’odeur'],['les sépales','protection de la fleur en bouton'],['l’ovaire','transformation en fruit après la fécondation'],['les ovules','transformation en graines après la fécondation']],{q:'Quel est le rôle de cette partie de la fleur : « %s » ?',rq:'Quelle partie de la fleur assure cette fonction : « %s » ?'}),2],
  [S({'par le vent':['le pissenlit','l’érable','le pollen de graminées'],'par les animaux':['la cerise mangée par un merle','la bardane accrochée au pelage','le gland enterré par un geai'],'par l’eau':['la noix de coco']},'Comment se fait la dispersion dans le cas de « %s » ?',{'par le vent':'Ces graines ou ce pollen sont légers, parfois munis d’ailes ou d’aigrettes.','par les animaux':'Les animaux transportent le fruit ou la graine, dans leur tube digestif ou accrochés à eux.','par l’eau':'Le fruit flotte et peut voyager sur la mer.'}),1],
  [seqs([['De la fleur à la nouvelle plante',['fleur épanouie','pollinisation','fécondation','ovaire transformé en fruit','dispersion des graines','germination']]]),1],
  [bank([['Qu’est-ce que la pollinisation ?','le transport du pollen des étamines jusqu’au pistil',['la transformation de l’ovaire en fruit','la germination de la graine','la chute des pétales'],'La pollinisation précède la fécondation.',1],
   ['Que devient l’ovaire après la fécondation ?','le fruit',['la graine','la racine','le pollen'],'L’ovaire grossit et devient le fruit ; les ovules qu’il contient deviennent les graines.',1],
   ['Que reçoit l’abeille en échange de la pollinisation ?','de la nourriture : nectar et pollen',['un abri pour l’hiver','de l’eau salée','rien du tout'],'C’est une coopération : chacun des deux partenaires en tire un bénéfice.',2],
   ['Pourquoi certains agriculteurs installent-ils des ruches dans leurs vergers ?','pour augmenter la pollinisation et donc la production de fruits',['pour protéger les arbres du froid','pour éloigner les oiseaux','pour fertiliser le sol'],'Plus de pollinisateurs = plus de fleurs pollinisées = plus de fruits.',2],
   ['Quelle conséquence peut avoir l’usage de certains pesticides sur les vergers ?','une baisse des pollinisateurs, donc moins de fruits',['plus de fleurs','des fruits plus gros','aucune conséquence'],'Certains pesticides tuent ou affaiblissent les insectes pollinisateurs.',3],
   ['Dans une expérience, pourquoi garde-t-on un lot de fleurs libres à côté des fleurs ensachées ?','c’est le témoin : il permet de comparer en ne changeant qu’un seul facteur',['pour avoir plus de fruits à manger','pour attirer les insectes dans les sacs','parce que le sac est trop petit'],'Le lot témoin montre le résultat dans les conditions normales.',3],
   ['Une tomate contient de nombreuses graines. Que peut-on en déduire ?','l’ovaire de la fleur contenait de nombreux ovules',['la fleur avait de nombreux pétales','elle provient de plusieurs fleurs','elle a été pollinisée par le vent'],'Chaque graine provient d’un ovule fécondé.',3],
   {tf:'Le fruit provient des pétales de la fleur.',v:false,e:'Le fruit provient de l’ovaire du pistil ; les pétales fanent et tombent.',d:1}]),3])},

{id:'svt6g',name:'Écosystèmes : relations entre les êtres vivants',icon:'🦊',domain:'Écosystèmes',
 refs:[REF6,E6('La Terre, une planète peuplée par des êtres vivants — Écosystème et chaînes alimentaires')],
 tip:'Dans une chaîne alimentaire, la flèche se lit « est mangé par » et va du mangé vers le mangeur. Le premier maillon est toujours un végétal chlorophyllien.',
 c:C(`Dans une forêt, le chêne nourrit les chenilles, les chenilles nourrissent les mésanges, l’épervier chasse les mésanges, et les feuilles mortes disparaissent peu à peu dans le sol. Toutes ces relations forment un <b>écosystème</b>. Comment fonctionne-t-il, et que se passe-t-il si l’on retire un maillon ?`,
  [T('Qu’est-ce qu’un écosystème ?',`<p>Un <b>écosystème</b> est formé d’un <b>milieu de vie</b> (sol, eau, climat : température, lumière, humidité…) et de l’ensemble des <b>êtres vivants</b> qui y vivent, en <b>interaction</b> entre eux et avec le milieu. Une mare, une haie, une forêt sont des écosystèmes.</p><p>La répartition des êtres vivants dépend des <b>facteurs physiques</b> du milieu : par exemple, les mousses poussent surtout dans les zones humides et ombragées. Les relations entre espèces sont variées : <b>prédation</b> (le renard mange le lapin), <b>coopération</b> (l’abeille et la fleur), <b>compétition</b> (deux espèces pour la même nourriture), <b>parasitisme</b> (la tique et le chevreuil).</p>`),
   T('Chaînes et réseaux alimentaires',`<p>Une <b>chaîne alimentaire</b> représente qui mange qui : herbe → lapin → renard (la flèche signifie « est mangé par »). Les végétaux chlorophylliens sont les <b>producteurs</b> : ils fabriquent leur propre matière à partir de la lumière, de l’eau, des sels minéraux et du dioxyde de carbone (production primaire). Les animaux sont des <b>consommateurs</b> : primaires (herbivores), secondaires, tertiaires.</p><p>Les chaînes s’entrecroisent en un <b>réseau alimentaire</b>. Après la mort, la matière organique est transformée par les <b>décomposeurs</b> (vers de terre, cloportes, champignons, bactéries) en matière minérale réutilisée par les végétaux : la matière circule en cycle.</p>`)],
  [{q:'Dans le réseau d’une haie, que se passe-t-il si les mésanges disparaissent ?',s:['Les mésanges mangent les chenilles et sont mangées par l’épervier.','Les chenilles, moins chassées, deviennent plus nombreuses et mangent plus de feuilles.','L’épervier manque de nourriture : sa population diminue ou il change de proie.']}],
  ['Je repère le producteur (végétal chlorophyllien) au début de la chaîne.','Je trace les flèches du mangé vers le mangeur.','Je nomme chaque niveau : producteur, consommateur primaire, secondaire…','Pour prévoir l’effet d’une disparition, je regarde qui mangeait l’espèce et ce qu’elle mangeait.'],
  ['Tracer la flèche dans le mauvais sens (« mange » au lieu de « est mangé par »).','Oublier les décomposeurs, qui recyclent la matière des êtres morts.','Croire que les végétaux se nourrissent de matière organique du sol : ils prélèvent de l’eau et des sels minéraux, et fabriquent leur matière grâce à la lumière.'],
  ['Écosystème = milieu de vie + êtres vivants + interactions.','Les végétaux sont des producteurs, à la base de toutes les chaînes alimentaires.','La flèche d’une chaîne alimentaire signifie « est mangé par ».','Les décomposeurs transforment la matière organique morte en matière minérale.']),
 g:mix([chaine,4],
  [S({'prédation':['le renard et le lapin','la coccinelle et le puceron','le héron et la grenouille'],'coopération (mutualisme)':['l’abeille et la fleur de pommier','l’algue et le champignon d’un lichen'],'compétition':['deux espèces d’oiseaux qui mangent les mêmes graines','deux arbres voisins qui cherchent la lumière'],'parasitisme':['la tique et le chevreuil','le gui et le pommier']},'Quelle relation existe entre « %s » ?',{'prédation':'L’un tue et mange l’autre.','coopération (mutualisme)':'Les deux partenaires tirent un bénéfice de la relation.','compétition':'Les deux utilisent la même ressource, qui devient moins disponible pour chacun.','parasitisme':'L’un vit aux dépens de l’autre sans le tuer rapidement.'}),2],
  [bank([['Quels êtres vivants sont toujours au début d’une chaîne alimentaire ?','les végétaux chlorophylliens (producteurs)',['les herbivores','les décomposeurs','les grands prédateurs'],'Seuls les végétaux chlorophylliens fabriquent leur matière à partir de matière minérale et de lumière.',1],
   ['Que signifie la flèche dans « herbe → lapin » ?','« est mangée par »',['« mange »','« vit à côté de »','« se transforme en »'],'L’herbe est mangée par le lapin : la flèche va du mangé vers le mangeur.',1],
   ['Quel est le rôle des vers de terre et des champignons du sol ?','décomposer la matière organique morte en matière minérale',['produire de la lumière','manger les renards','fabriquer de la chlorophylle'],'Ce sont des décomposeurs : ils recyclent la matière.',1],
   ['De quoi un écosystème est-il formé ?','d’un milieu de vie et des êtres vivants qui y vivent en interaction',['seulement des animaux d’une région','seulement des plantes','du climat uniquement'],'Milieu de vie + êtres vivants + interactions.',1],
   ['Dans un sous-bois sombre et humide, on trouve beaucoup de mousses ; sur une pelouse ensoleillée, presque pas. Quel facteur explique cette répartition ?','les facteurs physiques du milieu (lumière, humidité)',['la couleur des mousses','le hasard uniquement','la présence de renards'],'Chaque espèce vit là où les conditions physiques lui conviennent.',2],
   ['Que se passe-t-il si on supprime tous les décomposeurs d’une forêt ?','les feuilles mortes et cadavres s’accumulent et les végétaux manquent de sels minéraux',['les arbres poussent plus vite','rien ne change','les herbivores deviennent producteurs'],'Sans décomposeurs, la matière n’est plus recyclée en matière minérale.',3],
   ['Après un incendie, la végétation repousse peu à peu, puis les animaux reviennent. Que montre cet exemple ?','un écosystème évolue et peut se reconstituer, dans certaines limites',['un écosystème ne change jamais','les incendies créent de nouvelles espèces','les animaux ne reviennent jamais'],'Les écosystèmes sont dynamiques ; leur capacité de récupération a des limites.',3],
   ['Pourquoi dit-on qu’un réseau alimentaire est plus réaliste qu’une chaîne ?','parce qu’un être vivant mange souvent plusieurs espèces et est mangé par plusieurs autres',['parce qu’il contient moins d’espèces','parce qu’il ne contient pas de végétaux','parce qu’il n’a pas de flèches'],'Les chaînes s’entrecroisent : c’est le réseau alimentaire.',2],
   {tf:'Les plantes vertes prélèvent leur matière organique toute faite dans le sol.',v:false,e:'Elles prélèvent de l’eau et des sels minéraux et fabriquent leur matière organique grâce à la lumière et au CO₂.',d:2}]),3])},

{id:'svt6h',name:'La Terre, les paysages et le climat',icon:'🌍',domain:'Planète Terre',
 refs:[REF6,E6('La Terre, une planète peuplée par des êtres vivants — La Terre, une planète active qui abrite la vie')],
 tip:'Météo = le temps qu’il fait, ici et maintenant (heures, jours). Climat = la moyenne du temps sur au moins 30 ans dans une région.',
 c:C(`Il a neigé hier : le climat se refroidit-il ? Non : un jour de neige, c’est de la <b>météo</b>. Le <b>climat</b>, lui, se mesure sur des dizaines d’années, et il se réchauffe. Pourquoi la Terre est-elle la seule planète connue à abriter la vie, et comment l’activité humaine modifie-t-elle son climat ?`,
  [T('Une planète singulière et active',`<p>La Terre est la troisième planète du système solaire. À sa distance du Soleil, l’eau peut y être <b>liquide</b>. Son <b>atmosphère</b> filtre une partie des rayons dangereux et retient de la chaleur grâce à l’effet de serre naturel : la température moyenne est d’environ 15 °C. Eau liquide, atmosphère et température adaptée permettent la vie.</p><p>La Terre est <b>active</b> : activité interne (séismes, volcans) et externe (vents, courants océaniques, érosion par l’eau). Un <b>paysage</b> associe des composantes géologiques (roches, relief), biologiques (végétation, animaux) et humaines (villes, cultures, routes). Les sociétés exploitent des ressources liées à cette activité (roches pour construire, géothermie) et doivent se protéger des <b>risques naturels</b>.</p>`),
   T('Météo, climat et réchauffement',`<p>La <b>météorologie</b> décrit le temps qu’il fait en un lieu et à un moment donnés ; on la mesure avec un thermomètre, un pluviomètre, un anémomètre. Le <b>climat</b> est la moyenne de ces mesures sur au moins 30 ans.</p><p>Depuis la période préindustrielle (vers 1850), la température moyenne de la Terre a augmenté d’environ 1,1 °C (décennie 2011-2020). Ce réchauffement est dû à l’augmentation des <b>gaz à effet de serre</b> (dioxyde de carbone, méthane) émis par les activités humaines : combustion du charbon, du pétrole et du gaz, déforestation, élevage. Conséquences : fonte des glaciers, élévation du niveau de la mer, déplacement d’espèces vers le nord ou en altitude. On y répond par l’<b>atténuation</b> (réduire les émissions) et l’<b>adaptation</b> (se préparer aux changements).</p>`)],
  [{q:'Températures moyennes annuelles d’une ville : 12,0 °C ; 12,5 °C ; 13,0 °C ; 13,5 °C. Quelle est la moyenne ?',s:['On additionne : 12 + 12,5 + 13 + 13,5 = 51.','On divise par le nombre de valeurs : 51 ÷ 4.','Moyenne : 12,75 °C.']}],
  ['Je repère l’échelle de temps : quelques jours (météo) ou plusieurs décennies (climat).','Je lis les données (températures, glaciers, gaz à effet de serre) et je repère une tendance.','Je relie la tendance à sa cause, avec des arguments scientifiques.','Je distingue les actions d’atténuation et d’adaptation.'],
  ['Utiliser un hiver froid pour nier le réchauffement climatique : le climat se juge sur de longues périodes.','Confondre l’effet de serre naturel, indispensable à la vie, et son renforcement par les activités humaines.','Croire que le réchauffement n’a pas d’effet sur les êtres vivants : de nombreuses espèces changent de répartition.'],
  ['La Terre abrite la vie grâce à l’eau liquide, à son atmosphère et à une température adaptée.','Météo : temps qu’il fait sur quelques jours ; climat : moyenne sur au moins 30 ans.','Le réchauffement récent (environ +1,1 °C) est dû aux gaz à effet de serre émis par les activités humaines.','Atténuer = réduire les émissions ; s’adapter = se préparer aux conséquences.']),
 g:mix([d=>{const n=d===1?2:4;const base=R(110,140);const v=Array.from({length:n},()=>(base+R(-8,8))/10);const s=v.reduce((a,b)=>a+b,0);const m=rd(s/n);return num(`Températures moyennes relevées sur ${n} années : ${v.map(x=>nf(x)+' °C').join(' ; ')}. Calcule la moyenne.`,m,{unit:'°C',expl:`Somme : ${nf(rd(s))} ; ${nf(rd(s))} ÷ ${n} = <b>${nf(m)} °C</b>.`,hint:'Additionne les valeurs puis divise par leur nombre.'});},2],
  [d=>{const a=R(130,150)/10,b=rd(a+R(5,20)/10);return num(`La température moyenne d’une région était de ${nf(a)} °C sur la période 1951-1980 et de ${nf(b)} °C sur 1991-2020. De combien a-t-elle augmenté ?`,rd(b-a),{unit:'°C',expl:`${nf(b)} − ${nf(a)} = <b>${nf(rd(b-a))} °C</b>. On compare deux moyennes sur 30 ans : c’est une évolution du climat.`,hint:'Fais la différence entre les deux moyennes.'});},2],
  [S({'météo':['il pleut à Lyon ce matin','une tempête est annoncée pour demain','il a gelé cette nuit','le vent souffle à 60 km/h aujourd’hui'],'climat':['les étés méditerranéens sont chauds et secs','la température moyenne de la France a augmenté depuis 1900','il pleut en moyenne 800 mm par an en Bretagne','les hivers sont rigoureux en montagne']},'« %s » : est-ce une information de météo ou de climat ?',{'météo':'Elle décrit le temps qu’il fait à un moment et en un lieu donnés.','climat':'Elle décrit une moyenne ou une tendance sur de longues années.'}),2],
  [S({'atténuation':['prendre le vélo plutôt que la voiture','isoler les bâtiments','développer les énergies renouvelables','planter des forêts'],'adaptation':['construire des digues contre la montée de la mer','choisir des cultures qui supportent la sécheresse','végétaliser les villes contre les canicules']},'« %s » relève de…',{'atténuation':'Cette action réduit les émissions de gaz à effet de serre (ou en capte).','adaptation':'Cette action prépare à vivre avec les conséquences du réchauffement.'}),2],
  [bank([['Quelle est la place de la Terre dans le système solaire ?','la troisième planète à partir du Soleil',['la première','la cinquième','la plus éloignée'],'Mercure, Vénus, puis la Terre.',1],
   ['Quelle condition, liée à sa distance au Soleil, permet la vie sur Terre ?','la présence d’eau liquide',['l’absence d’atmosphère','une température de 100 °C','l’absence de jour et de nuit'],'Ni trop près ni trop loin du Soleil : l’eau peut y rester liquide.',1],
   ['Quel instrument mesure la quantité de pluie ?','le pluviomètre',['l’anémomètre','le thermomètre','le baromètre'],'Le pluviomètre recueille l’eau de pluie ; l’anémomètre mesure la vitesse du vent.',1],
   ['Quel gaz, rejeté par la combustion du pétrole et du charbon, renforce l’effet de serre ?','le dioxyde de carbone (CO₂)',['le dioxygène','le diazote','l’hélium'],'Le CO₂ est le principal gaz à effet de serre émis par les activités humaines.',1],
   ['Quels arguments montrent le réchauffement climatique récent ?','la hausse de la température moyenne mesurée et le recul des glaciers',['une journée très chaude en juillet','un hiver neigeux','la présence de nuages'],'Il faut des données sur de longues périodes : températures, glaciers, niveau de la mer.',2],
   ['Sans effet de serre naturel, la température moyenne de la Terre serait d’environ…','−18 °C',['+15 °C','+60 °C','0 °C exactement'],'L’effet de serre naturel retient de la chaleur : la moyenne est d’environ +15 °C au lieu de −18 °C.',3],
   ['Pourquoi certaines espèces de plantes de montagne montent-elles en altitude ?','parce que le réchauffement les pousse vers des zones plus fraîches',['parce que le sol devient plus fertile en haut','parce que les animaux les transportent','par hasard'],'Le réchauffement modifie la répartition des êtres vivants.',3],
   ['Dans un paysage, la rivière, la forêt et le village sont respectivement des composantes…','géologique (eau, relief), biologique et humaine',['humaine, géologique et biologique','biologiques toutes les trois','humaines toutes les trois'],'Un paysage associe des éléments naturels non vivants, vivants, et des aménagements humains.',3],
   {tf:'Un hiver particulièrement froid prouve que le climat ne se réchauffe pas.',v:false,e:'Une saison isolée relève de la météo ; le climat se juge sur au moins 30 ans.',d:2}]),3])}
]);

/* ===================== 5e (cycle 4) ===================== */
const AMI=[['de la salive',37,false,'La salive contient une enzyme (amylase) qui, à 37 °C (température du corps), transforme l’amidon en sucres plus petits : l’amidon a disparu.'],
  ['de la salive',5,true,'À 5 °C, l’enzyme de la salive est presque inactive : en 20 minutes, l’amidon n’est quasiment pas transformé.'],
  ['de l’eau',37,true,'L’eau seule ne contient aucune enzyme : l’amidon n’est pas transformé. C’est le tube témoin.'],
  ['de la salive préalablement bouillie',37,true,'L’ébullition a détruit l’enzyme de la salive : elle ne peut plus transformer l’amidon.'],
  ['de l’eau',5,true,'Sans enzyme, l’amidon reste présent quelle que soit la température.']];
const SEVE=[['éclairée','verte',true],['éclairée','blanche (sans chlorophylle)',false],['placée à l’obscurité','verte',false],['éclairée, mais privée de dioxyde de carbone','verte',false]];

MQ.add('svt','5',[
{id:'svt5a',name:'Digestion et devenir des aliments',icon:'🍽️',domain:'Corps humain',
 refs:[REF4,E4(TH3)+' — « Système digestif, digestion, absorption ; aliments et nutriments »'],
 tip:'Distingue bien l’ALIMENT (ce qu’on mange) et le NUTRIMENT (la petite molécule obtenue après digestion, qui passe dans le sang au niveau de l’intestin grêle).',
 c:C(`Un sandwich au jambon contient de l’amidon, des protéines et des lipides : ces grosses molécules ne peuvent pas passer telles quelles dans le sang. Que deviennent les aliments entre la bouche et l’intestin, et comment arrivent-ils jusqu’à nos muscles et à notre cerveau ?`,
  [T('Le tube digestif et les glandes digestives',`<p>Les aliments parcourent le <b>tube digestif</b> : bouche → œsophage → estomac → intestin grêle → gros intestin → anus. Des <b>glandes digestives</b> y déversent des sucs : glandes salivaires (salive), glandes de la paroi de l’estomac (suc gastrique), pancréas (suc pancréatique), foie (bile, qui aide à la digestion des graisses).</p><p>La digestion est d’abord <b>mécanique</b> (mastication par les dents, brassage par les muscles de l’estomac) puis <b>chimique</b> : les sucs digestifs contiennent des <b>enzymes</b> qui découpent les grosses molécules des aliments en petites molécules, les <b>nutriments</b>.</p>`),
   T('Des aliments aux nutriments, du tube digestif au sang',`<p>L’amidon est transformé en <b>glucose</b>, les protéines en <b>acides aminés</b>, les lipides en <b>acides gras</b> et glycérol. L’eau, les sels minéraux et les vitamines ne sont pas transformés.</p><p>Les nutriments traversent la paroi de l’<b>intestin grêle</b> et passent dans le <b>sang</b> : c’est l’<b>absorption</b>. Elle est très efficace car la paroi intestinale, plissée et couverte de <b>villosités</b>, possède une très grande surface et de nombreux vaisseaux sanguins. Le sang distribue ensuite les nutriments à toutes les cellules. Ce qui n’est pas digéré (fibres) est éliminé dans les selles. Des milliards de bactéries vivent dans l’intestin (<b>microbiote</b>) et participent à la digestion de certaines fibres.</p>`)],
  [{q:'Expérience : deux tubes d’empois d’amidon à 37 °C, l’un avec de la salive, l’autre avec de l’eau. Après 20 min, on ajoute de l’eau iodée. Interpréter.',s:['L’eau iodée colore l’amidon en bleu-noir.','Tube « eau » : bleu-noir, l’amidon est toujours là ; tube « salive » : pas de bleu-noir, l’amidon a disparu.','La salive contient une enzyme qui transforme l’amidon en sucres plus petits : c’est une digestion chimique.']}],
  ['Je suis le trajet des aliments dans le tube digestif.','Je repère la digestion mécanique puis chimique (enzymes des sucs digestifs).','Je relie chaque aliment au nutriment obtenu.','Je localise l’absorption (intestin grêle) et le transport par le sang.'],
  ['Croire que les aliments passent dans le foie ou le pancréas : ces glandes déversent leurs sucs dans le tube digestif, les aliments n’y passent pas.','Penser que la digestion se fait surtout dans l’estomac : elle s’achève dans l’intestin grêle, où a lieu l’absorption.','Confondre aliment et nutriment.'],
  ['Digestion mécanique (dents, muscles) + chimique (enzymes des sucs digestifs).','Amidon → glucose ; protéines → acides aminés ; lipides → acides gras et glycérol.','L’absorption des nutriments se fait dans l’intestin grêle, grâce à une très grande surface d’échange.','Le sang distribue les nutriments à toutes les cellules.']),
 g:mix([d=>{const [x,t,blue,why]=P(AMI);return ch(`Tube : empois d’amidon + <b>${x}</b>, placé à <b>${t} °C</b> pendant 20 minutes. On ajoute de l’eau iodée. Quel résultat obtient-on ?`,blue?'coloration bleu-noir : l’amidon est encore présent':'pas de coloration bleu-noir : l’amidon a disparu',[blue?'pas de coloration bleu-noir : l’amidon a disparu':'coloration bleu-noir : l’amidon est encore présent','coloration rouge brique : des protéines sont présentes'],{expl:why+' (L’eau iodée colore l’amidon en bleu-noir.)',hint:'Y a-t-il une enzyme active dans ce tube ?'});},3],
  [seqs([['Trajet des aliments dans le tube digestif',['bouche','œsophage','estomac','intestin grêle','gros intestin','anus']]]),2],
  [pairs([['l’amidon','glucose'],['les protéines','acides aminés'],['les lipides','acides gras et glycérol']],{q:'En quels nutriments la digestion transforme-t-elle %s ?'.replace('%s','« %s »'),rq:'De quel constituant des aliments proviennent ces nutriments : « %s » ?',oneWay:false}),2],
  [pairs([['les glandes salivaires','produisent la salive qui commence la digestion de l’amidon'],['l’estomac','brasse les aliments et produit le suc gastrique'],['le pancréas','déverse dans l’intestin un suc riche en enzymes'],['le foie','produit la bile qui aide à digérer les graisses'],['l’intestin grêle','achève la digestion et absorbe les nutriments'],['le gros intestin','réabsorbe de l’eau et forme les selles']],{q:'Quel est le rôle de cet organe : « %s » ?',rq:'Quel organe correspond à cette description : « %s » ?'}),2],
  [bank([['Comment appelle-t-on le passage des nutriments de l’intestin vers le sang ?','l’absorption',['la digestion','la respiration','l’excrétion'],'Les nutriments traversent la paroi de l’intestin grêle : c’est l’absorption.',1],
   ['Où se fait l’essentiel de l’absorption des nutriments ?','dans l’intestin grêle',['dans l’estomac','dans l’œsophage','dans le foie'],'La paroi de l’intestin grêle, très plissée et riche en vaisseaux sanguins, offre une immense surface d’échange.',1],
   ['Qu’est-ce qu’une enzyme digestive ?','une molécule des sucs digestifs qui découpe les aliments en nutriments',['un aliment très riche en sucre','une bactérie de l’intestin','un organe du tube digestif'],'Les enzymes réalisent la digestion chimique.',2],
   ['Pourquoi la grande surface de l’intestin grêle est-elle importante ?','elle augmente les échanges : plus de nutriments passent dans le sang',['elle ralentit la digestion','elle empêche les bactéries d’entrer','elle permet de respirer'],'Plis et villosités multiplient la surface d’absorption.',2],
   ['Les fibres des légumes ne sont pas digérées par nos enzymes. Que deviennent-elles ?','elles sont en partie utilisées par le microbiote puis éliminées dans les selles',['elles passent dans le sang','elles sont stockées dans le foie','elles deviennent des muscles'],'Les fibres facilitent le transit ; des bactéries intestinales en dégradent une partie.',3],
   ['Le pain mâché longtemps prend un goût sucré. Pourquoi ?','l’enzyme de la salive transforme l’amidon en sucres',['la salive contient du sucre','les dents fabriquent du sucre','le pain contient du sucre ajouté'],'C’est la première étape de la digestion chimique de l’amidon.',3],
   ['Pourquoi le tube « salive bouillie » sert-il de contrôle dans l’expérience sur l’amidon ?','il montre que c’est une substance détruite par la chaleur (une enzyme) qui agit',['il prouve que l’eau digère l’amidon','il accélère la réaction','il colore l’amidon'],'Si la salive bouillie n’agit plus, c’est que son agent actif a été détruit par la chaleur.',3],
   {tf:'Les aliments passent par le foie et le pancréas pendant la digestion.',v:false,e:'Le foie et le pancréas sont des glandes annexes : leurs sucs sont déversés dans l’intestin, mais les aliments n’y passent pas.',d:2},
   {tf:'L’eau, les sels minéraux et les vitamines passent dans le sang sans être digérés.',v:true,e:'Ce sont déjà de petites molécules : elles sont absorbées directement.',d:2}]),3])},

{id:'svt5b',name:'Respiration et échanges gazeux',icon:'🫁',domain:'Corps humain',
 refs:[REF4,E4(TH3)+' — « Rythmes cardiaque et respiratoire, et effort physique »',E4(TH2)+' — nutrition et organisation fonctionnelle'],
 tip:'Suis le dioxygène : air → alvéoles → sang → cellules. Le CO₂ fait le chemin inverse. Les échanges se font toujours là où la paroi est très fine.',
 c:C(`Pendant une course, tu respires plus vite et plus profondément. Pourquoi ? Que se passe-t-il entre l’air que tu inspires et celui que tu rejettes, et à quoi sert le dioxygène dans ton organisme ?`,
  [T('Ventilation et trajet de l’air',`<p>L’air entre par le nez ou la bouche, puis passe dans la <b>trachée</b>, les <b>bronches</b>, les <b>bronchioles</b> et arrive dans les <b>alvéoles pulmonaires</b>, de minuscules sacs à paroi très fine entourés de capillaires sanguins. L’<b>inspiration</b> est due à la contraction du <b>diaphragme</b> et des muscles entre les côtes qui augmentent le volume de la cage thoracique ; l’<b>expiration</b> suit leur relâchement.</p><p>À l’effort, la fréquence respiratoire et le volume d’air de chaque mouvement augmentent : le <b>débit ventilatoire</b> (volume d’air par minute = volume par mouvement × nombre de mouvements par minute) augmente.</p>`),
   T('Les échanges gazeux',`<p>L’air inspiré contient environ <b>21 % de dioxygène</b> (O₂) et 0,04 % de dioxyde de carbone (CO₂) ; l’air expiré environ 16 % d’O₂ et 4 % de CO₂. Dans les alvéoles, le dioxygène passe dans le sang, le dioxyde de carbone passe du sang dans l’air.</p><p>Le sang transporte le dioxygène jusqu’aux <b>cellules</b> ; elles l’utilisent avec les nutriments (glucose) pour produire l’énergie dont elles ont besoin, et rejettent du CO₂ (c’est la respiration cellulaire). D’autres animaux ont des organes adaptés à leur milieu : <b>branchies</b> (poissons, dans l’eau), <b>trachées</b> (insectes), <b>poumons</b> (mammifères, oiseaux). Le tabac (goudrons, monoxyde de carbone) abîme les alvéoles et réduit le transport du dioxygène.</p>`)],
  [{q:'Au repos, Inès inspire 0,5 L d’air par mouvement, 14 fois par minute. Pendant une course : 1,5 L, 30 fois par minute. Comparer les débits ventilatoires.',s:['Débit = volume par mouvement × fréquence.','Repos : 0,5 × 14 = 7 L/min ; course : 1,5 × 30 = 45 L/min.','Le débit est environ 6 fois plus grand à l’effort : les muscles reçoivent plus de dioxygène.']}],
  ['Je repère le trajet de l’air jusqu’aux alvéoles.','Je compare les compositions de l’air inspiré et expiré.','Je localise les échanges (alvéoles ↔ sang ↔ cellules).','Pour un calcul, j’utilise débit = volume × fréquence et je vérifie les unités.'],
  ['Croire qu’on expire seulement du CO₂ : l’air expiré contient encore environ 16 % de dioxygène.','Penser que les poumons « fabriquent » de l’énergie : ce sont les cellules qui l’utilisent pour produire de l’énergie.','Confondre respiration (échanges gazeux et utilisation du dioxygène) et ventilation (mouvements de l’air).'],
  ['L’air arrive dans les alvéoles, où le dioxygène passe dans le sang et le CO₂ en sort.','Les cellules utilisent le dioxygène et le glucose et rejettent du CO₂.','À l’effort, le débit ventilatoire augmente.','Branchies, trachées et poumons sont des organes respiratoires adaptés au milieu de vie.']),
 g:mix([d=>{const v=P([0.5,0.6,0.8,1,1.5,2]),f=R(d===1?12:10,d===1?20:40);const D=rd(v*f);return num(`Un élève inspire <b>${nf(v)} L</b> d’air par mouvement, à raison de <b>${f} mouvements par minute</b>. Quel est son débit ventilatoire ?`,D,{unit:'L/min',expl:`Débit = volume × fréquence = ${nf(v)} × ${f} = <b>${nf(D)} L/min</b>.`,hint:'Multiplie le volume d’un mouvement par le nombre de mouvements par minute.'});},3],
  [d=>{const k=R(6,d===1?10:25),s=P([15,20,30]);const f=k*60/s;return num(`On compte <b>${k} mouvements respiratoires en ${s} secondes</b>. Quelle est la fréquence respiratoire (mouvements par minute) ?`,f,{unit:'mouvements/min',expl:`1 min = 60 s = ${60/s} × ${s} s ; ${k} × ${60/s} = <b>${f} mouvements par minute</b>.`,hint:'Combien de fois y a-t-il '+s+' s dans une minute ?'});},2],
  [seqs([['Trajet de l’air inspiré',['nez ou bouche','trachée','bronches','bronchioles','alvéoles pulmonaires']],['Trajet du dioxygène',['air des alvéoles','paroi des alvéoles et des capillaires','sang','cellules des muscles']]]),2],
  [S({'branchies':['la truite','le têtard','la moule'],'trachées':['le criquet','l’abeille','le papillon'],'poumons':['le chat','le pigeon','la grenouille adulte','le dauphin']},'Quel organe respiratoire possède « %s » ?',{'branchies':'Lamelles très fines, riches en vaisseaux, qui prélèvent le dioxygène dissous dans l’eau.','trachées':'Tubes ramifiés qui apportent l’air directement aux organes.','poumons':'Organes creux où l’air arrive dans de nombreuses petites cavités.'}),2],
  [bank([['Quel gaz passe de l’air des alvéoles vers le sang ?','le dioxygène',['le dioxyde de carbone','la vapeur d’eau uniquement','le diazote uniquement'],'Le sang s’enrichit en dioxygène dans les poumons.',1],
   ['Quelle est la proportion approximative de dioxygène dans l’air inspiré ?','21 %',['78 %','4 %','0,04 %'],'L’air contient environ 21 % de dioxygène et 78 % de diazote.',1],
   ['Quel test met en évidence le CO₂ dans l’air expiré ?','l’eau de chaux qui se trouble',['l’eau iodée qui bleuit','le papier pH qui jaunit','la flamme qui s’éteint toujours'],'Le CO₂ trouble l’eau de chaux.',1],
   ['Quel muscle se contracte et s’abaisse à l’inspiration ?','le diaphragme',['le cœur','le biceps','l’estomac'],'En se contractant, le diaphragme agrandit la cage thoracique et l’air entre.',2],
   ['Pourquoi les échanges gazeux sont-ils efficaces dans les alvéoles ?','leur paroi est très fine, leur surface immense et elles sont entourées de capillaires',['elles sont épaisses et rigides','elles contiennent des aliments','elles sont peu nombreuses'],'Surface d’échange très grande + paroi très fine + sang abondant.',2],
   ['Pourquoi le débit ventilatoire augmente-t-il pendant l’effort ?','les muscles consomment plus de dioxygène et rejettent plus de CO₂',['les poumons grandissent','le sang s’arrête','pour refroidir le cerveau'],'L’augmentation de la ventilation répond aux besoins accrus des muscles.',2],
   ['L’air expiré contient environ 16 % de dioxygène. Que montre ce chiffre ?','une partie seulement du dioxygène inspiré est prélevée par le sang',['on n’utilise aucun dioxygène','tout le dioxygène est transformé en CO₂','le dioxygène est fabriqué par les poumons'],'21 % → 16 % : environ 5 points de dioxygène ont été prélevés.',3],
   ['Pourquoi le monoxyde de carbone de la fumée de cigarette est-il dangereux ?','il se fixe sur les globules rouges à la place du dioxygène',['il bouche les bronches comme un bouchon','il nourrit les cellules','il remplace le CO₂ dans l’air expiré'],'Le sang transporte alors moins de dioxygène vers les organes.',3],
   {tf:'Les cellules utilisent le dioxygène et le glucose pour produire de l’énergie et rejettent du dioxyde de carbone.',v:true,e:'C’est la respiration cellulaire.',d:2}]),3])},

{id:'svt5c',name:'Circulation du sang et transport dans l’organisme',icon:'❤️',domain:'Corps humain',
 refs:[REF4,E4(TH3)+' — « Rythmes cardiaque et respiratoire, et effort physique »',E4(TH2)+' — « rôle des systèmes de transport dans l’organisme »'],
 tip:'Artère = le sang PART du cœur ; veine = le sang REVIENT au cœur. Le côté gauche du cœur envoie le sang vers le corps, le côté droit vers les poumons.',
 c:C(`Ton cœur bat environ 70 fois par minute au repos, et bien plus pendant un sprint. Chaque battement propulse du sang dans un réseau de vaisseaux qui atteint chaque cellule. Comment ce sang circule-t-il, et que transporte-t-il ?`,
  [T('Le cœur, une double pompe',`<p>Le <b>cœur</b> est un muscle creux à quatre cavités : deux <b>oreillettes</b> en haut, deux <b>ventricules</b> en bas. Le cœur droit et le cœur gauche ne communiquent pas. Des <b>valvules</b> obligent le sang à circuler dans un seul sens.</p><p>La circulation est <b>double</b> : le ventricule droit envoie le sang vers les <b>poumons</b> (il s’y charge en dioxygène et se débarrasse du CO₂), puis il revient à l’oreillette gauche ; le ventricule gauche l’envoie par l’<b>aorte</b> vers tous les <b>organes</b>, puis il revient à l’oreillette droite par les veines caves.</p>`),
   T('Vaisseaux, sang et effort',`<p>Les <b>artères</b> conduisent le sang du cœur vers les organes ; les <b>veines</b> le ramènent au cœur ; les <b>capillaires</b>, très fins, permettent les échanges avec les cellules : dioxygène et nutriments sortent du sang, CO₂ et déchets y entrent.</p><p>Le sang est formé de <b>plasma</b> (liquide qui transporte nutriments, CO₂, déchets), de <b>globules rouges</b> (transport du dioxygène), de <b>globules blancs</b> (défense) et de <b>plaquettes</b> (coagulation). À l’effort, la <b>fréquence cardiaque</b> et le volume éjecté à chaque battement augmentent : le <b>débit cardiaque</b> (volume × fréquence) augmente et les muscles reçoivent plus de dioxygène et de glucose.</p>`)],
  [{q:'Au repos, le cœur de Noah bat 70 fois par minute et éjecte 70 mL par battement. Quel est son débit cardiaque ?',s:['Débit cardiaque = volume éjecté × fréquence.','70 mL × 70 = 4 900 mL par minute.','4 900 mL = 4,9 L : environ tout le volume de sang du corps passe dans le cœur chaque minute.']}],
  ['Je repère le sens de circulation grâce aux valvules.','Je distingue la circulation pulmonaire (cœur droit → poumons → cœur gauche) et la circulation générale (cœur gauche → organes → cœur droit).','Je localise les échanges au niveau des capillaires.','Pour un calcul : fréquence par minute, débit = volume × fréquence.'],
  ['Croire que les artères transportent toujours du sang riche en dioxygène : l’artère pulmonaire transporte du sang pauvre en dioxygène vers les poumons.','Penser que le sang « bleu » et le sang « rouge » sont deux sangs différents : c’est le même sang, plus ou moins chargé en dioxygène.','Confondre fréquence cardiaque (battements par minute) et débit cardiaque (volume par minute).'],
  ['Le cœur a quatre cavités ; le cœur droit et le cœur gauche ne communiquent pas.','Artères : du cœur vers les organes ; veines : des organes vers le cœur ; capillaires : échanges.','Circulation double : poumons d’une part, organes d’autre part.','À l’effort, fréquence et débit cardiaques augmentent pour mieux approvisionner les muscles.']),
 g:mix([d=>{const s=P([10,15,20,30]),k=R(Math.ceil((d===1?60:50)*s/60),Math.floor((d===1?90:180)*s/60)),f=k*60/s;
    return num(`On compte <b>${k} battements</b> en <b>${s} secondes</b>. Quelle est la fréquence cardiaque ?`,f,{unit:'battements/min',expl:`Une minute contient ${60/s} fois ${s} s : ${k} × ${60/s} = <b>${f} battements par minute</b>.`,hint:'Ramène le comptage à 60 secondes.'});},2],
  [d=>{const v=P([60,70,80,90,100,120]),f=P([60,65,70,75,80,100,120,150,180]);const Q=v*f/1000;return num(`Le cœur éjecte <b>${v} mL</b> de sang à chaque battement et bat <b>${f} fois par minute</b>. Quel est le débit cardiaque en litres par minute ?`,Q,{unit:'L/min',expl:`${v} × ${f} = ${nf(v*f)} mL/min = <b>${nf(Q)} L/min</b> (1 L = 1 000 mL).`,hint:'Volume × fréquence, puis conversion en litres.'});},3],
  [seqs([['Circulation pulmonaire puis générale',['oreillette droite','ventricule droit','artère pulmonaire','poumons','veines pulmonaires','oreillette gauche','ventricule gauche','aorte','organes']]]),2],
  [pairs([['les globules rouges','transportent le dioxygène'],['les globules blancs','défendent l’organisme contre les micro-organismes'],['les plaquettes','participent à la coagulation du sang'],['le plasma','transporte les nutriments, le CO₂ et les déchets'],['les capillaires','permettent les échanges entre le sang et les cellules'],['les valvules','empêchent le sang de refluer']],{q:'Quel est le rôle de cet élément : « %s » ?',rq:'Quel élément correspond à cette description : « %s » ?'}),2],
  [bank([['Comment appelle-t-on un vaisseau qui conduit le sang du cœur vers un organe ?','une artère',['une veine','un capillaire','une bronche'],'Les artères partent du cœur.',1],
   ['Quelle cavité du cœur envoie le sang vers tous les organes ?','le ventricule gauche',['le ventricule droit','l’oreillette droite','l’oreillette gauche'],'Le ventricule gauche, très musclé, propulse le sang dans l’aorte.',2],
   ['Où le sang se charge-t-il en dioxygène ?','dans les poumons',['dans le cœur','dans l’intestin','dans les muscles'],'Dans les capillaires des alvéoles pulmonaires.',1],
   ['Où le sang se charge-t-il en nutriments ?','au niveau de l’intestin grêle',['au niveau des poumons','dans le cœur','dans les reins'],'Les nutriments passent de l’intestin grêle dans le sang.',2],
   ['Pourquoi la fréquence cardiaque augmente-t-elle pendant un effort ?','pour apporter plus de dioxygène et de glucose aux muscles',['parce que le cœur se fatigue','pour refroidir le sang','pour digérer plus vite'],'Les muscles en activité consomment davantage : le débit sanguin augmente.',2],
   ['L’artère pulmonaire transporte un sang…','pauvre en dioxygène, du cœur vers les poumons',['riche en dioxygène, vers le corps','riche en nutriments, vers l’intestin','sans globules rouges'],'C’est une artère car elle part du cœur, mais elle transporte un sang pauvre en dioxygène.',3],
   ['Pourquoi dit-on que la circulation est « double » ?','le sang passe deux fois par le cœur : une fois pour les poumons, une fois pour les organes',['il y a deux cœurs','le sang circule dans les deux sens','il y a deux sortes de sang'],'Circulation pulmonaire + circulation générale.',3],
   ['Où ont lieu les échanges entre le sang et les cellules ?','dans les capillaires',['dans l’aorte','dans les oreillettes','dans les valvules'],'Leur paroi très fine laisse passer dioxygène, nutriments et déchets.',1],
   {tf:'Le cœur droit et le cœur gauche communiquent directement par un trou.',v:false,e:'Chez l’adulte, une cloison sépare complètement le cœur droit du cœur gauche.',d:2}]),3])},

{id:'svt5d',name:'Nutrition des végétaux chlorophylliens',icon:'🌿',domain:'Nutrition',
 refs:[REF4,E4(TH2)+' — « Relier les besoins des cellules d’une plante chlorophyllienne… »'],
 tip:'Une plante verte FABRIQUE sa matière organique : elle prend seulement de la matière minérale (eau, sels minéraux, CO₂) et utilise la lumière. Le test de l’amidon (eau iodée) révèle où elle en a fabriqué.',
 c:C(`Un chêne de 20 tonnes est sorti d’un petit gland. D’où vient toute cette matière ? Pas du sol, qui ne diminue presque pas autour de l’arbre ! Les végétaux chlorophylliens ont une façon de se nourrir très différente de celle des animaux.`,
  [T('Les besoins d’une plante verte',`<p>Une plante chlorophyllienne a besoin d’<b>eau</b> et de <b>sels minéraux</b>, puisés dans le sol par les <b>poils absorbants</b> des racines, de <b>dioxyde de carbone</b> (CO₂), qui entre par les <b>stomates</b> des feuilles, et de <b>lumière</b>, captée par la <b>chlorophylle</b> des chloroplastes.</p><p>À la lumière, les cellules chlorophylliennes fabriquent de la <b>matière organique</b> (sucres, puis amidon) à partir de cette matière minérale et rejettent du <b>dioxygène</b> : c’est la <b>photosynthèse</b>. La plante est un <b>producteur primaire</b>. Comme tous les êtres vivants, elle respire aussi, de jour comme de nuit.</p>`),
   T('Transport et stockage',`<p>La <b>sève brute</b> (eau + sels minéraux) monte des racines vers les feuilles dans des vaisseaux conducteurs. La <b>sève élaborée</b>, riche en sucres fabriqués dans les feuilles, est distribuée à tous les organes (racines, fleurs, fruits).</p><p>La plante <b>stocke</b> des réserves dans certains organes : amidon dans le tubercule de pomme de terre, sucre dans la racine de betterave, réserves dans les graines. Le test à l’<b>eau iodée</b> (coloration bleu-noir) révèle la présence d’amidon dans une feuille : on le trouve seulement dans les parties vertes et éclairées.</p>`)],
  [{q:'Une feuille de géranium est en partie recouverte d’un cache opaque pendant 48 h au soleil. Puis on la décolore et on la plonge dans l’eau iodée. Que prévoir ?',s:['Partie éclairée : la photosynthèse a lieu, de l’amidon est produit → coloration bleu-noir.','Partie sous le cache : pas de lumière, pas de photosynthèse → pas de bleu-noir.','Conclusion : la lumière est indispensable à la production de matière organique.']}],
  ['Je liste ce que la plante prélève (eau, sels minéraux, CO₂) et ce qu’elle utilise (lumière).','Je localise : racines (eau, sels minéraux), feuilles (CO₂, lumière, photosynthèse).','Je relie la sève brute et la sève élaborée à leurs trajets.','Dans une expérience, je compare la zone test et la zone témoin pour ne faire varier qu’un facteur.'],
  ['Croire que la plante « mange » la terre : la masse du sol ne diminue presque pas, la matière vient surtout de l’air (CO₂) et de l’eau.','Penser que les plantes ne respirent pas : elles respirent jour et nuit ; la photosynthèse s’y ajoute à la lumière.','Confondre sève brute (montante, minérale) et sève élaborée (riche en sucres).'],
  ['Besoins : eau, sels minéraux, CO₂ et lumière.','La photosynthèse produit de la matière organique et rejette du dioxygène, seulement à la lumière et dans les cellules chlorophylliennes.','Sève brute : racines → feuilles ; sève élaborée : feuilles → tous les organes.','L’amidon (bleu-noir à l’eau iodée) est stocké dans les feuilles et les organes de réserve.']),
 g:mix([d=>{const [lum,col,yes]=P(SEVE);return ch(`Une zone de feuille <b>${col}</b>, <b>${lum}</b> pendant 24 h, est testée à l’eau iodée après décoloration. Que observe-t-on ?`.replace('Que observe','Qu’observe'),yes?'une coloration bleu-noir : de l’amidon a été produit':'pas de coloration bleu-noir : pas d’amidon produit',[yes?'pas de coloration bleu-noir : pas d’amidon produit':'une coloration bleu-noir : de l’amidon a été produit','une coloration rouge : présence de dioxygène'],{expl:yes?'Avec chlorophylle, lumière, eau et CO₂, la photosynthèse fabrique des sucres stockés sous forme d’amidon.':'Il manque une condition de la photosynthèse (chlorophylle, lumière ou CO₂) : pas de production d’amidon.',hint:'La photosynthèse a besoin de chlorophylle, de lumière et de CO₂.'});},3],
  [d=>{const m1=R(2,9)*100,gain=R(20,80)*1000,soil=R(20,120);return ch(`Une jeune plante de ${m1} g est cultivée 5 ans dans un bac de terre, arrosée à l’eau. Elle pèse alors ${nf(m1+gain)} g ; la terre n’a perdu que ${soil} g. D’où vient l’essentiel de la matière gagnée ?`,'du CO₂ de l’air et de l’eau, transformés par photosynthèse',['de la terre','des sels minéraux uniquement','de la lumière transformée en matière'],{expl:`La plante a gagné ${nf(gain)} g alors que la terre n’a perdu que ${soil} g : la matière vient surtout du dioxyde de carbone et de l’eau, utilisés grâce à l’énergie lumineuse.`,hint:'Compare la masse gagnée et la masse perdue par la terre.'});},2],
  [pairs([['les poils absorbants','prélèvent l’eau et les sels minéraux du sol'],['les stomates','laissent entrer le CO₂ et sortir le dioxygène et la vapeur d’eau'],['les chloroplastes','captent la lumière grâce à la chlorophylle'],['la sève brute','transporte l’eau et les sels minéraux vers les feuilles'],['la sève élaborée','distribue les sucres fabriqués aux autres organes'],['le tubercule de pomme de terre','stocke des réserves d’amidon']],{q:'Quel est le rôle de cet élément : « %s » ?',rq:'Quel élément correspond à cette description : « %s » ?'}),2],
  [bank([['Quel gaz une plante verte rejette-t-elle à la lumière grâce à la photosynthèse ?','le dioxygène',['le dioxyde de carbone','le méthane','le diazote'],'La photosynthèse consomme du CO₂ et rejette du dioxygène.',1],
   ['Par où le dioxyde de carbone entre-t-il dans la plante ?','par les stomates des feuilles',['par les racines','par les fleurs','par l’écorce uniquement'],'Les stomates sont de petits orifices de l’épiderme des feuilles.',1],
   ['Quel réactif met en évidence l’amidon ?','l’eau iodée (coloration bleu-noir)',['l’eau de chaux','le sulfate de cuivre anhydre','la liqueur de Fehling'],'L’eau iodée colore l’amidon en bleu-noir.',1],
   ['Pourquoi dit-on que les végétaux chlorophylliens sont des producteurs primaires ?','ils fabriquent leur matière organique à partir de matière minérale',['ils produisent des fruits','ils mangent des animaux','ils vivent au début du printemps'],'Ils sont à la base de toutes les chaînes alimentaires.',2],
   ['Une plante placée à l’obscurité pendant une semaine…','ne fabrique plus de matière organique et utilise ses réserves',['grandit plus vite','fabrique plus d’amidon','ne respire plus'],'Sans lumière, pas de photosynthèse ; elle continue de respirer et puise dans ses réserves.',2],
   ['Une feuille panachée (vert et blanc) éclairée est testée à l’eau iodée. Où apparaît le bleu-noir ?','seulement dans les zones vertes',['seulement dans les zones blanches','partout','nulle part'],'Seules les cellules avec chlorophylle réalisent la photosynthèse.',3],
   ['Pourquoi trouve-t-on de l’amidon dans une racine de carotte qui ne voit jamais la lumière ?','la sève élaborée y apporte des sucres fabriqués dans les feuilles, qui y sont stockés',['la racine fait la photosynthèse','l’amidon vient du sol','l’amidon est fabriqué par l’eau'],'Les organes non chlorophylliens reçoivent la matière organique par la sève élaborée.',3],
   ['Une plante respire-t-elle la nuit ?','oui, elle respire jour et nuit',['non, jamais','seulement la nuit','seulement à la lumière'],'La respiration est permanente ; la photosynthèse n’a lieu qu’à la lumière.',2],
   {tf:'Une plante verte prélève dans le sol la matière organique dont elle est faite.',v:false,e:'Elle prélève eau et sels minéraux ; la matière organique est fabriquée dans les feuilles grâce à la lumière.',d:2}]),3])},

{id:'svt5e',name:'Micro-organismes, hygiène et santé',icon:'🦠',domain:'Santé',
 refs:[REF4,E4(TH3)+' — « Ubiquité, diversité et évolution du monde bactérien » ; « Mesures d’hygiène… action des antiseptiques et des antibiotiques »'],
 tip:'Antiseptique = sur la peau ou une plaie, il tue les microbes à l’extérieur. Antibiotique = médicament contre les BACTÉRIES seulement, jamais contre les virus.',
 c:C(`Il y a dans ton intestin plus de bactéries que de cellules dans tout ton corps, et la plupart sont utiles. Pourtant, d’autres micro-organismes provoquent des maladies. Comment distinguer les micro-organismes, comment entrent-ils dans l’organisme et comment s’en protéger ?`,
  [T('Un monde microbien partout',`<p>Les <b>micro-organismes</b> sont des êtres vivants visibles seulement au microscope. Les <b>bactéries</b> sont des cellules sans noyau qui se multiplient très vite par division (dans de bonnes conditions, certaines doublent leur nombre toutes les 20 minutes). Les <b>champignons microscopiques</b> comprennent les levures et les moisissures. Les <b>virus</b> ne sont pas des cellules : ils ne peuvent se multiplier qu’à l’intérieur de cellules qu’ils infectent.</p><p>Les micro-organismes sont présents partout (ubiquité) : air, eau, sol, peau, intestin. La plupart sont inoffensifs ou utiles (<b>microbiote</b> intestinal, fabrication du yaourt). Certains sont <b>pathogènes</b> : ils provoquent des maladies.</p>`),
   T('Contamination, infection et prévention',`<p>La <b>contamination</b> est l’entrée d’un micro-organisme pathogène dans l’organisme (plaie, voies respiratoires, aliments, eau, contact). L’<b>infection</b> est sa multiplication dans l’organisme.</p><p>Pour limiter la contamination : <b>hygiène</b> (lavage des mains au savon pendant 30 secondes, tousser dans son coude), <b>asepsie</b> (matériel stérile), <b>antiseptiques</b> (sur une plaie, ils tuent les micro-organismes). Contre une infection bactérienne, le médecin peut prescrire un <b>antibiotique</b>, inefficace contre les virus. Un mauvais usage favorise l’apparition de <b>bactéries résistantes</b>. La <b>vaccination</b> prépare l’organisme à se défendre.</p>`)],
  [{q:'Une bactérie se divise toutes les 20 minutes. Une plaie est contaminée par 10 bactéries. Combien sont-elles au bout d’une heure ?',s:['1 heure = 60 min = 3 périodes de 20 min.','À chaque période, le nombre double : 10 → 20 → 40 → 80.','Au bout d’1 heure : 80 bactéries (10 × 2³). D’où l’intérêt de désinfecter vite une plaie.']}],
  ['J’identifie le type de micro-organisme (bactérie, virus, champignon).','Je repère la voie de contamination.','Je choisis la bonne mesure : hygiène, antiseptique, antibiotique (bactéries seulement), vaccin (prévention).','Pour une multiplication, je compte le nombre de doublements.'],
  ['Prendre un antibiotique contre un rhume ou la grippe : ce sont des virus, l’antibiotique est inutile.','Croire que tous les microbes sont dangereux : la plupart sont inoffensifs ou utiles.','Confondre contamination (entrée) et infection (multiplication).'],
  ['Bactéries, champignons microscopiques et virus sont des micro-organismes ; les virus ne sont pas des cellules.','Contamination = entrée ; infection = multiplication dans l’organisme.','Hygiène, asepsie et antiseptiques limitent la contamination.','Les antibiotiques agissent seulement sur les bactéries ; leur mauvais usage crée des résistances.']),
 g:mix([d=>{const n0=P([1,2,5,10,100]),T0=P([20,30]),k=R(d===1?1:2,d===1?3:6);const t=k*T0;const N=n0*2**k;return num(`Une bactérie se divise toutes les <b>${T0} minutes</b>. On part de <b>${n0}</b> bactérie${n0>1?'s':''}. Combien y en a-t-il au bout de <b>${t} minutes</b> (si les conditions restent favorables) ?`,N,{expl:`${t} ÷ ${T0} = ${k} doublements : ${n0} × 2${'⁰¹²³⁴⁵⁶⁷⁸'[k]} = ${n0} × ${2**k} = <b>${nf(N)}</b>.`,hint:'Compte le nombre de doublements, puis multiplie par 2 autant de fois.'});},3],
  [S({'bactérie':['la salmonelle','le bacille de la tuberculose','le lactobacille du yaourt','le staphylocoque doré'],'virus':['le virus de la grippe','le VIH','le virus de la rougeole','le virus de la varicelle'],'champignon microscopique':['la levure de boulanger','la moisissure du pain','le champignon du « pied d’athlète »']},'« %s » est…',{'bactérie':'C’est une cellule sans noyau qui se multiplie par division.','virus':'Ce n’est pas une cellule : il se multiplie seulement dans les cellules qu’il infecte.','champignon microscopique':'C’est un champignon visible seulement au microscope (levure, moisissure).'}),2],
  [S({'antiseptique (sur la peau ou une plaie)':['désinfecter une écorchure','nettoyer la peau avant une piqûre'],'antibiotique (médicament)':['soigner une angine bactérienne','traiter une infection urinaire bactérienne'],'aucun des deux : ni antiseptique ni antibiotique':['soigner la grippe','guérir un rhume viral']},'Pour « %s », on utilise…',{'antiseptique (sur la peau ou une plaie)':'L’antiseptique tue les micro-organismes à la surface du corps.','antibiotique (médicament)':'L’antibiotique, prescrit par un médecin, agit contre les bactéries dans l’organisme.','aucun des deux : ni antiseptique ni antibiotique':'Ce sont des maladies virales : les antibiotiques n’agissent pas sur les virus.'}),2],
  [bank([['Les antibiotiques sont efficaces contre…','les bactéries',['les virus','tous les micro-organismes','les allergies'],'Les antibiotiques n’agissent pas sur les virus.',1],
   ['Combien de temps faut-il se laver les mains au savon pour qu’elles soient bien propres ?','environ 30 secondes',['2 secondes','10 minutes','le savon est inutile'],'Frotter 30 secondes, entre les doigts et sous les ongles, puis rincer et sécher.',1],
   ['Comment appelle-t-on l’entrée d’un micro-organisme pathogène dans l’organisme ?','la contamination',['l’infection','la vaccination','la digestion'],'L’infection est la multiplication qui suit.',1],
   ['Qu’est-ce qu’un micro-organisme pathogène ?','un micro-organisme capable de provoquer une maladie',['un micro-organisme utile','un médicament','un globule blanc'],'La plupart des micro-organismes ne sont pas pathogènes.',1],
   ['Pourquoi ne faut-il pas prendre d’antibiotiques « au cas où » ?','cela favorise l’apparition de bactéries résistantes',['cela rend les virus plus gentils','cela n’a aucune conséquence','cela vaccine contre toutes les maladies'],'Les bactéries résistantes survivent et se multiplient : les antibiotiques deviennent moins efficaces.',2],
   ['Pourquoi stérilise-t-on les instruments chirurgicaux ?','pour éviter de contaminer le patient (asepsie)',['pour les rendre plus brillants','pour soigner une infection déjà présente','pour tuer les virus dans le sang du patient'],'L’asepsie empêche l’entrée de micro-organismes.',2],
   ['Une plaie rouge, chaude et gonflée deux jours après une égratignure non nettoyée indique…','une infection : des micro-organismes s’y sont multipliés',['une guérison normale','une allergie au soleil','un manque de vitamines'],'Les micro-organismes entrés par la plaie se sont multipliés.',3],
   ['Pourquoi une contamination par quelques bactéries peut-elle devenir grave en quelques heures ?','les bactéries se multiplient très vite, leur nombre double régulièrement',['les bactéries grossissent','les bactéries fabriquent des virus','le sang les attire'],'Une croissance par doublements devient très rapide.',3],
   {tf:'Les virus sont des cellules sans noyau, comme les bactéries.',v:false,e:'Les virus ne sont pas des cellules : ils doivent infecter une cellule pour se multiplier.',d:2},
   {tf:'La plupart des bactéries de notre intestin sont utiles.',v:true,e:'Le microbiote participe à la digestion de certaines fibres et protège contre des pathogènes.',d:2}]),3])},

{id:'svt5f',name:'Puberté, reproduction humaine et respect de soi',icon:'🌱',domain:'Reproduction humaine',
 refs:[REF4,E4(TH3)+' — « Puberté, organes reproducteurs, production de cellules reproductrices, contrôles hormonaux »',REFEV],
 tip:'Classe chaque changement : caractère sexuel PRIMAIRE (organes reproducteurs, présents dès la naissance, qui deviennent fonctionnels) ou SECONDAIRE (apparaît à la puberté : pilosité, voix, seins…).',
 c:C(`Entre 10 et 16 ans environ, le corps se transforme : la taille augmente vite, la voix change, des poils apparaissent… Ces changements, appelés <b>puberté</b>, ne se produisent pas au même âge ni au même rythme chez tout le monde. Ils rendent l’organisme capable de se reproduire. Que se passe-t-il dans le corps ?`,
  [T('La puberté',`<p>La puberté commence généralement entre 8 et 13 ans chez les filles et entre 9 et 14 ans chez les garçons ; chacun a son propre rythme. Elle est déclenchée par le <b>cerveau</b>, qui commande aux organes reproducteurs (testicules, ovaires) de produire des <b>hormones</b> : surtout la <b>testostérone</b> chez le garçon, les <b>œstrogènes</b> et la <b>progestérone</b> chez la fille.</p><p>Apparaissent alors les <b>caractères sexuels secondaires</b> : poils sous les bras et au pubis, poussée de croissance ; chez la fille, développement des seins, élargissement du bassin, premières règles ; chez le garçon, mue de la voix, poils sur le visage, développement des muscles, premières éjaculations. Les <b>caractères sexuels primaires</b> (organes reproducteurs) existent dès la naissance et deviennent fonctionnels.</p>`),
   T('Les cellules reproductrices',`<p>Chez l’homme, à partir de la puberté, les <b>testicules</b> produisent en continu des millions de <b>spermatozoïdes</b> par jour, et ce toute la vie. Ils sont conduits par les spermiductes et mélangés à des liquides produits par la prostate et les vésicules séminales : c’est le <b>sperme</b>.</p><p>Chez la femme, les <b>ovaires</b> contiennent dès la naissance des réserves de follicules. À partir de la puberté et jusqu’à la ménopause (vers 50 ans), environ une fois par cycle (en moyenne 28 jours, mais c’est variable), un ovaire libère un <b>ovule</b> : c’est l’<b>ovulation</b>. Si l’ovule n’est pas fécondé, la couche superficielle de la muqueuse de l’<b>utérus</b> est éliminée avec un peu de sang : ce sont les <b>règles</b>, qui durent quelques jours.</p>`),
   T('De la fécondation à la naissance',`<p>La <b>fécondation</b> est la rencontre d’un spermatozoïde et d’un ovule, dans une <b>trompe</b> (oviducte) : elle donne une <b>cellule-œuf</b>. Celle-ci se divise et l’embryon s’implante dans la muqueuse de l’utérus (nidation). L’<b>embryon</b> puis le <b>fœtus</b> se développent pendant environ 9 mois ; le <b>placenta</b> assure les échanges avec le sang de la mère.</p><p>Chaque corps est unique et mérite le respect : les différences de rythme, de taille ou de morphologie sont normales. On respecte son intimité et celle des autres. Des règles très douloureuses justifient une consultation médicale ; l’infirmière scolaire ou un médecin peuvent répondre aux questions.</p>`)],
  [{q:'Pourquoi Léa, 11 ans, a-t-elle déjà ses règles alors que son amie Sarah, 13 ans, ne les a pas encore ?',s:['La puberté commence à des âges différents selon les personnes.','Elle est déclenchée par le cerveau, qui active la production d’hormones par les ovaires.','Les deux situations sont normales : chacune suit son propre rythme.']}],
  ['Je classe les changements : caractères sexuels primaires ou secondaires.','Je relie chaque organe reproducteur à sa fonction.','Je décris le trajet des cellules reproductrices jusqu’à la fécondation.','Je relie la grossesse aux échanges par le placenta.'],
  ['Croire que tout le monde doit changer au même âge : les rythmes de la puberté sont très variables.','Penser que les règles sont l’ovule qui sort : ce sont des débris de la muqueuse de l’utérus avec un peu de sang.','Situer la fécondation dans l’utérus : elle a lieu dans une trompe.'],
  ['La puberté est déclenchée par le cerveau et les hormones sexuelles ; elle rend capable de se reproduire.','Testicules : spermatozoïdes en continu dès la puberté ; ovaires : en général un ovule par cycle.','Fécondation dans la trompe → cellule-œuf → embryon → fœtus ; placenta = échanges avec la mère.','Chaque corps évolue à son rythme ; respect de soi, des autres et de l’intimité.']),
 g:mix([S({'caractère sexuel secondaire (apparaît à la puberté)':['la mue de la voix','l’apparition des poils pubiens','le développement des seins','la pousse de la barbe','l’élargissement du bassin'],'caractère sexuel primaire (présent dès la naissance)':['la présence de testicules','la présence d’ovaires','la présence d’un utérus']},'« %s » est…',{'caractère sexuel secondaire (apparaît à la puberté)':'Ce caractère apparaît à la puberté sous l’effet des hormones sexuelles.','caractère sexuel primaire (présent dès la naissance)':'C’est un organe reproducteur présent dès la naissance, qui devient fonctionnel à la puberté.'}),3],
  [pairs([['les testicules','produisent les spermatozoïdes et la testostérone'],['les spermiductes','conduisent les spermatozoïdes'],['la prostate et les vésicules séminales','produisent le liquide qui forme le sperme avec les spermatozoïdes'],['les ovaires','libèrent les ovules et produisent des hormones'],['les trompes (oviductes)','accueillent l’ovule ; c’est le lieu de la fécondation'],['l’utérus','accueille et protège l’embryon puis le fœtus'],['le placenta','assure les échanges entre la mère et le fœtus']],{q:'Quel est le rôle de cet organe : « %s » ?',rq:'Quel organe correspond à cette description : « %s » ?'}),4],
  [seqs([['De la fécondation à la naissance',['fécondation dans la trompe','cellule-œuf','premières divisions','nidation dans l’utérus','embryon','fœtus','naissance']]]),2],
  [bank([['Qu’est-ce qui déclenche la puberté ?','le cerveau, qui active la production d’hormones par les testicules ou les ovaires',['l’alimentation uniquement','le sport','l’âge exact de 12 ans pour tous'],'Le cerveau envoie des messages hormonaux aux organes reproducteurs.',1],
   ['Où la fécondation a-t-elle lieu ?','dans une trompe (oviducte)',['dans l’ovaire','dans le vagin','dans le placenta'],'L’ovule libéré par l’ovaire est capté par la trompe, où peut avoir lieu la rencontre avec un spermatozoïde.',1],
   ['Quelle cellule résulte de la fécondation ?','la cellule-œuf',['le spermatozoïde','l’ovule','le fœtus'],'L’union d’un spermatozoïde et d’un ovule forme une cellule-œuf.',1],
   ['Combien de temps dure environ la grossesse chez la femme ?','environ 9 mois',['environ 4 mois','environ 28 jours','environ 2 ans'],'Environ 9 mois entre la fécondation et la naissance.',1],
   ['Que sont les règles ?','l’élimination de la couche superficielle de la muqueuse de l’utérus avec un peu de sang',['la sortie d’un ovule visible','une maladie','l’élimination de l’urine'],'Elles se produisent lorsque l’ovule n’a pas été fécondé.',2],
   ['À partir de la puberté, les testicules produisent des spermatozoïdes…','en continu, toute la vie',['une fois par mois','seulement jusqu’à 20 ans','une fois par an'],'Contrairement aux ovaires, qui fonctionnent par cycles jusqu’à la ménopause.',2],
   ['Deux élèves de même âge sont à des stades différents de leur puberté. Que peut-on dire ?','c’est normal : chacun a son propre rythme',['l’un des deux est malade','l’un des deux doit consulter immédiatement','c’est impossible'],'La puberté commence et progresse à des âges différents selon les personnes.',2],
   ['Comment le fœtus reçoit-il le dioxygène et les nutriments ?','par le placenta, à partir du sang de sa mère',['en respirant le liquide amniotique','en mangeant par la bouche','par la peau de sa mère'],'Le placenta est le lieu des échanges entre le sang maternel et le sang du fœtus.',2],
   ['En moyenne, environ combien de fois un ovaire libère-t-il un ovule ?','environ une fois par cycle',['une fois par jour','une fois par an','des millions de fois par jour'],'En général un ovule par cycle (environ 28 jours en moyenne, durée variable).',3],
   ['Une adolescente a des règles très douloureuses chaque mois. Que lui conseiller ?','en parler et consulter un médecin ou l’infirmière scolaire',['ne rien dire, c’est forcément normal','arrêter de manger','attendre la ménopause'],'Des règles douloureuses nécessitent une consultation médicale.',3],
   ['Pourquoi la puberté rend-elle capable de se reproduire ?','les organes reproducteurs deviennent fonctionnels et produisent des cellules reproductrices',['la taille augmente','la voix devient plus grave','les poils apparaissent'],'Les caractères secondaires accompagnent la mise en fonctionnement des testicules ou des ovaires.',3],
   {tf:'La fécondation a lieu dans l’utérus.',v:false,e:'Elle a lieu dans une trompe ; l’embryon s’implante ensuite dans l’utérus.',d:2}]),4])},

{id:'svt5g',name:'Fonctionnement et dynamique des écosystèmes',icon:'🌲',domain:'Écosystèmes',
 refs:[REF4,E4(TH2)+' — « Dynamique des populations et paramètres d’influence »',E4(TH1)+' — écosystèmes et activités humaines'],
 tip:'L’effectif d’une population change avec 4 nombres : + naissances − morts + arrivées − départs. Pour les relations, demande-toi qui profite et qui est pénalisé.',
 c:C(`Dans une forêt du Canada, le nombre de lynx monte et descend régulièrement, en suivant celui des lièvres avec un peu de retard. Pourquoi les populations d’un écosystème varient-elles ainsi, et comment la matière circule-t-elle entre les êtres vivants ?`,
  [T('Populations et facteurs du milieu',`<p>Une <b>population</b> est l’ensemble des individus d’une même espèce vivant dans un même lieu. Son effectif varie selon les <b>naissances</b>, les <b>morts</b>, les <b>arrivées</b> et les <b>départs</b> d’individus.</p><p>Ces variations dépendent de <b>facteurs abiotiques</b> (non vivants : température, lumière, humidité, nature du sol) et de <b>facteurs biotiques</b> (les autres êtres vivants : nourriture disponible, prédateurs, concurrents, parasites). Par exemple, quand les lièvres abondent, les lynx bien nourris se reproduisent plus ; les lièvres, très chassés, diminuent ; puis les lynx, privés de nourriture, diminuent à leur tour.</p>`),
   T('Cycle de la matière et énergie',`<p>Les <b>producteurs</b> (végétaux chlorophylliens) fabriquent de la matière organique grâce à l’énergie de la <b>lumière</b>. Elle passe aux <b>consommateurs</b> par l’alimentation. Les <b>décomposeurs</b> (champignons, bactéries, petits animaux du sol) transforment la matière organique des cadavres, excréments et feuilles mortes en <b>matière minérale</b>, réutilisée par les végétaux : la matière <b>circule en cycle</b>.</p><p>L’énergie, elle, ne fait pas de cycle : elle entre sous forme de lumière et une grande partie est perdue (chaleur) à chaque niveau. Un écosystème est <b>dynamique</b> : après une perturbation (tempête, incendie), il se reconstitue progressivement, dans certaines limites.</p>`)],
  [{q:'Une population de 200 hérissons a eu 90 naissances et 70 morts dans l’année ; 15 individus sont arrivés et 5 sont partis. Quel est l’effectif final ?',s:['Effectif final = initial + naissances − morts + arrivées − départs.','200 + 90 − 70 + 15 − 5.','= 230 hérissons : la population a augmenté.']}],
  ['Je délimite la population étudiée (une espèce, un lieu).','Je fais le bilan naissances, morts, arrivées, départs.','Je cherche les facteurs abiotiques et biotiques qui expliquent les variations.','Je suis la matière : producteurs → consommateurs → décomposeurs → matière minérale.'],
  ['Croire qu’un prédateur fait disparaître sa proie : en général, les deux populations oscillent.','Oublier les décomposeurs dans le cycle de la matière.','Dire que l’énergie est recyclée comme la matière : elle est en grande partie dissipée sous forme de chaleur.'],
  ['Une population = individus d’une même espèce dans un même lieu.','Effectif final = initial + naissances − morts + arrivées − départs.','Facteurs abiotiques (milieu physique) et biotiques (autres êtres vivants) influencent les populations.','La matière circule en cycle grâce aux décomposeurs ; l’énergie vient du Soleil.']),
 g:mix([d=>{const N=R(5,40)*10,n=R(10,90),m=R(10,90),a=d===1?0:R(0,30),e=d===1?0:R(0,30);const F0=N+n-m+a-e;const sp=P(['hérissons','mésanges','lapins','grenouilles','chevreuils','écureuils']);
    return num(`Une population de <b>${N} ${sp}</b> a connu en un an <b>${n} naissances</b> et <b>${m} morts</b>${d===1?'':`, <b>${a} arrivées</b> et <b>${e} départs</b>`}. Quel est l’effectif à la fin de l’année ?`,F0,{expl:`${N} + ${n} − ${m}${d===1?'':` + ${a} − ${e}`} = <b>${F0}</b>. La population a ${F0>N?'augmenté':F0<N?'diminué':'gardé le même effectif'}.`,hint:'Ajoute ce qui entre (naissances, arrivées), retire ce qui sort (morts, départs).'});},3],
  [S({'facteur abiotique':['la température','l’humidité du sol','la lumière','l’acidité de l’eau','la salinité de l’eau'],'facteur biotique':['la présence de prédateurs','la quantité de proies','un parasite','une espèce concurrente','la présence de pollinisateurs']},'« %s » est un…',{'facteur abiotique':'C’est une caractéristique physique ou chimique du milieu, non vivante.','facteur biotique':'Il est lié aux autres êtres vivants.'}),2],
  [bank([['Qu’est-ce qu’une population ?','l’ensemble des individus d’une même espèce dans un même lieu',['toutes les espèces d’une forêt','un groupe d’espèces apparentées','les êtres vivants d’un continent'],'Exemple : les lièvres d’une forêt.',1],
   ['Quels êtres vivants transforment la matière organique morte en matière minérale ?','les décomposeurs',['les producteurs','les prédateurs','les herbivores'],'Champignons, bactéries et petits animaux du sol.',1],
   ['Quelle est la source d’énergie de la plupart des écosystèmes ?','la lumière du Soleil',['la chaleur du sol','les décomposeurs','l’eau de pluie'],'Les producteurs captent l’énergie lumineuse.',1],
   ['Les lièvres deviennent très nombreux. Que devient ensuite la population de lynx ?','elle augmente, car la nourriture est abondante',['elle diminue aussitôt','elle disparaît','elle ne change jamais'],'Avec plus de proies, les prédateurs se nourrissent et se reproduisent mieux.',2],
   ['Les lynx deviennent très nombreux. Que devient ensuite la population de lièvres ?','elle diminue, car ils sont plus chassés',['elle augmente','elle ne change pas','elle devient prédatrice'],'La prédation augmente ; ensuite, les lynx manqueront de nourriture.',2],
   ['Pourquoi dit-on que la matière « circule en cycle » dans un écosystème ?','les décomposeurs la rendent sous forme minérale aux végétaux, qui la réutilisent',['elle disparaît à chaque niveau','elle vient uniquement de la pluie','les animaux fabriquent de la matière minérale'],'Producteurs → consommateurs → décomposeurs → matière minérale → producteurs.',2],
   ['Un hiver très rigoureux fait chuter une population d’oiseaux. Quel type de facteur est en cause ?','un facteur abiotique (la température)',['un facteur biotique','un prédateur','un parasite'],'La température est une caractéristique physique du milieu.',2],
   ['Pourquoi y a-t-il moins de prédateurs que de proies dans un écosystème ?','une grande partie de l’énergie est perdue à chaque niveau de la chaîne',['les prédateurs vivent moins longtemps','les proies sont plus grosses','par hasard'],'Chaque niveau ne transmet qu’une petite part de l’énergie reçue : il nourrit moins d’individus.',3],
   ['Après une tempête qui a abattu des arbres, de jeunes plantes de lumière poussent dans la trouée. Que montre cette observation ?','un écosystème est dynamique et se reconstitue après une perturbation',['la forêt est définitivement détruite','les tempêtes créent de nouvelles espèces','les arbres repoussent en une semaine'],'Les espèces se succèdent jusqu’à la reconstitution de la forêt, dans certaines limites.',3],
   {tf:'L’énergie est recyclée dans l’écosystème comme la matière.',v:false,e:'La matière circule en cycle ; l’énergie lumineuse est en grande partie dissipée sous forme de chaleur.',d:3}]),3])},

{id:'svt5h',name:'Risques naturels et prévention',icon:'🌋',domain:'Planète Terre',
 refs:[REF4,E4(TH1)+' — « Notions d’aléas, de vulnérabilité et de risque en lien avec les phénomènes naturels ; prévisions »'],
 tip:'Risque = aléa (le phénomène possible) × enjeux (les personnes et les biens exposés). Pas d’enjeux, pas de risque ; plus la population est vulnérable, plus le risque est grand.',
 c:C(`Un fort séisme dans un désert inhabité ne fait aucune victime ; un séisme plus faible sous une grande ville peut être une catastrophe. Pourquoi ? Parce que le <b>risque</b> ne dépend pas seulement du phénomène naturel, mais aussi des personnes et des biens exposés.`,
  [T('Aléa, enjeux, vulnérabilité, risque',`<p>L’<b>aléa</b> est un phénomène naturel possible, caractérisé par sa probabilité et son intensité : inondation, séisme, éruption volcanique, cyclone, tempête, glissement de terrain, avalanche. Les <b>enjeux</b> sont les personnes, les habitations, les routes, les activités qui peuvent être touchés. La <b>vulnérabilité</b> mesure la fragilité de ces enjeux (bâtiments non adaptés, population non informée).</p><p>Le <b>risque</b> naît de la rencontre d’un aléa et d’enjeux : risque = aléa × enjeux (et vulnérabilité). Un aléa fort dans une zone vide présente un risque faible ; un aléa même modéré dans une zone très peuplée et mal préparée présente un risque élevé.</p>`),
   T('Prévoir, prévenir, protéger',`<p>La <b>prévision</b> consiste à surveiller pour annoncer le phénomène : la carte de vigilance de Météo-France (vert, jaune, orange, rouge) pour les tempêtes, orages ou crues ; la surveillance des volcans (séismes, déformations du sol, gaz). On ne sait pas prévoir précisément la date d’un séisme.</p><p>La <b>prévention</b> réduit la vulnérabilité : information des populations, plans de prévention des risques (pas de construction en zone inondable), constructions parasismiques, exercices de mise en sécurité à l’école. La <b>protection</b> limite les effets : digues, bassins de rétention, filets et galeries contre les chutes de pierres. Les bons réflexes comptent : en cas d’inondation, monter en hauteur et ne pas aller chercher ses enfants à l’école (ils y sont pris en charge) ; pendant un séisme, s’abriter sous un meuble solide, loin des fenêtres.</p>`)],
  [{q:'Comparer le risque d’inondation pour deux villages au bord d’une même rivière : A, maisons construites en zone inondable ; B, maisons sur une butte et bassin de rétention en amont.',s:['L’aléa (crue de la rivière) est le même pour les deux villages.','A a des enjeux exposés et vulnérables ; B a réduit la vulnérabilité et protégé ses enjeux.','Le risque est plus élevé pour A : il dépend des enjeux et de leur vulnérabilité, pas seulement de l’aléa.']}],
  ['J’identifie l’aléa (quel phénomène, quelle intensité, quelle fréquence).','Je repère les enjeux exposés et leur vulnérabilité.','J’évalue le risque en combinant aléa et enjeux.','Je classe les mesures : prévision, prévention, protection.'],
  ['Confondre aléa et risque : un séisme dans un désert est un aléa fort mais un risque faible.','Croire qu’on peut prévoir la date exacte d’un séisme : on peut seulement connaître les zones à risque et s’y préparer.','Confondre prévision (annoncer) et prévention (réduire la vulnérabilité à l’avance).'],
  ['Aléa = phénomène naturel possible ; enjeux = personnes et biens exposés.','Risque = aléa × enjeux, aggravé par la vulnérabilité.','Prévision (vigilance, surveillance), prévention (information, règles de construction), protection (digues, filets).','Connaître les bons réflexes sauve des vies.']),
 g:mix([d=>{const ev=P(['une crue','un séisme','une éruption volcanique','une tempête','un glissement de terrain']);const al=P(['fort','faible']);const [lieu,enj]=P([['une région désertique sans habitants',0],['un village de quelques maisons',1],['une grande ville très peuplée',2]]);
    const r=enj===0||(al==='faible'&&enj===1)?'risque faible ou nul':al==='fort'&&enj===2?'risque fort (majeur)':'risque modéré';
    return ch(`On envisage <b>${ev}</b> d’aléa <b>${al}</b> dans <b>${lieu}</b>. Comment qualifier le risque ?`,r,['risque fort (majeur)','risque modéré','risque faible ou nul'].filter(x=>x!==r),{expl:enj===0?'Sans enjeux (personnes, biens), il n’y a pas ou très peu de risque, même si l’aléa est fort.':al==='faible'&&enj===1?'Aléa faible et enjeux limités : le risque est <b>faible</b>.':`Le risque combine l’aléa (${al}) et les enjeux (${enj===2?'très nombreux':'limités'}) : <b>${r}</b>.`,hint:'Risque = aléa × enjeux.'});},3],
  [S({'prévision':['la carte de vigilance météorologique','la surveillance d’un volcan par des capteurs','la mesure du niveau des rivières en amont'],'prévention':['interdire de construire en zone inondable','construire selon les normes parasismiques','faire des exercices de mise en sécurité à l’école','informer la population des bons réflexes'],'protection':['construire une digue','installer des filets contre les chutes de pierres','aménager un bassin de rétention des eaux']},'« %s » relève de…',{'prévision':'On surveille pour annoncer le phénomène à l’avance.','prévention':'On réduit à l’avance la vulnérabilité des personnes et des biens.','protection':'On construit un ouvrage qui limite les effets du phénomène.'}),3],
  [pairs([['l’aléa','phénomène naturel possible, caractérisé par sa probabilité et son intensité'],['les enjeux','personnes et biens exposés au phénomène'],['la vulnérabilité','fragilité des enjeux face au phénomène'],['le risque','rencontre d’un aléa et d’enjeux exposés']],{q:'Que désigne %s ?'.replace('%s','« %s »'),rq:'Quel mot désigne : « %s » ?'}),2],
  [bank([['Pendant un séisme, à l’intérieur, que faut-il faire ?','s’abriter sous un meuble solide, loin des fenêtres',['sortir en courant pendant les secousses','prendre l’ascenseur','se placer près d’une vitre'],'Se protéger des chutes d’objets ; on évacue après les secousses, sans ascenseur.',1],
   ['En cas d’inondation, faut-il aller chercher ses enfants à l’école ?','non, ils y sont pris en charge en sécurité',['oui, le plus vite possible en voiture','oui, à pied dans l’eau','seulement s’il pleut'],'Se déplacer expose au danger ; l’école applique son plan de mise en sécurité.',2],
   ['Peut-on prévoir la date exacte d’un séisme ?','non, mais on connaît les zones où ils sont probables',['oui, au jour près','oui, grâce à la météo','oui, en observant les animaux'],'On ne sait pas prévoir la date ; on se prépare par la prévention.',1],
   ['La vigilance « rouge » de Météo-France signifie…','un phénomène dangereux d’intensité exceptionnelle est prévu',['il fera beau','un phénomène habituel sans danger','la fin de l’alerte'],'Rouge : vigilance absolue, phénomène exceptionnel.',2],
   ['Pourquoi un même séisme fait-il plus de victimes dans une ville aux bâtiments fragiles ?','la vulnérabilité des enjeux y est plus grande',['l’aléa y est plus fort','la Terre tremble plus fort sous les villes','il n’y a pas de différence'],'Des constructions parasismiques réduisent la vulnérabilité.',2],
   ['Une tempête violente traverse l’océan sans toucher aucune côte ni aucun bateau. Le risque était…','très faible, car il n’y avait pas d’enjeux',['majeur','impossible à déterminer','fort, car l’aléa était fort'],'Sans enjeux exposés, l’aléa ne se traduit pas en risque.',3],
   ['Bétonner les sols d’une ville augmente le risque d’inondation. Pourquoi ?','l’eau ne s’infiltre plus et ruisselle rapidement vers les rivières',['le béton attire la pluie','le béton fait monter la mer','le béton fait fondre la neige'],'Les activités humaines peuvent aggraver l’aléa et la vulnérabilité.',3],
   {tf:'Un plan de prévention des risques peut interdire de construire dans une zone inondable.',v:true,e:'C’est une mesure de prévention qui évite d’exposer de nouveaux enjeux.',d:2}]),3])}
]);

/* ===================== 4e (cycle 4) ===================== */
const CHR=[['l’être humain',46],['le chimpanzé',48],['le chien',78],['le chat',38],['le cheval',64],['la vache',60],['la souris',40],['le rat',42],['la drosophile (mouche du vinaigre)',8],['le pois',14],['le maïs',20]];
const ATB=['amoxicilline','tétracycline','érythromycine','gentamicine','ciprofloxacine','céfotaxime'];

MQ.add('svt','4',[
{id:'svt4a',name:'La cellule, unité du vivant',icon:'🧫',domain:'Le vivant',
 refs:[REF4,E4(TH2)+' — « Nutrition et organisation fonctionnelle à l’échelle de l’organisme, des organes, des tissus et des cellules »'],
 tip:'Pour une taille réelle, DIVISE la taille sur l’image par le grossissement, puis convertis : 1 mm = 1 000 µm. Pour reconnaître une cellule, cherche d’abord le noyau, puis la paroi et les chloroplastes.',
 c:C(`Ton corps contient des dizaines de milliers de milliards de cellules, toutes issues d’une seule cellule-œuf. Une bactérie, elle, n’est faite que d’une cellule. Qu’ont en commun toutes ces cellules, comment fonctionnent-elles et comment se multiplient-elles ?`,
  [T('Une organisation commune',`<p>Tous les êtres vivants sont formés de <b>cellules</b> : c’est l’unité de structure du vivant. Toute cellule est limitée par une <b>membrane</b> et contient du <b>cytoplasme</b>. Chez les animaux, les végétaux et les champignons, elle possède un <b>noyau</b> qui contient l’information génétique (les chromosomes, faits d’ADN). Les bactéries n’ont pas de noyau.</p><p>Les cellules végétales ont en plus une <b>paroi</b> rigide, une grande <b>vacuole</b> et, dans les parties vertes, des <b>chloroplastes</b> où se réalise la photosynthèse. Dans un organisme pluricellulaire, des cellules semblables forment un <b>tissu</b> (tissu musculaire, nerveux…), les tissus forment des <b>organes</b>.</p>`),
   T('Une unité de fonctionnement',`<p>La cellule est aussi l’unité de <b>fonctionnement</b> du vivant : elle prélève dans son milieu des nutriments (glucose…) et du dioxygène, et rejette du dioxyde de carbone et des déchets. Dans les <b>mitochondries</b>, la respiration cellulaire utilise glucose et dioxygène pour produire l’énergie nécessaire à la cellule.</p><p>Toute cellule provient d’une autre cellule, par <b>division cellulaire</b> : une cellule « mère » donne deux cellules « filles » qui reçoivent la même information génétique. Les divisions permettent la croissance et le renouvellement des tissus (peau, sang). Les cellules sont très petites : on mesure leur taille en micromètres (1 µm = 0,001 mm), souvent entre 10 et 100 µm.</p>`)],
  [{q:'Combien de cellules de 25 µm de long faut-il aligner pour faire 1 mm ?',s:['1 mm = 1 000 µm.','1 000 ÷ 25 = 40.','Il faut 40 cellules : cela montre à quel point les cellules sont petites.']}],
  ['J’observe au plus faible grossissement, puis j’augmente.','Je repère les structures : membrane, cytoplasme, noyau ; paroi, vacuole, chloroplastes.','Je conclus sur le type de cellule (animale, végétale, bactérienne).','Pour les tailles, je divise par le grossissement et je convertis en µm.'],
  ['Croire que les cellules végétales n’ont pas de membrane : elles ont une membrane doublée d’une paroi.','Penser que toutes les cellules d’une plante ont des chloroplastes : les cellules des racines n’en ont pas.','Confondre division cellulaire (une cellule donne deux cellules) et croissance de la taille d’une cellule.'],
  ['La cellule est l’unité de structure et de fonctionnement du vivant.','Membrane, cytoplasme, noyau (sauf bactéries) ; + paroi, vacuole, chloroplastes chez les végétaux.','Les mitochondries produisent l’énergie de la cellule à partir de glucose et de dioxygène.','Toute cellule provient de la division d’une autre cellule.']),
 g:mix([d=>{const G=P([40,100,400,1000]);const real=P(G>=400?[5,10,20,25,40,50]:[20,50,100,200]);const img=rd(real*G/1000);return num(`Sur une photographie au grossissement <b>×${G}</b>, une cellule mesure <b>${nf(img)} mm</b>. Quelle est sa taille réelle ?`,real,{unit:'µm',expl:`${nf(img)} ÷ ${G} = ${nf(rd(img/G))} mm = <b>${real} µm</b> (1 mm = 1 000 µm).`,hint:'Divise par le grossissement, puis multiplie par 1 000 pour passer en µm.'});},3],
  [d=>{const s=P([10,20,25,40,50,100,125,200,250]);return num(`Combien de cellules de <b>${s} µm</b> faut-il aligner pour obtenir une longueur de <b>1 mm</b> ?`,1000/s,{expl:`1 mm = 1 000 µm ; 1 000 ÷ ${s} = <b>${1000/s} cellules</b>.`,hint:'Convertis 1 mm en µm.'});},2],
  [S({'présent dans les cellules animales et végétales':['la membrane','le cytoplasme','le noyau','les mitochondries'],'propre aux cellules végétales':['la paroi','les chloroplastes','la grande vacuole']},'Où trouve-t-on cet élément : « %s » ?',{'présent dans les cellules animales et végétales':'C’est un élément commun aux cellules des animaux et des végétaux.','propre aux cellules végétales':'C’est une particularité des cellules végétales.'}),2],
  [pairs([['la membrane','limite la cellule et contrôle les échanges avec le milieu'],['le noyau','contient l’information génétique (chromosomes)'],['les mitochondries','produisent l’énergie de la cellule par la respiration'],['les chloroplastes','réalisent la photosynthèse'],['la paroi','rigidifie et protège la cellule végétale'],['le cytoplasme','milieu intérieur où se déroulent de nombreuses réactions']],{q:'Quel est le rôle de cet élément : « %s » ?',rq:'Quel élément de la cellule correspond à cette description : « %s » ?'}),2],
  [bank([['Quelle est l’unité de structure commune à tous les êtres vivants ?','la cellule',['l’organe','le tissu','le noyau'],'Tous les êtres vivants sont faits d’une ou de plusieurs cellules.',1],
   ['Quel élément de la cellule contient l’information génétique ?','le noyau',['la membrane','la vacuole','la paroi'],'Le noyau contient les chromosomes, formés d’ADN.',1],
   ['Comment appelle-t-on un ensemble de cellules semblables qui assurent la même fonction ?','un tissu',['un organe','un appareil','un organisme'],'Exemple : le tissu musculaire.',1],
   ['D’où provient une nouvelle cellule ?','de la division d’une cellule préexistante',['de la transformation d’un nutriment','de la fusion de deux organes','elle apparaît spontanément'],'Toute cellule provient d’une autre cellule.',2],
   ['Quels échanges une cellule animale réalise-t-elle avec son milieu ?','elle prélève glucose et dioxygène, rejette CO₂ et déchets',['elle prélève CO₂ et rejette dioxygène','elle ne réalise aucun échange','elle prélève de la lumière'],'Ces échanges permettent la respiration cellulaire.',2],
   ['Une cellule de 2 µm, sans noyau, est observée dans un yaourt. C’est…','une bactérie',['une cellule végétale','un globule blanc','un neurone'],'Absence de noyau et très petite taille : caractéristiques d’une bactérie.',2],
   ['Les cellules de la racine d’une plante possèdent-elles des chloroplastes ?','non, car elles sont à l’obscurité dans le sol',['oui, comme toutes les cellules végétales','oui, mais ils sont rouges','seulement la nuit'],'Les chloroplastes se trouvent dans les cellules des parties vertes éclairées.',3],
   ['Une plaie se referme en quelques jours. Grâce à quoi ?','aux divisions des cellules de la peau autour de la plaie',['à la fusion des cellules mortes','au sang qui devient peau','à la croissance d’une seule cellule géante'],'Les divisions cellulaires assurent le renouvellement et la réparation des tissus.',3],
   {tf:'Une cellule fille issue d’une division reçoit la même information génétique que la cellule mère.',v:true,e:'Les chromosomes sont copiés puis répartis à l’identique.',d:3}]),3])},

{id:'svt4b',name:'Information génétique : premiers repères',icon:'🧬',domain:'Génétique',
 refs:[REF4,E4(TH2)+' — « Gamètes et patrimoine génétique chez les Vertébrés et les plantes à fleurs » ; « Expliquer sur quoi reposent la diversité et la stabilité génétique des individus »'],
 tip:'Dans une cellule du corps, les chromosomes vont PAR PAIRES (46 = 23 paires chez l’être humain) ; une cellule reproductrice n’en a qu’UN de chaque paire (23). La fécondation reforme les paires.',
 c:C(`Tu as peut-être les yeux de ta mère et le groupe sanguin de ton père, mais ta langue maternelle ne s’est pas transmise par les cellules ! Quels caractères sont héréditaires, et où se trouve l’information qui les détermine ?`,
  [T('Caractères héréditaires et environnement',`<p>Un <b>caractère héréditaire</b> est transmis des parents aux enfants : groupe sanguin, couleur naturelle des yeux, forme du lobe de l’oreille. D’autres caractères dépendent de l’<b>environnement</b> ou du mode de vie : bronzage, musculature, langue parlée, cicatrices. Souvent, un caractère dépend des deux (la taille dépend de l’hérédité et de l’alimentation).</p><p>L’information génétique se trouve dans le <b>noyau</b> des cellules, sur les <b>chromosomes</b>, formés d’une longue molécule d’<b>ADN</b>. Une portion de chromosome qui détermine un caractère s’appelle un <b>gène</b>. Toutes les cellules d’un individu (sauf les cellules reproductrices) contiennent la même information génétique.</p>`),
   T('Le caryotype et la transmission',`<p>Le <b>caryotype</b> est la photographie des chromosomes d’une cellule, rangés par paires et par taille. Chez l’être humain, il y a <b>46 chromosomes</b>, soit <b>23 paires</b> : 22 paires identiques dans les deux sexes et une paire de <b>chromosomes sexuels</b> (XX chez la femme, XY chez l’homme). Chaque espèce a un nombre de chromosomes caractéristique (chien : 78 ; pois : 14).</p><p>Les <b>cellules reproductrices</b> (spermatozoïdes, ovules) ne contiennent qu’<b>un chromosome de chaque paire</b> : 23 chez l’être humain. À la fécondation, la cellule-œuf reçoit 23 chromosomes du père et 23 de la mère : elle retrouve 46 chromosomes. Un ovule porte toujours un chromosome X ; un spermatozoïde porte un X ou un Y, ce qui détermine le sexe génétique de l’enfant. Une anomalie du nombre de chromosomes (par exemple trois chromosomes 21 : trisomie 21) modifie le développement.</p>`)],
  [{q:'Le chat a 38 chromosomes dans ses cellules. Combien de chromosomes ont ses spermatozoïdes, et combien en aura la cellule-œuf ?',s:['Les cellules du corps ont des paires : 38 = 19 paires.','Un spermatozoïde reçoit un chromosome de chaque paire : 19 chromosomes.','La cellule-œuf reçoit 19 + 19 = 38 chromosomes : le nombre de l’espèce est conservé.']}],
  ['Je repère si le caractère est héréditaire, lié à l’environnement, ou les deux.','Je localise l’information : noyau → chromosomes → ADN → gènes.','Je compte les chromosomes par paires (cellule du corps) ou un par paire (cellule reproductrice).','Je vérifie que la fécondation rétablit le nombre de l’espèce.'],
  ['Croire que les cellules reproductrices ont 46 chromosomes : elles n’en ont que 23 chez l’être humain.','Penser que plus une espèce est « évoluée », plus elle a de chromosomes : le chien en a 78, l’être humain 46.','Croire que tous les caractères sont héréditaires : le bronzage ou une langue apprise ne le sont pas.'],
  ['L’information génétique est portée par les chromosomes (ADN) du noyau ; un gène est une portion de chromosome.','Être humain : 46 chromosomes = 23 paires, dont une paire sexuelle (XX ou XY).','Cellules reproductrices : un chromosome de chaque paire (23) ; la fécondation rétablit 46.','Les caractères dépendent de l’hérédité et souvent aussi de l’environnement.']),
 g:mix([d=>{const [sp,n]=P(CHR.filter(x=>d===1?x[0]==='l’être humain'||x[1]<=48:true));const k=R(0,2);
    if(k===0)return num(`Les cellules du corps ${deN(sp)} contiennent <b>${n} chromosomes</b>. Combien de chromosomes contient une de ses cellules reproductrices ?`,n/2,{expl:`Une cellule reproductrice reçoit un chromosome de chaque paire : ${n} ÷ 2 = <b>${n/2}</b>.`,hint:'Les chromosomes vont par paires dans les cellules du corps.'});
    if(k===1)return num(`Combien de <b>paires</b> de chromosomes y a-t-il dans une cellule du corps ${deN(sp)} (${n} chromosomes) ?`,n/2,{expl:`${n} chromosomes rangés par paires : ${n} ÷ 2 = <b>${n/2} paires</b>.`,hint:'Une paire = 2 chromosomes.'});
    return num(`Chez ${sp}, un spermatozoïde (ou un grain de pollen) apporte <b>${n/2}</b> chromosomes et une cellule reproductrice femelle en apporte autant. Combien de chromosomes aura la cellule-œuf ?`,n,{expl:`${n/2} + ${n/2} = <b>${n}</b> : la fécondation rétablit le nombre de chromosomes de l’espèce.`,hint:'Additionne les apports des deux parents.'});},4],
  [S({'caractère héréditaire':['le groupe sanguin','la couleur naturelle des yeux','la forme du lobe de l’oreille','la couleur naturelle des cheveux'],'caractère lié à l’environnement':['le bronzage','une cicatrice','la langue parlée','des muscles développés par l’entraînement']},'« %s » est surtout…',{'caractère héréditaire':'Il est déterminé par l’information génétique transmise par les parents.','caractère lié à l’environnement':'Il est acquis au cours de la vie et n’est pas transmis par les cellules reproductrices.'}),2],
  [bank([['Où se trouvent les chromosomes dans une cellule ?','dans le noyau',['dans la membrane','dans le cytoplasme seulement','dans les mitochondries uniquement'],'Les chromosomes, porteurs de l’information génétique, sont dans le noyau.',1],
   ['De quelle molécule les chromosomes sont-ils formés ?','l’ADN',['le glucose','l’amidon','l’hémoglobine'],'Chaque chromosome contient une très longue molécule d’ADN.',1],
   ['Qu’est-ce qu’un gène ?','une portion de chromosome qui détermine un caractère',['une cellule reproductrice','un organe','un chromosome entier'],'Un chromosome porte de nombreux gènes.',1],
   ['Quelle paire de chromosomes sexuels possède un homme ?','XY',['XX','YY','il n’en a pas'],'Femme : XX ; homme : XY.',1],
   ['Comment appelle-t-on la photographie des chromosomes rangés par paires ?','un caryotype',['un génome','un arbre de parenté','une radiographie'],'Le caryotype permet de compter et de comparer les chromosomes.',2],
   ['Quel parent détermine le sexe génétique de l’enfant ?','le père, car son spermatozoïde apporte un X ou un Y',['la mère, car l’ovule apporte un X ou un Y','les deux à égalité','aucun, c’est l’environnement'],'L’ovule porte toujours un X ; le spermatozoïde porte X ou Y.',2],
   ['Un caryotype humain montre 47 chromosomes dont trois chromosomes 21. Il s’agit…','d’une trisomie 21',['d’un caryotype normal','d’un caryotype de chimpanzé','d’une cellule reproductrice'],'Un chromosome 21 supplémentaire : trisomie 21.',2],
   ['Pourquoi les cellules reproductrices n’ont-elles que 23 chromosomes chez l’être humain ?','pour que la fécondation rétablisse 46 chromosomes',['parce qu’elles sont plus petites','parce qu’elles sont abîmées','parce qu’elles n’ont pas de noyau'],'23 + 23 = 46 : le nombre de l’espèce est conservé de génération en génération.',3],
   ['Des vrais jumeaux élevés séparément n’ont pas exactement la même taille. Pourquoi ?','la taille dépend aussi de l’environnement (alimentation, santé)',['ils n’ont pas les mêmes gènes','la taille n’est jamais héréditaire','par erreur de mesure uniquement'],'Même information génétique, mais environnement différent.',3],
   {tf:'Une cellule de peau et une cellule du foie d’une même personne contiennent la même information génétique.',v:true,e:'Toutes les cellules issues de la cellule-œuf ont reçu la même information génétique.',d:3},
   {tf:'Le nombre de chromosomes indique si une espèce est plus évoluée qu’une autre.',v:false,e:'Le chien a 78 chromosomes et l’être humain 46 : ce nombre n’indique pas un « degré d’évolution ».',d:2}]),3])},

{id:'svt4c',name:'Reproduction et transmission de la vie',icon:'👶',domain:'Reproduction',
 refs:[REF4,E4(TH3)+' — « Relier le fonctionnement des appareils reproducteurs à partir de la puberté aux principes de la maîtrise de la reproduction »',REFEV],
 tip:'Dans un cycle, le jour 1 est le premier jour des règles ; l’ovulation a lieu environ 14 jours AVANT le début des règles suivantes (jour 14 pour un cycle de 28 jours).',
 c:C(`Chez l’homme, des millions de spermatozoïdes sont produits chaque jour ; chez la femme, un ovule est libéré environ une fois par mois. Comment fonctionnent ces deux appareils reproducteurs, qui les commande, et comment ces connaissances permettent-elles de maîtriser la reproduction ?`,
  [T('Le fonctionnement des appareils reproducteurs',`<p>Chez l’homme, à partir de la puberté, les <b>testicules</b> produisent <b>en continu</b> des spermatozoïdes et une hormone, la <b>testostérone</b>. Chez la femme, le fonctionnement est <b>cyclique</b> : un cycle dure en moyenne 28 jours (souvent entre 21 et 35). Le jour 1 est le premier jour des règles.</p><p>Pendant la première partie du cycle, un <b>follicule</b> de l’ovaire grossit et produit des œstrogènes ; la muqueuse de l’utérus s’épaissit. Vers le milieu du cycle a lieu l’<b>ovulation</b> : l’ovule est libéré, environ 14 jours avant les règles suivantes. Le follicule vide produit alors de la <b>progestérone</b>, qui prépare l’utérus à une éventuelle nidation. Sans fécondation, la production d’hormones chute et la muqueuse est éliminée : ce sont les <b>règles</b>.</p>`),
   T('Un contrôle par le cerveau',`<p>Les testicules et les ovaires sont commandés par le <b>cerveau</b> (hypothalamus et hypophyse), qui libère dans le sang des hormones stimulant leur fonctionnement. Les hormones des ovaires et des testicules agissent en retour sur le cerveau : c’est une régulation.</p><p>La <b>fécondation</b> a lieu dans une trompe : un spermatozoïde (23 chromosomes) et un ovule (23 chromosomes) forment une cellule-œuf (46 chromosomes). L’ovule ne vit qu’environ un jour après l’ovulation ; les spermatozoïdes peuvent survivre quelques jours dans les voies génitales féminines. L’embryon s’implante dans l’utérus environ une semaine après la fécondation.</p>`),
   T('Maîtriser la reproduction',`<p>Ces connaissances permettent de choisir le moment d’avoir un enfant. La <b>contraception</b> empêche la grossesse : la pilule contient des hormones de synthèse qui freinent le cerveau et bloquent l’<b>ovulation</b> ; le préservatif empêche les spermatozoïdes d’atteindre l’ovule (c’est aussi le seul moyen qui protège des infections sexuellement transmissibles) ; le dispositif intra-utérin (stérilet) empêche la fécondation ou la nidation.</p><p>À l’inverse, en cas d’infertilité, la <b>procréation médicalement assistée</b> aide à obtenir une grossesse : par exemple la fécondation in vitro (FIV), où la fécondation a lieu au laboratoire avant le transfert de l’embryon dans l’utérus.</p>`)],
  [{q:'Le cycle de Clara dure 30 jours. Vers quel jour a lieu son ovulation ?',s:['L’ovulation a lieu environ 14 jours avant le début des règles suivantes.','Les règles suivantes commencent au jour 31 (jour 1 du cycle suivant).','Ovulation vers le jour 30 − 14 = 16 du cycle.']}],
  ['Je repère le jour 1 (début des règles) et la durée du cycle.','Je place l’ovulation environ 14 jours avant les règles suivantes.','Je relie chaque hormone à l’organe qui la produit et à son effet.','J’explique une méthode contraceptive par l’étape qu’elle bloque.'],
  ['Croire que l’ovulation a toujours lieu le jour 14 : cela dépend de la durée du cycle, et les cycles varient.','Penser que la pilule protège des infections sexuellement transmissibles : seul le préservatif protège des IST.','Croire que l’homme produit un spermatozoïde par cycle : la production est continue.'],
  ['Testicules : production continue de spermatozoïdes et de testostérone dès la puberté.','Ovaires : fonctionnement cyclique ; ovulation environ 14 jours avant les règles suivantes.','Le cerveau commande les organes reproducteurs par des hormones.','Contraception : bloquer l’ovulation, la rencontre des gamètes ou la nidation ; le préservatif protège aussi des IST.']),
 g:mix([d=>{const L=R(d===1?28:24,d===1?28:35);return num(`Un cycle dure <b>${L} jours</b> (le jour 1 est le premier jour des règles). Vers quel jour du cycle (donne son numéro) a lieu l’ovulation ?`,L-14,{expl:`L’ovulation a lieu environ 14 jours avant les règles suivantes : ${L} − 14 = <b>jour ${L-14}</b>. Ce n’est qu’une estimation : les cycles varient d’une personne et d’un mois à l’autre.`,hint:'Compte 14 jours en arrière à partir de la fin du cycle.'});},2],
  [pairs([['la testostérone','hormone produite par les testicules'],['les œstrogènes','hormones produites par le follicule de l’ovaire'],['la progestérone','hormone qui prépare l’utérus à la nidation'],['l’hypophyse','glande du cerveau qui commande les ovaires et les testicules'],['l’ovulation','libération d’un ovule par l’ovaire'],['la nidation','implantation de l’embryon dans la muqueuse de l’utérus']],{q:'Que désigne « %s » ?',rq:'Quel terme correspond à cette description : « %s » ?'}),3],
  [S({'bloque l’ovulation':['la pilule contraceptive','l’implant contraceptif'],'empêche les spermatozoïdes d’atteindre l’ovule':['le préservatif externe (masculin)','le préservatif interne (féminin)'],'aide à obtenir une grossesse':['la fécondation in vitro (FIV)','l’insémination artificielle']},'Quel est le principe de « %s » ?',{'bloque l’ovulation':'Des hormones de synthèse freinent la commande du cerveau : pas d’ovulation.','empêche les spermatozoïdes d’atteindre l’ovule':'C’est une barrière ; c’est aussi la seule méthode qui protège des IST.','aide à obtenir une grossesse':'C’est une technique de procréation médicalement assistée (PMA).'}),2],
  [bank([['Que se passe-t-il au moment de l’ovulation ?','l’ovaire libère un ovule',['l’utérus élimine sa muqueuse','un spermatozoïde est produit','l’embryon s’implante'],'L’ovule est libéré et capté par la trompe.',1],
   ['Quel organe commande le fonctionnement des ovaires et des testicules ?','le cerveau (hypothalamus et hypophyse)',['le cœur','l’estomac','les reins'],'Il libère des hormones qui stimulent les organes reproducteurs.',1],
   ['Combien de chromosomes contient la cellule-œuf humaine ?','46',['23','92','48'],'23 apportés par le spermatozoïde + 23 par l’ovule.',1],
   ['Que provoque la chute des hormones ovariennes en fin de cycle, sans fécondation ?','les règles',['l’ovulation','la nidation','la puberté'],'Sans hormones pour l’entretenir, la muqueuse utérine est éliminée.',2],
   ['Comment agit la pilule contraceptive ?','ses hormones freinent le cerveau et empêchent l’ovulation',['elle tue les spermatozoïdes dans l’estomac','elle protège des IST','elle provoque les règles chaque jour'],'Sans ovulation, pas de fécondation possible.',2],
   ['Quel moyen de contraception protège aussi des infections sexuellement transmissibles ?','le préservatif',['la pilule','l’implant','le stérilet'],'Le préservatif est une barrière : c’est le seul à protéger aussi des IST.',2],
   ['Pourquoi la période de fertilité s’étend-elle sur plusieurs jours avant l’ovulation ?','les spermatozoïdes peuvent survivre quelques jours dans les voies génitales féminines',['l’ovule vit plusieurs semaines','l’ovulation dure une semaine','les règles sont fertiles'],'Un rapport quelques jours avant l’ovulation peut aboutir à une fécondation.',3],
   ['Dans la fécondation in vitro, où a lieu la fécondation ?','au laboratoire, hors du corps',['dans la trompe','dans l’ovaire','dans le vagin'],'« In vitro » signifie « dans le verre » : l’embryon est ensuite transféré dans l’utérus.',3],
   ['Un cycle de 35 jours a son ovulation vers le jour 21. Pourquoi pas le jour 14 ?','l’ovulation se place environ 14 jours avant les règles suivantes, quelle que soit la durée du cycle',['les longs cycles n’ont pas d’ovulation','c’est une erreur de calcul','l’ovulation a toujours lieu le jour 21'],'35 − 14 = 21 : c’est surtout la première partie du cycle qui varie.',3],
   {tf:'Chez l’homme, la production de spermatozoïdes est cyclique, une fois par mois.',v:false,e:'Elle est continue à partir de la puberté.',d:2}]),3])},

{id:'svt4d',name:'Système nerveux, sens et mouvement',icon:'🧠',domain:'Corps humain',
 refs:[REF4,E4(TH3)+' — « Message nerveux, centres nerveux, nerfs, cellules nerveuses »'],
 tip:'Suis toujours la chaîne : stimulus → récepteur sensoriel → nerf sensitif → centre nerveux → nerf moteur → muscle. Si un maillon est coupé, la réponse n’a pas lieu.',
 c:C(`Une balle arrive vers toi : en une fraction de seconde, tu la vois, tu lèves le bras et tu l’attrapes. Comment l’information voyage-t-elle de tes yeux à ton cerveau puis à tes muscles, et à quelle vitesse ?`,
  [T('De l’organe des sens au cerveau',`<p>Les <b>organes des sens</b> (œil, oreille, peau, nez, langue) contiennent des <b>récepteurs sensoriels</b> qui captent un <b>stimulus</b> (lumière, son, contact, chaleur) et le transforment en <b>message nerveux</b>. Ce message est conduit par un <b>nerf sensitif</b> jusqu’aux <b>centres nerveux</b> : le <b>cerveau</b> et la <b>moelle épinière</b>.</p><p>Le cerveau intègre les informations venues de plusieurs sens et élabore une réponse. Il comporte des zones spécialisées (<b>aires cérébrales</b>) : aire visuelle à l’arrière, aire motrice qui commande les mouvements. L’hémisphère gauche commande les muscles du côté droit du corps, et inversement.</p>`),
   T('Du cerveau aux muscles',`<p>Le message nerveux moteur part du cerveau, descend la moelle épinière puis un <b>nerf moteur</b> jusqu’aux <b>muscles</b>, qui se contractent. Les muscles sont attachés aux os par des <b>tendons</b> ; en se contractant ils raccourcissent et font bouger les os autour d’une <b>articulation</b>. Les muscles fonctionnent par paires antagonistes : le biceps plie le bras, le triceps le tend.</p><p>Le message nerveux est porté par des cellules nerveuses, les <b>neurones</b> : il est <b>électrique</b> le long d’un neurone et <b>chimique</b> entre deux neurones, au niveau d’une <b>synapse</b> où sont libérées des molécules appelées neurotransmetteurs. Sa vitesse va d’environ 1 m/s à plus de 100 m/s selon les fibres. Certains mouvements, les <b>réflexes</b> (retrait de la main d’une plaque chaude), sont commandés par la moelle épinière sans décision du cerveau.</p>`)],
  [{q:'Un message nerveux parcourt 1,2 m (de la moelle épinière au pied) en 20 ms. Quelle est sa vitesse ?',s:['v = d ÷ t, avec d en mètres et t en secondes.','20 ms = 0,02 s.','v = 1,2 ÷ 0,02 = 60 m/s.']}],
  ['J’identifie le stimulus et le récepteur sensoriel concerné.','Je trace le trajet du message : nerf sensitif → centre nerveux → nerf moteur → muscle.','Je repère l’organe qui commande (cerveau ou moelle épinière pour un réflexe).','Pour une vitesse, j’utilise v = d ÷ t en mètres et en secondes.'],
  ['Croire que les nerfs « réfléchissent » : ce sont des conducteurs ; ce sont les centres nerveux qui élaborent la réponse.','Penser que l’œil « voit » : il capte la lumière, mais c’est le cerveau qui construit l’image.','Oublier de convertir les millisecondes en secondes (1 ms = 0,001 s).'],
  ['Récepteur sensoriel → nerf sensitif → centres nerveux → nerf moteur → muscle.','Le cerveau intègre les informations et commande les mouvements volontaires ; la moelle épinière commande les réflexes.','Le message nerveux est électrique dans les neurones et chimique au niveau des synapses.','Les muscles tirent sur les os grâce aux tendons et fonctionnent par paires antagonistes.']),
 g:mix([d=>{const v=P([10,20,25,40,50,80,100]);const t=R(Math.ceil(500/v),Math.floor(2000/v));const dd=rd(v*t/1000);
    if(Math.random()<.5)return num(`Un message nerveux parcourt <b>${nf(dd)} m</b> en <b>${nf(t)} ms</b>. Quelle est sa vitesse ?`,v,{unit:'m/s',expl:`${nf(t)} ms = ${nf(rd(t/1000))} s ; v = ${nf(dd)} ÷ ${nf(rd(t/1000))} = <b>${v} m/s</b>.`,hint:'Convertis les ms en s, puis v = d ÷ t.'});
    return num(`Un message nerveux se propage à <b>${v} m/s</b> le long d’un nerf de <b>${nf(dd)} m</b>. Combien de millisecondes met-il ?`,t,{unit:'ms',expl:`t = d ÷ v = ${nf(dd)} ÷ ${v} = ${nf(rd(dd/v))} s = <b>${nf(t)} ms</b>.`,hint:'t = d ÷ v, puis × 1 000 pour avoir des ms.'});},3],
  [seqs([['Trajet d’une information jusqu’au mouvement',['stimulus','récepteur sensoriel','nerf sensitif','centre nerveux','nerf moteur','muscle']]]),2],
  [pairs([['le récepteur sensoriel','capte un stimulus et le transforme en message nerveux'],['le nerf sensitif','conduit le message de l’organe des sens vers les centres nerveux'],['le nerf moteur','conduit le message des centres nerveux vers les muscles'],['la moelle épinière','centre nerveux qui commande les réflexes et relaie les messages'],['la synapse','zone de contact où le message passe d’un neurone à un autre'],['le tendon','relie un muscle à un os']],{q:'Que désigne « %s » ?',rq:'Quel élément correspond à cette description : « %s » ?'}),2],
  [bank([['Comment appelle-t-on la cellule nerveuse ?','le neurone',['le globule blanc','la fibre musculaire','le récepteur'],'Les neurones conduisent le message nerveux.',1],
   ['Quels sont les centres nerveux ?','le cerveau et la moelle épinière',['les nerfs et les muscles','l’œil et l’oreille','le cœur et les poumons'],'Ils reçoivent les messages sensitifs et élaborent les réponses.',1],
   ['Quel muscle plie le bras au niveau du coude ?','le biceps',['le triceps','le mollet','le diaphragme'],'Le biceps fléchit, le triceps (son antagoniste) étend le bras.',1],
   ['Sous quelle forme le message nerveux passe-t-il d’un neurone à l’autre ?','sous forme chimique (neurotransmetteurs)',['sous forme de son','sous forme de lumière','il ne passe jamais'],'Électrique dans le neurone, chimique au niveau de la synapse.',2],
   ['Une personne a une lésion de l’hémisphère gauche du cerveau dans l’aire motrice. Quelle partie du corps risque d’être paralysée ?','le côté droit',['le côté gauche','les deux côtés','aucune'],'Chaque hémisphère commande les muscles du côté opposé du corps.',3],
   ['Le nerf sensitif d’un doigt est sectionné. Que se passe-t-il quand on pique ce doigt ?','la personne ne sent rien',['la personne sent mais ne peut plus bouger le doigt','rien ne change','le doigt bouge tout seul'],'Le message n’arrive plus aux centres nerveux : pas de sensation.',3],
   ['Retirer la main d’une plaque brûlante avant même de sentir la douleur est…','un réflexe commandé par la moelle épinière',['un mouvement volontaire réfléchi','un mouvement commandé par l’œil','une contraction du cœur'],'Le réflexe est très rapide car il ne passe pas par une décision du cerveau.',2],
   ['Pourquoi dit-on que c’est le cerveau qui « voit » ?','l’œil capte la lumière, mais l’image est construite par l’aire visuelle du cerveau',['parce que le cerveau a des yeux','parce que l’œil ne sert à rien','parce que la lumière entre dans le cerveau'],'Les messages venus de l’œil sont interprétés par le cerveau.',2],
   {tf:'Un muscle peut pousser un os aussi bien que le tirer.',v:false,e:'Un muscle ne peut que se contracter et tirer : c’est pourquoi les muscles fonctionnent par paires antagonistes.',d:3}]),3])},

{id:'svt4e',name:'Hormones et régulation de l’organisme',icon:'⚗️',domain:'Corps humain',
 refs:[REF4,E4(TH3)+' — « Puberté, organes reproducteurs, production de cellules reproductrices, contrôles hormonaux »'],
 tip:'Une hormone suit toujours le même chemin : glande endocrine → sang → organe cible (qui possède des récepteurs à cette hormone). Pour prouver le rôle d’une glande : ablation (effet disparaît), puis greffe ou injection (effet rétabli).',
 c:C(`Au XIXe siècle, un médecin retire les testicules à de jeunes coqs : leur crête ne se développe pas et ils ne chantent pas. S’il regreffe un testicule ailleurs dans le corps, la crête pousse normalement. Comment un organe peut-il agir à distance, sans nerf ? Grâce à des messagers chimiques : les <b>hormones</b>.`,
  [T('La communication hormonale',`<p>Une <b>hormone</b> est une substance chimique produite par une <b>glande endocrine</b>, libérée dans le <b>sang</b>, qui agit à distance sur des <b>organes cibles</b>. Seules les cellules qui possèdent des <b>récepteurs</b> à cette hormone y répondent.</p><p>Exemples : les <b>testicules</b> produisent la testostérone (caractères sexuels masculins, production des spermatozoïdes) ; les <b>ovaires</b> produisent œstrogènes et progestérone (cycle de l’utérus) ; les <b>glandes surrénales</b> produisent l’adrénaline (elle accélère le cœur en cas de stress ou d’effort). La communication hormonale est plus lente que la communication nerveuse, mais ses effets durent plus longtemps et touchent tout l’organisme par le sang.</p>`),
   T('Une régulation commandée par le cerveau',`<p>Le fonctionnement des ovaires et des testicules est commandé par le <b>cerveau</b> : l’hypothalamus et l’<b>hypophyse</b> (petite glande sous le cerveau) libèrent des hormones qui stimulent les organes reproducteurs. À la puberté, cette commande s’active : c’est elle qui déclenche les transformations du corps.</p><p>En retour, les hormones produites par les ovaires et les testicules agissent sur le cerveau et modulent sa commande : c’est une <b>régulation</b> qui maintient des taux d’hormones adaptés. La pilule contraceptive utilise ce mécanisme : ses hormones de synthèse freinent l’hypophyse, si bien que l’ovulation n’a pas lieu. L’usage d’hormones pour améliorer ses performances (<b>dopage</b>) perturbe ces régulations et est dangereux pour la santé.</p>`)],
  [{q:'Une ratte privée de ses ovaires n’a plus de cycle de l’utérus. Si on lui injecte des extraits d’ovaires, la muqueuse utérine se développe à nouveau. Conclure.',s:['Ablation des ovaires → l’utérus ne fonctionne plus : les ovaires agissent sur l’utérus.','Injection d’extraits (sans nerf ni greffe) → l’effet revient : l’action passe par des substances chimiques.','Les ovaires commandent l’utérus grâce à des hormones transportées par le sang.']}],
  ['J’identifie la glande, l’hormone et l’organe cible.','Je repère dans une expérience l’ablation (effet supprimé) et la greffe ou l’injection (effet rétabli).','Je conclus que l’action passe par le sang si la glande greffée n’est reliée à aucun nerf.','Je relie l’effet observé à la régulation (commande du cerveau, rétroaction des hormones).'],
  ['Croire qu’une hormone agit sur toutes les cellules : seules les cellules cibles, munies de récepteurs, répondent.','Confondre message nerveux (rapide, par les nerfs) et message hormonal (plus lent, par le sang).','Penser que l’hypophyse fabrique les cellules reproductrices : elle commande les organes qui les fabriquent.'],
  ['Hormone = messager chimique produit par une glande endocrine, transporté par le sang, actif sur des cellules cibles.','Testostérone (testicules) ; œstrogènes et progestérone (ovaires) ; adrénaline (glandes surrénales).','Le cerveau (hypothalamus, hypophyse) commande les ovaires et les testicules, qui agissent en retour sur lui.','La pilule bloque l’ovulation en freinant l’hypophyse ; le dopage hormonal est dangereux.']),
 g:mix([pairs([['la testostérone','les testicules'],['les œstrogènes','les ovaires'],['la progestérone','les ovaires (follicule après l’ovulation)'],['l’adrénaline','les glandes surrénales'],['les hormones qui commandent les ovaires et les testicules','l’hypophyse']],{q:'Quelle glande produit %s ?'.replace('%s','« %s »'),rq:'Quelle hormone produisent « %s » ?',oneWay:true}),2],
  [d=>{const X=P([['Un coq jeune est privé de ses testicules','sa crête ne se développe pas','les testicules agissent sur le développement de la crête'],['Une ratte est privée de ses ovaires','son utérus ne présente plus de cycle','les ovaires agissent sur l’utérus'],['On retire l’hypophyse d’un animal adulte','ses testicules (ou ses ovaires) cessent de fonctionner','l’hypophyse commande les organes reproducteurs']]);const k=R(0,1);
    if(k===0)return ch(`${X[0]} : ${X[1]}. Quelle conclusion peut-on tirer ?`,X[2],['cet organe ne sert à rien','l’effet est dû au hasard','cet organe produit des cellules sanguines'],{expl:`Supprimer l’organe supprime l’effet : ${X[2]}. Il reste à prouver que l’action passe par le sang (greffe ou injection d’extraits).`,hint:'Que se passe-t-il quand on enlève l’organe ?'});
    return ch(`${X[0]} : ${X[1]}. On lui greffe ensuite l’organe retiré sous la peau (sans connexion nerveuse) et l’effet réapparaît. Que montre la greffe ?`,'l’organe agit par des substances transportées par le sang : des hormones',['l’organe agit par les nerfs','la greffe n’a aucun effet','le sang fabrique l’organe'],{expl:'La greffe n’est reliée à aucun nerf : seule la circulation sanguine peut transporter le message. C’est une communication hormonale.',hint:'L’organe greffé est-il relié par des nerfs ?'});},3],
  [S({'communication nerveuse':['message transmis en quelques millisecondes','message conduit par des nerfs','effet très localisé sur un muscle précis'],'communication hormonale':['message transporté par le sang','effet qui dure des heures ou des jours','message chimique produit par une glande endocrine']},'« %s » caractérise plutôt la…',{'communication nerveuse':'La communication nerveuse est rapide, brève et passe par les nerfs.','communication hormonale':'La communication hormonale est plus lente, plus durable et passe par le sang.'}),2],
  [bank([['Qu’est-ce qu’une hormone ?','un messager chimique produit par une glande et transporté par le sang',['un message électrique dans un nerf','une cellule du sang','un nutriment'],'Elle agit à distance sur des organes cibles.',1],
   ['Comment une hormone atteint-elle son organe cible ?','par le sang',['par les nerfs','par le tube digestif','par l’air'],'Elle est libérée dans le sang qui la distribue.',1],
   ['Quelle hormone est surtout responsable des caractères sexuels masculins ?','la testostérone',['la progestérone','l’adrénaline','l’œstrogène'],'Produite par les testicules.',1],
   ['Pourquoi certaines cellules seulement répondent-elles à une hormone ?','elles possèdent des récepteurs à cette hormone',['elles sont plus grosses','elles sont plus proches du cœur','les autres sont mortes'],'Ce sont les cellules cibles.',2],
   ['Comment la pilule contraceptive empêche-t-elle l’ovulation ?','ses hormones de synthèse freinent l’hypophyse, qui ne stimule plus l’ovaire',['elle détruit les ovaires','elle bloque les spermatozoïdes','elle accélère les règles'],'Elle agit sur la commande du cerveau.',2],
   ['Que déclenche la puberté ?','l’activation par le cerveau de la commande hormonale des ovaires ou des testicules',['la croissance des os uniquement','la chute des dents de lait','la digestion'],'L’hypothalamus et l’hypophyse stimulent les organes reproducteurs.',2],
   ['Un sportif prend de la testostérone de synthèse. Pourquoi est-ce dangereux ?','cela perturbe les régulations hormonales et peut nuire à la santé (cœur, foie, fertilité)',['ce n’est pas dangereux','cela rend seulement plus fatigué','cela fait seulement grandir'],'Le dopage est interdit et dérègle l’organisme ; il peut même freiner la production naturelle d’hormones.',3],
   ['Une forte peur fait battre le cœur plus vite pendant plusieurs minutes. Quelle hormone y participe ?','l’adrénaline',['la progestérone','la testostérone','les œstrogènes'],'Produite par les glandes surrénales, elle accélère le cœur.',3],
   {tf:'La communication hormonale est plus rapide que la communication nerveuse.',v:false,e:'Le message nerveux est très rapide ; les hormones agissent plus lentement mais plus durablement.',d:2},
   ['Qu’est-ce qu’une glande endocrine ?','une glande qui libère ses produits (hormones) dans le sang',['une glande qui déverse un suc dans l’intestin','un organe des sens','une cellule nerveuse'],'Endocrine = sécrétion interne, dans le sang ; les glandes salivaires, elles, déversent la salive dans la bouche.',2],
   ['Où se trouve l’hypophyse ?','sous le cerveau',['dans le cou','dans l’abdomen','dans les testicules'],'Petite glande reliée à l’hypothalamus, à la base du cerveau.',1],
   ['Quel est l’organe cible principal de la progestérone ?','l’utérus',['l’estomac','les poumons','l’œil'],'Elle prépare la muqueuse utérine à une éventuelle nidation.',2],
   ['Après la ménopause, les ovaires ne produisent presque plus d’hormones. Que devient le cycle de l’utérus ?','il s’arrête : il n’y a plus de règles',['il s’accélère','il reste identique','il devient hebdomadaire'],'Sans hormones ovariennes, la muqueuse utérine n’évolue plus de façon cyclique.',3],
   ['Les hormones des testicules agissent en retour sur le cerveau. Comment appelle-t-on ce type de contrôle ?','une régulation (rétrocontrôle)',['une digestion','une vaccination','une fécondation'],'Le cerveau ajuste sa commande selon le taux d’hormones : les taux restent adaptés.',3],
   ['Pourquoi un extrait de testicule injecté dans le sang d’un coq castré rétablit-il la crête ?','il contient de la testostérone, transportée par le sang jusqu’à la crête',['il contient des nerfs','il contient des spermatozoïdes qui agissent sur la crête','il nourrit la crête'],'C’est la preuve d’une communication hormonale.',3]]),3])},

{id:'svt4f',name:'Immunité : défendre l’organisme',icon:'🛡️',domain:'Santé',
 refs:[REF4,E4(TH3)+' — « Réactions immunitaires » ; « Mesures d’hygiène, vaccination, action des antiseptiques et des antibiotiques »'],
 tip:'Classe les défenses dans l’ordre : barrières (peau, muqueuses) → réaction rapide non spécifique (inflammation, phagocytose) → réaction lente spécifique (lymphocytes, anticorps).',
 c:C(`Une écharde se plante dans ton doigt : quelques heures plus tard, la zone est rouge, chaude, gonflée et douloureuse. Ce n’est pas la maladie : c’est ton organisme qui se défend. Quelles sont ses lignes de défense contre les micro-organismes ?`,
  [T('Barrières et réaction rapide',`<p>La <b>peau</b> et les <b>muqueuses</b> (nez, bouche, intestin) forment une première barrière : mucus, larmes, acidité de l’estomac, bactéries utiles de la peau et de l’intestin limitent l’entrée des micro-organismes. Une plaie ouvre une porte d’entrée : c’est la <b>contamination</b>.</p><p>Aussitôt se déclenche la <b>réaction inflammatoire</b> : rougeur, chaleur, gonflement, douleur. Les vaisseaux se dilatent et des globules blancs, les <b>phagocytes</b>, sortent du sang et viennent sur place. Ils englobent les micro-organismes et les digèrent : c’est la <b>phagocytose</b>. Cette réaction est rapide et agit contre tous les micro-organismes : elle est <b>non spécifique</b>.</p>`),
   T('Réaction spécifique et aides médicales',`<p>Si l’infection persiste, d’autres globules blancs interviennent : les <b>lymphocytes</b>. Ils reconnaissent spécifiquement un <b>antigène</b> (une molécule propre au micro-organisme). Les lymphocytes B produisent des <b>anticorps</b> qui se fixent sur cet antigène et le neutralisent ; les lymphocytes T détruisent les cellules infectées par un virus. Cette réaction est plus lente (plusieurs jours) mais <b>spécifique</b>.</p><p>La médecine aide l’organisme : <b>antiseptiques</b> sur les plaies, <b>antibiotiques</b> contre les bactéries (pas contre les virus), <b>vaccins</b> pour préparer à l’avance la réaction spécifique. En laboratoire, un <b>antibiogramme</b> permet de choisir l’antibiotique efficace : plus la zone sans bactéries autour d’un disque d’antibiotique est grande, plus il est efficace.</p>`)],
  [{q:'Antibiogramme : zones d’inhibition de 25 mm (amoxicilline), 6 mm (tétracycline, diamètre du disque), 14 mm (érythromycine). Quel antibiotique choisir ?',s:['La zone sans bactéries mesure l’efficacité de l’antibiotique.','6 mm = diamètre du disque : aucune zone, la bactérie est résistante à la tétracycline.','L’amoxicilline (25 mm) est la plus efficace : c’est celle qu’il faut choisir.']}],
  ['J’identifie la porte d’entrée du micro-organisme.','Je décris la réaction rapide (inflammation, phagocytose).','Je décris la réaction spécifique (lymphocytes, anticorps) si l’infection persiste.','Je choisis l’aide médicale adaptée (antiseptique, antibiotique pour une bactérie, vaccin en prévention).'],
  ['Croire que l’inflammation est la maladie : c’est une réaction de défense.','Penser que les anticorps détruisent eux-mêmes les microbes : ils les neutralisent, puis les phagocytes les éliminent.','Utiliser un antibiotique contre un virus : il est sans effet.'],
  ['Peau et muqueuses sont les premières barrières.','Réaction inflammatoire et phagocytose : rapides, non spécifiques.','Lymphocytes B (anticorps) et T (destruction des cellules infectées) : plus lents, spécifiques d’un antigène.','Antiseptiques, antibiotiques (bactéries seulement) et vaccins aident l’organisme.']),
 g:mix([d=>{const names=pickN(ATB,4);const res=R(0,3);const best=(res+R(1,3))%4;const used=new Set([6]);const dia=names.map((n,i)=>{if(i===res)return 6;let x;for(let k=0;k<20;k++){x=R(9,24);if(!used.has(x))break;}used.add(x);return x;});dia[best]=Math.max(...dia.filter((x,i)=>i!==best))+R(3,8);
    const tab=names.map((n,i)=>`${n} : ${dia[i]} mm`).join(' ; ');
    if(Math.random()<.5)return ch(`Antibiogramme (diamètre de la zone sans bactéries ; un disque mesure 6 mm) — ${tab}. Quel antibiotique est le plus efficace ?`,names[best],names.filter((n,i)=>i!==best),{expl:`La zone d’inhibition la plus grande (${dia[best]} mm) correspond à <b>${names[best]}</b> : c’est l’antibiotique le plus efficace contre cette bactérie.`,hint:'Cherche la plus grande zone sans bactéries.'});
    return ch(`Antibiogramme (diamètre de la zone sans bactéries ; un disque mesure 6 mm) — ${tab}. À quel antibiotique la bactérie est-elle résistante ?`,names[res],names.filter((n,i)=>i!==res),{expl:`Avec ${names[res]}, la zone mesure 6 mm, soit le diamètre du disque : aucune bactérie n’a été tuée autour. La bactérie est <b>résistante</b> à cet antibiotique.`,hint:'Quel disque n’a aucune zone autour de lui ?'});},3],
  [seqs([['Défense de l’organisme après une coupure',['contamination par une plaie','réaction inflammatoire','phagocytose par les phagocytes','intervention des lymphocytes','production d’anticorps spécifiques']]]),2],
  [S({'barrière naturelle':['la peau','le mucus du nez','les larmes','l’acidité de l’estomac'],'réaction rapide non spécifique':['la phagocytose','la rougeur et le gonflement d’une plaie'],'réaction lente spécifique':['la production d’anticorps','la destruction des cellules infectées par les lymphocytes T']},'« %s » est…',{'barrière naturelle':'Elle empêche ou limite l’entrée des micro-organismes.','réaction rapide non spécifique':'Elle agit en quelques heures contre tous les micro-organismes.','réaction lente spécifique':'Elle met plusieurs jours et vise un antigène précis.'}),2],
  [bank([['Quels sont les quatre signes de la réaction inflammatoire ?','rougeur, chaleur, gonflement, douleur',['fièvre, toux, fatigue, frissons','pâleur, froid, démangeaison, sueur','saignement, croûte, cicatrice, bleu'],'Ce sont les signes locaux de l’arrivée de sang et de globules blancs.',1],
   ['Comment appelle-t-on l’action d’un globule blanc qui englobe et digère un microbe ?','la phagocytose',['la digestion intestinale','la vaccination','la coagulation'],'Elle est réalisée par les phagocytes.',1],
   ['Quelles cellules produisent les anticorps ?','les lymphocytes B',['les globules rouges','les phagocytes','les neurones'],'Les lymphocytes B produisent des anticorps spécifiques d’un antigène.',2],
   ['Qu’est-ce qu’un antigène ?','une molécule reconnue comme étrangère par les lymphocytes',['un médicament','un globule blanc','un anticorps'],'Chaque micro-organisme porte des antigènes qui lui sont propres.',2],
   ['Un anticorps dirigé contre le virus de la rougeole agit-il contre le virus de la grippe ?','non, un anticorps est spécifique d’un antigène',['oui, il agit contre tous les virus','oui, mais seulement la nuit','seulement si on prend des antibiotiques'],'La réaction des lymphocytes est spécifique.',2],
   ['Pourquoi la réaction spécifique met-elle plusieurs jours ?','les lymphocytes adaptés doivent être sélectionnés et se multiplier',['le sang circule lentement','les anticorps sont fabriqués par l’estomac','les phagocytes la retardent'],'Lors du premier contact, il faut produire de nombreux lymphocytes spécifiques.',3],
   ['Une bactérie forme une zone de 6 mm (diamètre du disque) autour de tous les antibiotiques testés. Que conclure ?','elle est résistante à tous ces antibiotiques',['tous ces antibiotiques sont très efficaces','le test est impossible','c’est un virus'],'Aucune zone d’inhibition : aucun antibiotique ne l’a tuée.',3],
   ['Que permet la vaccination ?','préparer à l’avance la réaction spécifique de l’organisme',['tuer les bactéries déjà présentes','remplacer les globules blancs','soigner une infection virale déclarée'],'Le vaccin met l’organisme en contact avec un antigène sans danger.',2],
   {tf:'Les antibiotiques soignent la grippe.',v:false,e:'La grippe est due à un virus ; les antibiotiques n’agissent que sur les bactéries.',d:1}]),3])},

{id:'svt4g',name:'Tectonique des plaques et activité interne du globe',icon:'🗺️',domain:'Planète Terre',
 refs:[REF4,E4(TH1)+' — « le globe terrestre (forme, rotation, dynamique interne et tectonique des plaques lithosphériques ; séismes, éruptions volcaniques) »'],
 tip:'Pour les calculs, retiens : 1 km = 100 000 cm, et une vitesse de 1 cm/an pendant 1 million d’années fait 10 km. Pour une frontière, demande-toi si les plaques s’écartent, se rapprochent ou coulissent.',
 c:C(`Les côtes de l’Amérique du Sud et de l’Afrique s’emboîtent comme deux pièces de puzzle. En 1912, Alfred Wegener en déduit que les continents se déplacent. On s’est moqué de lui… jusqu’aux années 1960. Aujourd’hui, des satellites mesurent ces mouvements au millimètre près. Comment la surface de la Terre bouge-t-elle ?`,
  [T('Des plaques en mouvement',`<p>La couche externe rigide de la Terre, la <b>lithosphère</b> (environ 100 km d’épaisseur), est découpée en une douzaine de grandes <b>plaques lithosphériques</b>. Elles se déplacent de quelques centimètres par an sur une couche plus déformable, l’<b>asthénosphère</b>. Le moteur de ces mouvements est la chaleur interne du globe.</p><p>Les arguments de Wegener (continents qui s’emboîtent, mêmes fossiles et mêmes roches de part et d’autre de l’Atlantique, traces d’anciens glaciers) ont été complétés par l’étude des fonds océaniques : les roches du plancher océanique sont de plus en plus âgées quand on s’éloigne d’une <b>dorsale</b>. La plupart des séismes et des volcans se situent aux <b>frontières des plaques</b>.</p>`),
   T('Les frontières de plaques',`<p>Aux <b>dorsales océaniques</b>, les plaques <b>s’écartent</b> (divergence) : du magma remonte et forme une nouvelle lithosphère océanique ; le volcanisme y est surtout <b>effusif</b> (laves fluides, coulées), comme en Islande. Aux zones de <b>subduction</b>, les plaques <b>se rapprochent</b> (convergence) : une plaque océanique plonge sous une autre au niveau d’une fosse océanique ; on y trouve des séismes jusqu’en profondeur et un volcanisme <b>explosif</b> (laves visqueuses, nuées ardentes), comme dans les Andes ou aux Antilles. Quand deux continents se rencontrent, c’est la <b>collision</b> qui forme des chaînes de montagnes (Himalaya, Alpes). Enfin, des plaques peuvent <b>coulisser</b> l’une contre l’autre (faille de San Andreas).</p><p>Un <b>séisme</b> correspond à une rupture brutale des roches le long d’une <b>faille</b> : le point de rupture est le <b>foyer</b>, le point de la surface situé au-dessus est l’<b>épicentre</b>, et des ondes sismiques se propagent dans toutes les directions.</p>`)],
  [{q:'L’océan Atlantique s’ouvre d’environ 2 cm par an. De combien s’est-il élargi en 10 millions d’années ?',s:['d = v × t = 2 cm/an × 10 000 000 ans.','d = 20 000 000 cm.','20 000 000 cm ÷ 100 000 = 200 km.']}],
  ['Je localise la frontière de plaques sur la carte.','Je détermine le mouvement : écartement, rapprochement ou coulissement.','J’en déduis les phénomènes attendus (type de volcanisme, séismes, relief).','Pour une vitesse, j’utilise d = v × t et je convertis les cm en km (÷ 100 000).'],
  ['Croire que les plaques flottent sur un océan de magma liquide : l’asthénosphère est solide mais déformable.','Confondre foyer (en profondeur) et épicentre (en surface).','Penser que les plaques bougent de plusieurs mètres par an : c’est quelques centimètres, la vitesse de pousse des ongles.'],
  ['La lithosphère est découpée en plaques qui se déplacent de quelques cm par an.','Dorsale : écartement, volcanisme effusif ; subduction : rapprochement, volcanisme explosif et séismes ; collision : montagnes.','Séismes et volcans se concentrent aux frontières des plaques.','Un séisme est une rupture de roches le long d’une faille (foyer en profondeur, épicentre en surface).']),
 g:mix([d=>{const v=P([1,2,3,4,5,8,10]),t=P([1,2,5,10,20,50]);const D=v*t*10;const k=d===1?0:R(0,2);
    if(k===0)return num(`Une plaque se déplace de <b>${v} cm par an</b>. De combien de kilomètres se déplace-t-elle en <b>${t} million${t>1?'s':''} d’années</b> ?`,D,{unit:'km',expl:`${v} cm/an × ${nf(t*1e6)} ans = ${nf(v*t*1e6)} cm ; ÷ 100 000 = <b>${nf(D)} km</b>.`,hint:'d = v × t, puis 1 km = 100 000 cm.'});
    if(k===1)return num(`Une roche du fond océanique se trouve à <b>${nf(D)} km</b> de l’axe de la dorsale ; la plaque s’écarte à <b>${v} cm par an</b>. Quel est l’âge de cette roche, en millions d’années ?`,t,{unit:'millions d’années',expl:`${nf(D)} km = ${nf(D*1e5)} cm ; t = d ÷ v = ${nf(D*1e5)} ÷ ${v} = ${nf(t*1e6)} ans = <b>${t} million${t>1?'s':''} d’années</b>.`,hint:'Convertis les km en cm, puis t = d ÷ v.'});
    return num(`Une roche formée à la dorsale il y a <b>${t} million${t>1?'s':''} d’années</b> se trouve aujourd’hui à <b>${nf(D)} km</b> de l’axe. À quelle vitesse la plaque s’est-elle déplacée, en cm par an ?`,v,{unit:'cm/an',expl:`${nf(D)} km = ${nf(D*1e5)} cm ; v = ${nf(D*1e5)} ÷ ${nf(t*1e6)} = <b>${v} cm/an</b>.`,hint:'v = d ÷ t, avec d en cm et t en années.'});},3],
  [S({'divergence (dorsale)':['l’Islande','l’axe de l’océan Atlantique','le fond de la mer Rouge'],'subduction':['la cordillère des Andes','les Antilles','le Japon'],'collision continentale':['l’Himalaya','les Alpes'],'coulissement':['la faille de San Andreas (Californie)']},'Quel type de frontière de plaques explique ce cas : « %s » ?',{'divergence (dorsale)':'Les plaques s’écartent et une nouvelle lithosphère océanique se forme.','subduction':'Une plaque océanique plonge sous une autre plaque.','collision continentale':'Deux continents se rapprochent et le relief se soulève.','coulissement':'Deux plaques glissent horizontalement l’une contre l’autre.'}),2],
  [S({'volcanisme effusif':['des coulées de lave fluide','un volcan de dorsale comme en Islande','le Piton de la Fournaise (La Réunion)'],'volcanisme explosif':['des nuées ardentes','une lave très visqueuse qui forme un dôme','la montagne Pelée (Martinique)']},'« %s » caractérise un…',{'volcanisme effusif':'La lave est fluide : elle s’écoule en coulées.','volcanisme explosif':'La lave visqueuse retient les gaz qui s’échappent violemment.'}),2],
  [bank([['Comment appelle-t-on la couche rigide externe de la Terre, découpée en plaques ?','la lithosphère',['l’asthénosphère','le noyau','l’atmosphère'],'Environ 100 km d’épaisseur.',1],
   ['Quel scientifique a proposé la dérive des continents en 1912 ?','Alfred Wegener',['Charles Darwin','Louis Pasteur','Isaac Newton'],'Ses idées ont été confirmées dans les années 1960 par la tectonique des plaques.',1],
   ['Quel point de la surface est situé à la verticale du foyer d’un séisme ?','l’épicentre',['la faille','la fosse','le cratère'],'Le foyer est en profondeur, l’épicentre en surface.',1],
   ['À quelle vitesse se déplacent les plaques lithosphériques ?','quelques centimètres par an',['quelques mètres par jour','quelques kilomètres par an','elles sont immobiles'],'De l’ordre de la vitesse de pousse des ongles.',1],
   ['Comment évolue l’âge des roches du plancher océanique quand on s’éloigne d’une dorsale ?','il augmente',['il diminue','il reste le même','il est aléatoire'],'Les roches se forment à la dorsale puis s’en éloignent avec le mouvement des plaques.',2],
   ['Pourquoi trouve-t-on les mêmes fossiles en Amérique du Sud et en Afrique ?','ces continents étaient réunis autrefois',['les animaux traversaient l’océan à la nage','par hasard','les fossiles ont été transportés par l’être humain'],'C’est un argument de Wegener en faveur de la dérive des continents.',2],
   ['Que se passe-t-il au niveau d’une zone de subduction ?','une plaque océanique plonge sous une autre plaque',['deux plaques s’écartent','une nouvelle lithosphère se forme','rien ne bouge'],'On y trouve une fosse, des séismes profonds et un volcanisme explosif.',2],
   ['Pourquoi les séismes de la cordillère des Andes peuvent-ils être très profonds ?','ils se produisent le long de la plaque océanique qui s’enfonce',['à cause des glaciers','parce que les Andes sont hautes','parce que l’océan est profond'],'La plaque plongeante reste rigide et cassante jusqu’à des centaines de km.',3],
   ['Quelle est la source d’énergie des mouvements des plaques ?','la chaleur interne de la Terre',['le Soleil','les marées','le vent'],'La Terre libère sa chaleur interne, ce qui entretient les mouvements.',3],
   {tf:'Les plaques lithosphériques flottent sur un océan de magma liquide.',v:false,e:'L’asthénosphère est solide mais déformable ; le magma ne se forme que localement.',d:3}]),3])},

{id:'svt4h',name:'Biodiversité, ressources et activités humaines',icon:'🐟',domain:'Environnement',
 refs:[REF4,E4(TH1)+' — « L’exploitation de quelques ressources naturelles par l’être humain » ; « interactions entre les activités humaines et l’environnement »'],
 tip:'Une ressource « renouvelable » ne le reste que si on la prélève MOINS vite qu’elle ne se renouvelle. Compare toujours prélèvement et renouvellement.',
 c:C(`La morue de Terre-Neuve était si abondante qu’on la disait inépuisable. En 1992, après des décennies de pêche intensive, le Canada a dû interdire sa pêche : le stock s’était effondré. Comment exploiter les ressources naturelles sans les épuiser, et comment nos activités modifient-elles la biodiversité ?`,
  [T('Des ressources naturelles plus ou moins renouvelables',`<p>Les <b>ressources naturelles</b> sont ce que l’être humain prélève dans son environnement pour se nourrir et pour ses activités : eau, sol, bois, poissons, pétrole, charbon, gaz, minerais. Certaines sont <b>renouvelables</b> (poissons, bois, eau douce) car elles se reconstituent, mais seulement si on ne les prélève pas plus vite qu’elles ne se renouvellent. D’autres sont <b>non renouvelables</b> à l’échelle humaine (pétrole, charbon, gaz, minerais) : formées en millions d’années, elles s’épuisent.</p><p>Le <b>sol</b> lui-même est une ressource fragile : il se forme très lentement (des centaines à des milliers d’années) mais peut être perdu par érosion en quelques années après une déforestation.</p>`),
   T('Impacts et gestion durable',`<p>Les activités humaines peuvent dégrader la biodiversité : surpêche, déforestation, pollution des eaux, <b>fragmentation</b> des milieux par les routes et les villes, introduction d’<b>espèces invasives</b> (frelon asiatique, jussie, écrevisse de Louisiane), réchauffement climatique.</p><p>Une <b>gestion durable</b> cherche à concilier besoins humains et préservation : quotas et tailles minimales de pêche, périodes de repos biologique, forêts exploitées en replantant, réduction des pesticides, <b>aires protégées</b>, <b>trames vertes et bleues</b> (corridors qui relient les milieux naturels), recyclage, économies d’eau et d’énergie. Ces choix se font à différentes échelles : individuelle, locale, nationale et internationale.</p>`)],
  [{q:'Un stock de poissons de 10 000 t se renouvelle de 1 500 t par an. On en pêche 2 000 t par an. Que devient le stock en 4 ans (modèle simplifié) ?',s:['Bilan annuel : + 1 500 − 2 000 = − 500 t.','En 4 ans : 4 × (− 500) = − 2 000 t.','Stock final : 10 000 − 2 000 = 8 000 t : la pêche n’est pas durable, il faudrait pêcher au plus 1 500 t par an.']}],
  ['J’identifie la ressource et je précise si elle est renouvelable.','Je compare le prélèvement au renouvellement.','J’identifie les impacts sur les écosystèmes et la biodiversité.','Je propose une mesure de gestion durable adaptée et j’en discute les limites.'],
  ['Croire qu’une ressource renouvelable est inépuisable : la surexploitation peut l’effondrer.','Penser que le pétrole se reforme rapidement : il faut des millions d’années.','Croire qu’une espèce introduite est toujours sans danger : certaines deviennent invasives.'],
  ['Ressources renouvelables (bois, poissons, eau) et non renouvelables à l’échelle humaine (pétrole, charbon, minerais).','Exploitation durable : prélever moins que le renouvellement.','Surpêche, déforestation, pollutions, fragmentation et espèces invasives menacent la biodiversité.','Quotas, aires protégées, trames vertes et bleues, recyclage : des réponses à différentes échelles.']),
 g:mix([d=>{const S0=R(5,20)*1000,Rn=R(5,30)*100,Cp=R(5,30)*100,n=d===1?1:R(2,5);const Fs=S0+n*(Rn-Cp);
    if(Math.random()<.6||d===1)return num(`Un stock de poissons de <b>${nf(S0)} t</b> se renouvelle de <b>${nf(Rn)} t par an</b> ; on en pêche <b>${nf(Cp)} t par an</b>. Quel sera le stock dans <b>${n} an${n>1?'s':''}</b> (modèle simplifié) ?`,Fs,{unit:'t',expl:`Bilan annuel : ${nf(Rn)} − ${nf(Cp)} = ${Rn-Cp>=0?'+':'−'} ${nf(Math.abs(Rn-Cp))} t. Sur ${n} an${n>1?'s':''} : ${nf(S0)} ${Rn-Cp>=0?'+':'−'} ${n} × ${nf(Math.abs(Rn-Cp))} = <b>${nf(Fs)} t</b>.`,hint:'Fais le bilan d’une année (renouvellement − pêche), puis multiplie par le nombre d’années.'});
    const ok=Cp<=Rn;return ch(`Un stock de poissons se renouvelle de <b>${nf(Rn)} t par an</b> ; on en pêche <b>${nf(Cp)} t par an</b>. Cette pêche est-elle durable ?`,ok?'oui, car on prélève au plus ce qui se renouvelle':'non, car on prélève plus que ce qui se renouvelle',[ok?'non, car on prélève plus que ce qui se renouvelle':'oui, car on prélève au plus ce qui se renouvelle','oui, du moment que le stock de départ est grand'],{expl:`Pêche ${nf(Cp)} t ${ok?'≤':'&gt;'} renouvellement ${nf(Rn)} t : le stock ${ok?'se maintient ou augmente':'diminue chaque année'}.`,hint:'Compare prélèvement et renouvellement.'});},3],
  [S({'renouvelable (si on ne la surexploite pas)':['le bois des forêts','les poissons','l’eau douce','l’énergie du vent'],'non renouvelable à l’échelle humaine':['le pétrole','le charbon','le gaz naturel','le minerai de cuivre']},'« %s » est une ressource…',{'renouvelable (si on ne la surexploite pas)':'Elle se reconstitue à l’échelle de quelques années ou décennies.','non renouvelable à l’échelle humaine':'Elle s’est formée en millions d’années : son stock s’épuise.'}),2],
  [S({'impact négatif sur la biodiversité':['la fragmentation des forêts par une autoroute','la surpêche','l’introduction du frelon asiatique','l’usage intensif de pesticides'],'mesure de préservation':['une trame verte reliant deux forêts','un quota de pêche','la création d’une réserve naturelle','un passage à faune sous une route']},'« %s » est…',{'impact négatif sur la biodiversité':'Cette action détruit, isole ou concurrence des populations d’êtres vivants.','mesure de préservation':'Cette action protège les milieux ou limite les prélèvements.'}),2],
  [bank([['Pourquoi le pétrole est-il une ressource non renouvelable à l’échelle humaine ?','il met des millions d’années à se former',['il est liquide','il est noir','il se trouve sous la mer'],'Nous le consommons bien plus vite qu’il ne se forme.',1],
   ['Qu’est-ce qu’une espèce invasive ?','une espèce introduite qui se multiplie et nuit aux espèces locales',['une espèce en voie de disparition','une espèce locale protégée','une espèce domestique'],'Exemple : le frelon asiatique, qui chasse les abeilles.',1],
   ['À quoi sert une trame verte ?','à relier des milieux naturels pour que les êtres vivants puissent circuler',['à repeindre les routes en vert','à interdire la nature en ville','à planter du gazon'],'Elle limite la fragmentation des habitats.',2],
   ['Que se passe-t-il quand on pêche plus de poissons qu’il n’en naît chaque année ?','le stock diminue et peut s’effondrer',['le stock augmente','le stock reste stable','les poissons grandissent plus vite'],'C’est la surpêche (exemple de la morue de Terre-Neuve).',2],
   ['Pourquoi impose-t-on une taille minimale de capture pour certains poissons ?','pour laisser les jeunes atteindre l’âge de se reproduire',['pour vendre plus de poissons','pour attraper les plus petits','pour protéger les filets'],'Les jeunes poissons doivent pouvoir se reproduire avant d’être pêchés.',2],
   ['Après une déforestation sur une pente, le sol disparaît en quelques années. Pourquoi est-ce grave ?','un sol met des centaines à des milliers d’années à se former',['le sol repousse en un an','le sol est inutile','les arbres repoussent sans sol'],'L’érosion détruit une ressource qui se renouvelle très lentement.',3],
   ['Une autoroute traverse une forêt. Quelle conséquence pour les populations animales ?','elles sont isolées en petites populations plus fragiles',['elles deviennent plus nombreuses','aucune conséquence','elles changent d’espèce'],'La fragmentation réduit les échanges entre populations ; les passages à faune la limitent.',3],
   {tf:'Une ressource renouvelable ne peut jamais s’épuiser.',v:false,e:'Si on la prélève plus vite qu’elle ne se renouvelle, elle s’épuise.',d:2}]),3])}
]);

/* ===================== 3e (cycle 4) ===================== */
const ABO=g=>g.includes('A')&&g.includes('B')?'AB':g.includes('A')?'A':g.includes('B')?'B':'O';
const GENO={A:['(A//A)','(A//O)'],B:['(B//B)','(B//O)'],AB:['(A//B)'],O:['(O//O)']};
const SUP=n=>String(n).split('').map(c=>'⁰¹²³⁴⁵⁶⁷⁸⁹'[+c]).join('');
const PAIRES=[['la drosophile',4],['le pois',7],['le maïs',10],['le chat',19],['l’être humain',23]];

MQ.add('svt','3',[
{id:'svt3a',name:'ADN, gènes et caractères héréditaires',icon:'🧬',domain:'Génétique',
 refs:[REF4,E4(TH2)+' — « ADN, mutations, brassage, gène, méiose et fécondation » ; « Expliquer comment les phénotypes sont déterminés par les génotypes et par l’action de l’environnement »'],
 tip:'Un gène = un emplacement sur un chromosome ; un allèle = une version de ce gène. Chaque cellule du corps possède DEUX allèles de chaque gène (un sur chaque chromosome de la paire), une cellule reproductrice UN seul.',
 c:C(`Tous les êtres humains possèdent le gène du groupe sanguin, et pourtant certains sont du groupe A, d’autres B, AB ou O. Comment un même gène peut-il donner des caractères différents ? La réponse se trouve dans l’<b>ADN</b> et dans les différentes versions des gènes : les <b>allèles</b>.`,
  [T('De l’ADN au gène',`<p>Les chromosomes du noyau sont formés d’<b>ADN</b>, une très longue molécule en double hélice. L’information génétique y est écrite sous la forme d’un enchaînement de quatre éléments, notés A, T, C et G, dont l’ordre forme un message. Un <b>gène</b> est une portion d’ADN, située à un emplacement précis d’un chromosome, qui contient l’information pour réaliser un caractère (en permettant la fabrication d’une protéine).</p><p>Les deux chromosomes d’une même paire portent les mêmes gènes, aux mêmes emplacements. Chaque cellule du corps possède donc <b>deux exemplaires</b> de chaque gène : l’un hérité du père, l’autre de la mère.</p>`),
   T('Allèles, génotype et phénotype',`<p>Un gène peut exister sous plusieurs versions, les <b>allèles</b>, qui diffèrent par de petites variations de l’ADN. Les allèles naissent de <b>mutations</b> : des modifications de l’ADN, spontanées ou favorisées par des agents mutagènes (rayons UV, certaines substances du tabac). Une mutation dans une cellule reproductrice peut être transmise aux descendants.</p><p>Le <b>génotype</b> est l’ensemble des allèles d’un individu pour un gène, noté par exemple (A//O). Le <b>phénotype</b> est le caractère observé (groupe A). Pour le groupe sanguin, les allèles A et B s’expriment tous les deux et l’allèle O ne s’exprime que s’il est présent en deux exemplaires : on dit que A et B sont <b>dominants</b> sur O, qui est <b>récessif</b>. Le phénotype dépend du génotype mais aussi souvent de l’<b>environnement</b> (alimentation, soleil, mode de vie).</p>`)],
  [{q:'Quel est le groupe sanguin d’une personne de génotype (B//O) ?',s:['Elle possède un allèle B et un allèle O.','L’allèle B est dominant sur l’allèle O, qui ne s’exprime pas.','Son phénotype est le groupe B.']}],
  ['Je localise l’information : noyau → chromosome → ADN → gène.','J’écris le génotype avec les deux allèles, un sur chaque chromosome de la paire.','J’en déduis le phénotype en appliquant la dominance.','Je vérifie si l’environnement peut aussi agir sur le caractère.'],
  ['Confondre gène et allèle : le gène est le « tiroir » (groupe sanguin), l’allèle est son contenu (A, B ou O).','Croire qu’une personne du groupe A a forcément le génotype (A//A) : elle peut être (A//O).','Penser que toutes les mutations sont dangereuses : beaucoup sont sans effet, certaines créent la diversité.'],
  ['Un gène est une portion d’ADN d’un chromosome qui détermine un caractère.','Les allèles sont les différentes versions d’un gène ; ils naissent de mutations.','Chaque cellule du corps a deux allèles par gène ; une cellule reproductrice en a un.','Phénotype = génotype + action de l’environnement.']),
 g:mix([d=>{const al=['A','B','O'];const g=[P(al),P(al)].sort();const ph=ABO(g);return ch(`Quel est le groupe sanguin (phénotype) d’une personne de génotype <b>(${g[0]}//${g[1]})</b> ?`,'groupe '+ph,['groupe A','groupe B','groupe AB','groupe O'].filter(x=>x!=='groupe '+ph),{expl:g[0]===g[1]?`Deux allèles ${g[0]} identiques : groupe <b>${ph}</b>.`:ph==='AB'?'Les allèles A et B s’expriment tous les deux : groupe <b>AB</b>.':`L’allèle ${ph} est dominant sur l’allèle O, qui ne s’exprime pas : groupe <b>${ph}</b>.`,hint:'A et B sont dominants sur O.'});},3],
  [d=>{const ph=P(['A','B','AB','O']);const good=GENO[ph].join(' ou ');const bad=['(A//A) seulement','(A//B)','(O//O)','(B//B) ou (B//O)','(A//A) ou (A//O)','(A//O) seulement'].filter(x=>x!==good&&x!==GENO[ph][0]);return ch(`Quel(s) génotype(s) peut avoir une personne du <b>groupe ${ph}</b> ?`,good,pickN(bad,3),{expl:ph==='O'?'L’allèle O est récessif : il ne s’exprime que s’il est présent deux fois, donc <b>(O//O)</b>.':ph==='AB'?'A et B s’expriment ensemble : <b>(A//B)</b>.':`L’allèle ${ph} s’exprime qu’il soit en un ou deux exemplaires : <b>${good}</b>.`,hint:'Un allèle récessif ne s’exprime que s’il est présent deux fois.'});},2],
  [pairs([['l’ADN','molécule en double hélice qui porte l’information génétique'],['un gène','portion d’ADN qui détermine un caractère'],['un allèle','version d’un gène'],['une mutation','modification de la séquence de l’ADN'],['le génotype','ensemble des allèles d’un individu pour un gène'],['le phénotype','caractère observable d’un individu']],{q:'Que désigne « %s » ?',rq:'Quel terme correspond à cette définition : « %s » ?'}),3],
  [bank([['Combien d’allèles d’un même gène une cellule du corps humain possède-t-elle ?','deux',['un','quatre','vingt-trois'],'Un sur chaque chromosome de la paire : l’un vient du père, l’autre de la mère.',1],
   ['Combien d’allèles d’un même gène un spermatozoïde possède-t-il ?','un',['deux','aucun','quarante-six'],'Une cellule reproductrice ne contient qu’un chromosome de chaque paire.',1],
   ['Où se trouvent les gènes ?','sur les chromosomes, dans le noyau',['dans le sang uniquement','dans la membrane','dans les muscles uniquement'],'Les gènes sont des portions de l’ADN des chromosomes.',1],
   ['Comment de nouveaux allèles apparaissent-ils ?','par mutation de l’ADN',['par entraînement physique','par l’alimentation','par la vaccination'],'Une mutation modifie l’ADN et peut créer un nouvel allèle.',2],
   ['Pourquoi est-il conseillé de se protéger des UV du soleil ?','ils peuvent provoquer des mutations dans l’ADN des cellules de la peau',['ils donnent des allèles dominants','ils détruisent les chromosomes sexuels','ils modifient le groupe sanguin'],'Les UV sont des agents mutagènes ; certaines mutations peuvent conduire à un cancer de la peau.',2],
   ['Une mutation apparaît dans une cellule de la peau. Sera-t-elle transmise aux enfants ?','non, seules les mutations des cellules reproductrices sont transmises',['oui, toujours','oui, si la personne bronze','seulement aux garçons'],'Les enfants reçoivent l’ADN des cellules reproductrices des parents.',3],
   ['Deux parents du groupe A ont un enfant du groupe O. Est-ce possible ?','oui, si les deux parents ont le génotype (A//O)',['non, c’est impossible','oui, si l’enfant a mangé des aliments du groupe O','seulement si l’un des parents est AB'],'Chaque parent peut transmettre son allèle O : l’enfant est alors (O//O).',3],
   ['Des vrais jumeaux n’ont pas exactement la même masse musculaire. Pourquoi ?','le phénotype dépend aussi de l’environnement (entraînement, alimentation)',['ils n’ont pas les mêmes allèles','une mutation a changé tous leurs gènes','c’est impossible'],'Même génotype, mais des modes de vie différents.',2],
   {tf:'Toutes les mutations provoquent des maladies.',v:false,e:'Beaucoup sont sans effet visible ; d’autres créent des allèles nouveaux, source de diversité.',d:2}]),3])},

{id:'svt3b',name:'Diversité génétique et évolution',icon:'🦎',domain:'Évolution',
 refs:[REF4,E4(TH2)+' — « Diversité génétique au sein d’une population » ; « Apparition et disparition d’espèces au cours du temps » ; « Maintien des formes aptes à se reproduire, hasard, sélection naturelle »'],
 tip:'Pour la diversité : méiose (chaque paire se sépare au hasard) puis fécondation (rencontre au hasard). Pour l’évolution : variation héritable + tri par le milieu (sélection naturelle) + hasard, sur de nombreuses générations.',
 c:C(`Hormis les vrais jumeaux, aucun être humain n’est génétiquement identique à un autre, même entre frères et sœurs. Et les espèces elles-mêmes changent au fil des générations : il y a 66 millions d’années, aucun primate actuel n’existait. Comment naît cette diversité, et comment les espèces évoluent-elles ?`,
  [T('Méiose et fécondation : chaque individu est unique',`<p>Les cellules reproductrices sont produites par une division particulière, la <b>méiose</b> : chaque cellule reproductrice reçoit <b>un seul chromosome de chaque paire</b>, choisi au hasard. Chez l’être humain, avec 23 paires, un individu peut produire plus de 8 millions (2²³) de combinaisons de chromosomes différentes, et encore davantage grâce aux échanges de morceaux entre chromosomes d’une même paire. C’est le <b>brassage génétique</b>.</p><p>La <b>fécondation</b> réunit au hasard un spermatozoïde et un ovule parmi tous ceux possibles : chaque cellule-œuf, donc chaque individu, possède une combinaison unique d’allèles. Seuls les vrais jumeaux, issus d’une même cellule-œuf, ont la même information génétique. Les <b>mutations</b> créent de nouveaux allèles : elles sont la source première de la diversité.</p>`),
   T('L’évolution des espèces',`<p>Les fossiles montrent que des espèces apparaissent et disparaissent au cours des temps géologiques (crise biologique de la fin du Crétacé, il y a 66 millions d’années). Les espèces actuelles partagent des <b>ancêtres communs</b> : l’être humain et le chimpanzé ont un ancêtre commun, mais l’être humain ne descend pas du chimpanzé.</p><p>Charles <b>Darwin</b> (1859) a proposé le mécanisme de la <b>sélection naturelle</b> : dans une population, les individus sont variés ; ceux dont les caractères héréditaires sont avantageux dans un milieu donné survivent et se reproduisent davantage ; leurs allèles deviennent plus fréquents au fil des générations. Le <b>hasard</b> joue aussi un rôle (dérive). Exemples : la phalène du bouleau, dont la forme sombre est devenue fréquente dans les forêts noircies par la pollution industrielle ; les bactéries résistantes aux antibiotiques.</p>`)],
  [{q:'Combien de combinaisons différentes de chromosomes une drosophile (4 paires) peut-elle produire dans ses cellules reproductrices, sans compter les échanges entre chromosomes ?',s:['Pour chaque paire, la cellule reproductrice reçoit l’un ou l’autre chromosome : 2 possibilités.','Les paires se répartissent indépendamment : 2 × 2 × 2 × 2.','2⁴ = 16 combinaisons différentes.']}],
  ['Je repère la source de diversité : mutation (nouvel allèle), méiose (répartition au hasard), fécondation (rencontre au hasard).','Pour un calcul de combinaisons, je multiplie 2 par lui-même autant de fois qu’il y a de paires.','Pour l’évolution, je cherche la variation héritable, l’avantage dans le milieu et la reproduction différentielle.','Je raisonne sur des populations et de nombreuses générations, pas sur un individu.'],
  ['Croire qu’un individu se transforme pour s’adapter : ce sont les populations qui évoluent, par tri des variations existantes.','Dire que l’être humain descend du chimpanzé : ils ont un ancêtre commun.','Penser que les frères et sœurs ont la même information génétique : seuls les vrais jumeaux l’ont.'],
  ['La méiose répartit au hasard un chromosome de chaque paire dans les cellules reproductrices.','La fécondation réunit au hasard deux cellules reproductrices : chaque individu est génétiquement unique.','Les mutations sont la source des nouveaux allèles.','La sélection naturelle et le hasard modifient la fréquence des allèles : les espèces évoluent.']),
 g:mix([d=>{const [sp,n]=P(PAIRES.filter(x=>d===1?x[1]<=7:d===2?x[1]<=19:true));const v=2**n;return num(`Chez ${sp} (${n} paires de chromosomes), combien de combinaisons différentes de chromosomes peut-on obtenir dans les cellules reproductrices, en ne tenant compte que de la répartition au hasard des paires ?`,v,{expl:`Chaque paire offre 2 possibilités, de façon indépendante : 2 multiplié ${n} fois par lui-même = 2${SUP(n)} = <b>${nf(v)}</b>.`,hint:'2 possibilités par paire : multiplie 2 par lui-même autant de fois qu’il y a de paires.'});},2],
  [d=>{const N=P([50,100,200,250,400,500]),k=R(Math.round(N*0.05),Math.round(N*0.95));const p=rd(k/N*100);return num(`Dans une forêt industrielle anglaise du XIXe siècle, on capture <b>${N} phalènes</b>, dont <b>${k}</b> de forme sombre. Quel est le pourcentage de phalènes sombres ?`,p,{unit:'%',expl:`${k} ÷ ${N} × 100 = <b>${nf(p)} %</b>. Sur les troncs noircis par la suie, les phalènes sombres étaient moins repérées par les oiseaux : elles survivaient et se reproduisaient davantage.`,hint:'Pourcentage = partie ÷ total × 100.'});},2],
  [S({'source de diversité génétique':['une mutation','la répartition au hasard des chromosomes lors de la méiose','la rencontre au hasard des cellules reproductrices'],'mécanisme qui trie les variations':['la sélection naturelle','la survie plus fréquente des individus avantagés dans leur milieu']},'« %s » est…',{'source de diversité génétique':'Elle produit de nouvelles combinaisons ou de nouveaux allèles.','mécanisme qui trie les variations':'Il modifie la fréquence des allèles existants dans une population.'}),2],
  [bank([['Pourquoi deux frères (non jumeaux) n’ont-ils pas la même information génétique ?','méiose et fécondation produisent à chaque fois une combinaison d’allèles nouvelle',['ils n’ont pas les mêmes parents','à cause de leur alimentation','à cause de leur prénom'],'Chaque cellule reproductrice des parents est différente, et leur rencontre se fait au hasard.',1],
   ['Qui a proposé la théorie de l’évolution par sélection naturelle en 1859 ?','Charles Darwin',['Alfred Wegener','Louis Pasteur','Gregor Mendel'],'Dans « De l’origine des espèces ».',1],
   ['Les vrais jumeaux ont la même information génétique car…','ils sont issus d’une même cellule-œuf',['ils sont nés le même jour','ils ont les mêmes parents','ils mangent la même chose'],'La cellule-œuf s’est séparée en deux embryons au début du développement.',1],
   ['L’être humain descend-il du chimpanzé ?','non, ils partagent un ancêtre commun',['oui, directement','oui, depuis 2 000 ans','non, ils n’ont aucune parenté'],'Ce sont deux espèces cousines qui ont évolué chacune de leur côté.',2],
   ['Pourquoi les bactéries résistantes aux antibiotiques deviennent-elles plus fréquentes ?','les antibiotiques éliminent les bactéries sensibles ; les résistantes survivent et se multiplient',['les antibiotiques transforment les bactéries','les bactéries apprennent à résister','par hasard uniquement'],'C’est un exemple actuel de sélection naturelle.',2],
   ['Une girafe qui étire son cou toute sa vie transmet-elle un cou plus long à ses petits ?','non, un caractère acquis au cours de la vie n’est pas transmis',['oui, toujours','oui, si elle est une femelle','seulement si elle mange beaucoup'],'Seules les variations de l’ADN des cellules reproductrices se transmettent.',3],
   ['Dans un milieu longtemps enneigé vit une population de lièvres au pelage plus ou moins clair. Lesquels laisseront le plus de descendants en moyenne ?','ceux au pelage blanc, moins repérés par les prédateurs',['ceux au pelage sombre','tous autant','ceux qui décident de blanchir'],'Les individus avantagés survivent et se reproduisent plus : leurs allèles deviennent plus fréquents.',3],
   ['Que montrent les fossiles des organismes disparus ?','que les espèces apparaissent et disparaissent au cours des temps géologiques',['que les espèces n’ont jamais changé','que la Terre a 6 000 ans','que tous les animaux sont des dinosaures'],'Les êtres vivants ont une histoire : c’est l’évolution.',2],
   {tf:'C’est l’individu qui évolue pour s’adapter à son milieu.',v:false,e:'Ce sont les populations qui évoluent, sur plusieurs générations, par tri des variations héréditaires.',d:3}]),3])},

{id:'svt3c',name:'Immunité, vaccination et mémoire immunitaire',icon:'💉',domain:'Santé',
 refs:[REF4,E4(TH3)+' — « Expliquer les réactions qui permettent à l’organisme de se préserver des micro-organismes pathogènes » ; « Mesures d’hygiène, vaccination, action des antiseptiques et des antibiotiques »','Éduscol — ressource d’évaluation SVT cycle 4 « Exercer son esprit critique - vaccination »'],
 tip:'Compare toujours les deux réponses : premier contact = réponse lente et faible ; deuxième contact (ou après un vaccin) = réponse rapide, forte et durable grâce aux lymphocytes mémoire.',
 c:C(`Si tu as eu la varicelle enfant, tu ne la refais en général pas. Et un vaccin injecté une seule fois peut protéger pendant des années. Comment l’organisme « se souvient »-il d’un micro-organisme, et pourquoi la vaccination protège-t-elle aussi les autres ?`,
  [T('Les deux temps de la réponse immunitaire',`<p>Contre un micro-organisme qui a franchi les barrières, l’organisme réagit d’abord de façon <b>rapide et non spécifique</b> : réaction inflammatoire et <b>phagocytose</b>. Puis vient une réponse <b>spécifique</b>, dirigée contre les <b>antigènes</b> du micro-organisme : les <b>lymphocytes B</b> reconnaissent l’antigène, se multiplient et produisent des <b>anticorps</b> qui neutralisent les micro-organismes, ensuite éliminés par phagocytose ; les <b>lymphocytes T</b> détruisent les cellules infectées par un virus. Les lymphocytes T4 coordonnent cette réponse : le VIH, qui les infecte, affaiblit tout le système immunitaire (sida).</p><p>Après la guérison, il reste des <b>lymphocytes mémoire</b> spécifiques. Lors d’un second contact avec le même antigène, la <b>réponse secondaire</b> est plus rapide, plus forte et plus durable : le micro-organisme est éliminé avant de provoquer la maladie.</p>`),
   T('La vaccination',`<p>Un <b>vaccin</b> contient un antigène rendu inoffensif (micro-organisme tué ou atténué, fragment, toxine inactivée, ou ARN messager qui fait fabriquer un fragment par nos cellules). Il déclenche une réponse primaire et la formation de lymphocytes mémoire, sans la maladie. En cas de contact réel, la réponse est immédiatement de type secondaire. Des rappels entretiennent la mémoire.</p><p>Plus une population est vaccinée, moins le micro-organisme circule : les personnes qui ne peuvent pas être vaccinées (nourrissons, malades) sont protégées indirectement. C’est la <b>protection collective</b>. Historiquement, Edward Jenner (1796, variole) et Louis Pasteur (1885, rage) ont ouvert la voie ; la variole a été éradiquée en 1980. Les <b>antibiotiques</b> soignent les infections bactériennes ; leur mauvais usage favorise les bactéries résistantes.</p>`)],
  [{q:'Après une première injection d’un antigène, le taux d’anticorps atteint 10 unités au 14e jour. Après une seconde injection, il atteint 500 unités au 5e jour. Comparer.',s:['Délai : 14 jours puis 5 jours : la réponse secondaire est plus rapide.','Intensité : 500 ÷ 10 = 50 fois plus d’anticorps : elle est plus forte.','Ces différences s’expliquent par les lymphocytes mémoire formés lors du premier contact : c’est le principe du rappel de vaccin.']}],
  ['Je distingue réponse non spécifique (phagocytose) et spécifique (lymphocytes).','Je compare réponse primaire et secondaire : délai, intensité, durée.','J’explique la vaccination par la mémoire immunitaire.','Je distingue prévention (vaccin) et traitement (antibiotique pour une bactérie).'],
  ['Croire que le vaccin soigne une maladie déjà déclarée : il prévient.','Penser qu’un vaccin contre la rougeole protège contre la grippe : la mémoire est spécifique.','Confondre anticorps (molécules) et antibiotiques (médicaments contre les bactéries).'],
  ['Réponse rapide non spécifique (phagocytose) puis réponse spécifique (lymphocytes B → anticorps ; lymphocytes T).','Les lymphocytes mémoire rendent la réponse secondaire plus rapide, plus forte et plus durable.','Le vaccin crée une mémoire sans provoquer la maladie ; la vaccination de beaucoup protège aussi les autres.','Les antibiotiques agissent sur les bactéries, pas sur les virus.']),
 g:mix([d=>{const p=P([5,10,20,50]),m=P([5,10,20,50,100]),t1=R(10,15),t2=R(2,5);return num(`Taux maximal d’anticorps : <b>${p} unités</b> au ${t1}e jour après un premier contact avec un antigène, <b>${nf(p*m)} unités</b> au ${t2}e jour après un second contact. Combien de fois la réponse secondaire est-elle plus forte ?`,m,{unit:'fois',expl:`${nf(p*m)} ÷ ${p} = <b>${m}</b>. La réponse secondaire est aussi plus rapide (${t2} jours au lieu de ${t1}) grâce aux lymphocytes mémoire.`,hint:'Divise le taux de la réponse secondaire par celui de la réponse primaire.'});},2],
  [d=>{const N=P([200,400,500,800,1000,2000]),v=R(Math.round(N*0.4),N);const p=rd(v/N*100);return num(`Dans un collège de <b>${nf(N)} élèves</b>, <b>${nf(v)}</b> sont à jour de leur vaccination contre la rougeole. Quel est le taux de couverture vaccinale ?`,p,{unit:'%',expl:`${nf(v)} ÷ ${nf(N)} × 100 = <b>${nf(p)} %</b>. Pour la rougeole, très contagieuse, il faut environ 95 % de personnes immunisées pour empêcher la circulation du virus.`,hint:'Vaccinés ÷ total × 100.'});},2],
  [seqs([['Réponse immunitaire contre une bactérie',['contamination','réaction inflammatoire et phagocytose','reconnaissance de l’antigène par des lymphocytes B','multiplication des lymphocytes B','production d’anticorps','neutralisation puis phagocytose des bactéries','persistance de lymphocytes mémoire']]]),2],
  [pairs([['un antigène','molécule étrangère reconnue par les lymphocytes'],['un anticorps','molécule produite par les lymphocytes B qui neutralise un antigène précis'],['un lymphocyte mémoire','cellule qui permet une réponse plus rapide lors d’un nouveau contact'],['un vaccin','préparation contenant un antigène rendu inoffensif'],['la phagocytose','ingestion et digestion d’un micro-organisme par un globule blanc'],['un antibiotique','médicament qui tue les bactéries ou bloque leur multiplication']],{q:'Que désigne « %s » ?',rq:'Quel terme correspond à cette définition : « %s » ?'}),2],
  [bank([['Quelles cellules produisent les anticorps ?','les lymphocytes B',['les lymphocytes T','les globules rouges','les plaquettes'],'Après avoir reconnu l’antigène, ils se multiplient et produisent des anticorps.',1],
   ['Pourquoi ne refait-on généralement pas la varicelle ?','des lymphocytes mémoire permettent une réponse secondaire rapide',['le virus disparaît de la Terre','les anticorps sont des médicaments','la peau devient imperméable'],'Le virus est éliminé avant de provoquer la maladie.',1],
   ['Quelle cellule le VIH infecte-t-il ?','les lymphocytes T4',['les globules rouges','les neurones','les cellules de l’estomac'],'En détruisant les lymphocytes T4, il affaiblit toute la réponse immunitaire.',2],
   ['Qui a mis au point le vaccin contre la rage en 1885 ?','Louis Pasteur',['Edward Jenner','Charles Darwin','Alexander Fleming'],'Jenner avait inventé la vaccination contre la variole en 1796 ; Fleming a découvert la pénicilline.',2],
   ['Pourquoi faut-il parfois des rappels de vaccin ?','pour entretenir et renforcer la mémoire immunitaire',['parce que le premier vaccin était faux','pour soigner une infection','pour changer de groupe sanguin'],'Chaque nouveau contact avec l’antigène relance une réponse secondaire.',2],
   ['Un bébé de 2 mois, trop jeune pour être vacciné contre la rougeole, vit dans une ville où presque tous sont vaccinés. Il est…','protégé indirectement, car le virus circule très peu',['plus exposé qu’ailleurs','vacciné automatiquement','protégé par les antibiotiques'],'C’est la protection collective.',3],
   ['Un vaccin contre la rougeole protège-t-il contre la grippe ?','non, la mémoire immunitaire est spécifique d’un antigène',['oui, contre tous les virus','oui, mais seulement l’hiver','seulement chez les adultes'],'Chaque vaccin cible des antigènes précis.',2],
   ['Pourquoi un anticorps anti-tétanique ne se fixe-t-il pas sur le virus de la grippe ?','sa forme est complémentaire d’un seul antigène',['il est trop petit','il ne circule pas dans le sang','il est détruit par la grippe'],'La spécificité de l’anticorps repose sur la complémentarité de forme avec l’antigène.',3],
   {tf:'Un vaccin soigne une maladie déjà déclarée.',v:false,e:'Le vaccin est préventif : il prépare la mémoire immunitaire avant le contact.',d:1}]),3])},

{id:'svt3d',name:'Reproduction, sexualité responsable et prévention',icon:'🤝',domain:'Reproduction humaine',
 refs:[REF4,E4(TH3)+' — « Expliquer sur quoi reposent les comportements responsables dans le domaine de la sexualité : fertilité, grossesse, respect de l’autre, choix raisonné de la procréation, contraception, prévention des infections sexuellement transmissibles »',REFEV+' — classe de 3e'],
 tip:'Pour chaque méthode, demande-toi : empêche-t-elle une grossesse ? protège-t-elle des IST ? Seul le préservatif (externe ou interne) fait les deux.',
 c:C(`Connaître le fonctionnement de son corps permet de faire des choix libres et responsables : décider si et quand avoir un enfant, se protéger et protéger l’autre des infections, respecter le consentement de chacun. Que dit la science sur la contraception et la prévention des infections sexuellement transmissibles ?`,
  [T('Maîtriser la procréation',`<p>La <b>contraception</b> permet d’éviter une grossesse non désirée. Les méthodes <b>hormonales</b> (pilule à prendre chaque jour, implant, patch, anneau) bloquent l’ovulation ; le <b>dispositif intra-utérin</b> (stérilet) empêche la fécondation ou la nidation ; les <b>préservatifs</b> externe (masculin) et interne (féminin) empêchent les spermatozoïdes d’atteindre l’ovule. Le choix d’une méthode se fait avec un professionnel de santé.</p><p>En cas d’oubli de pilule ou de rapport non protégé, la <b>contraception d’urgence</b> doit être prise le plus tôt possible (au plus tard dans les 3 à 5 jours selon la méthode) ; elle est délivrée sans ordonnance et gratuitement en pharmacie, et l’infirmière scolaire peut la donner. L’<b>interruption volontaire de grossesse</b> (IVG) est un droit encadré par la loi. À l’inverse, la <b>procréation médicalement assistée</b> aide les couples qui ont des difficultés à avoir un enfant.</p>`),
   T('Prévenir les infections sexuellement transmissibles',`<p>Les <b>IST</b> sont des infections transmises lors de rapports sexuels non protégés (et pour certaines par le sang ou de la mère à l’enfant). Elles sont dues à des <b>virus</b> (VIH, papillomavirus humains ou HPV, hépatite B, herpès) ou à des <b>bactéries</b> (chlamydia, gonocoque, syphilis). Beaucoup ne donnent aucun symptôme au début : seul un <b>dépistage</b> permet de savoir.</p><p>Le <b>préservatif</b> est le seul moyen de contraception qui protège aussi des IST (il est gratuit en pharmacie pour les moins de 26 ans). Des <b>vaccins</b> existent contre les HPV (recommandé pour les filles et les garçons de 11 à 14 ans) et l’hépatite B. Après un risque d’exposition au VIH, un <b>traitement post-exposition</b> doit être commencé le plus tôt possible, au plus tard dans les 48 heures. Les IST bactériennes se soignent par antibiotiques, d’où l’intérêt d’un dépistage précoce.</p>`),
   T('Respect, consentement et ressources',`<p>Une relation se fonde sur le <b>respect</b> et le <b>consentement</b> : il doit être libre et éclairé, il peut être retiré à tout moment, et l’absence de « non » ne vaut pas « oui ». Personne n’est obligé d’avoir des relations sexuelles ; chacun avance à son rythme. Les substances comme l’alcool ou le cannabis altèrent le jugement et augmentent les prises de risque.</p><p>Pour s’informer ou être aidé : l’infirmière scolaire, un médecin, un centre de santé sexuelle, un centre gratuit d’information, de dépistage et de diagnostic (CeGIDD), le numéro vert national « Sexualités, contraception, IVG » (0 800 08 11 11, gratuit et anonyme).</p>`)],
  [{q:'Un couple utilise la pilule comme seule méthode. Sont-ils protégés des IST ?',s:['La pilule contient des hormones qui bloquent l’ovulation : elle évite une grossesse.','Elle n’empêche pas le contact entre les muqueuses et les liquides : elle ne protège pas des IST.','Pour se protéger aussi des IST, il faut utiliser un préservatif (et faire un dépistage).']}],
  ['J’identifie le but : éviter une grossesse, éviter une IST, ou les deux.','Je relie chaque méthode à l’étape qu’elle bloque (ovulation, rencontre des gamètes, nidation, contact).','Je sais qu’une IST peut être sans symptôme : je pense au dépistage.','Je connais les ressources : infirmière scolaire, médecin, centre de santé sexuelle, CeGIDD, numéro vert.'],
  ['Croire que la pilule protège des IST : seul le préservatif protège à la fois d’une grossesse et des IST.','Penser qu’une personne qui semble en bonne santé ne peut pas transmettre d’IST : beaucoup d’IST sont sans symptôme.','Croire que la contraception d’urgence est une méthode régulière : c’est une solution exceptionnelle, à prendre le plus vite possible.'],
  ['Contraception hormonale : bloque l’ovulation ; préservatif : barrière qui protège aussi des IST.','Contraception d’urgence : le plus tôt possible, sans ordonnance, gratuite en pharmacie.','IST virales (VIH, HPV, hépatite B) et bactériennes (chlamydia, syphilis) ; dépistage et vaccins (HPV, hépatite B).','Le consentement est libre, éclairé et peut être retiré à tout moment.']),
 g:mix([S({'protège d’une grossesse ET des IST':['le préservatif externe (masculin)','le préservatif interne (féminin)'],'protège d’une grossesse mais PAS des IST':['la pilule','l’implant contraceptif','le stérilet (DIU)','la contraception d’urgence']},'« %s » : que permet cette méthode ?',{'protège d’une grossesse ET des IST':'C’est une barrière qui empêche à la fois le passage des spermatozoïdes et le contact avec les micro-organismes.','protège d’une grossesse mais PAS des IST':'Elle agit sur l’ovulation, la fécondation ou la nidation, mais n’empêche pas la transmission des micro-organismes.'}),3],
  [S({'virus':['le VIH','les papillomavirus humains (HPV)','le virus de l’hépatite B','le virus de l’herpès génital'],'bactérie':['la chlamydia','la syphilis','le gonocoque']},'Cet agent d’IST, « %s », est…',{'virus':'Les antibiotiques n’agissent pas ; il existe des traitements antiviraux et, pour certains, des vaccins (HPV, hépatite B).','bactérie':'Elle se soigne par antibiotiques, d’où l’intérêt d’un dépistage précoce.'}),2],
  [pairs([['le dépistage','test qui permet de savoir si l’on a une IST, même sans symptôme'],['le traitement post-exposition','traitement à commencer au plus tard 48 h après un risque d’exposition au VIH'],['la contraception d’urgence','méthode exceptionnelle à prendre le plus tôt possible après un rapport non protégé'],['le consentement','accord libre et éclairé, qui peut être retiré à tout moment'],['la procréation médicalement assistée','ensemble de techniques médicales qui aident à obtenir une grossesse']],{q:'Que désigne « %s » ?',rq:'Quel terme correspond à cette définition : « %s » ?'}),2],
  [bank([['Quel est le seul moyen de contraception qui protège aussi des IST ?','le préservatif',['la pilule','le stérilet','l’implant'],'Le préservatif (externe ou interne) est une barrière contre les spermatozoïdes et les micro-organismes.',1],
   ['Comment agit la pilule contraceptive ?','ses hormones bloquent l’ovulation',['elle tue les spermatozoïdes','elle protège des IST','elle provoque une IVG'],'Sans ovulation, pas de fécondation possible.',1],
   ['Quand faut-il prendre la contraception d’urgence ?','le plus tôt possible après le rapport à risque',['un mois après','seulement après avoir fait un test de grossesse positif','chaque jour à la place de la pilule'],'Son efficacité diminue avec le temps ; au plus tard 3 à 5 jours selon la méthode.',1],
   ['Pourquoi faire un dépistage même sans symptôme ?','beaucoup d’IST ne donnent aucun symptôme au début',['les IST guérissent toutes seules','le dépistage protège pour toujours','c’est inutile'],'Un dépistage précoce permet de se soigner et d’éviter de transmettre l’infection.',2],
   ['Contre quelles IST existe-t-il un vaccin ?','les papillomavirus (HPV) et l’hépatite B',['le VIH et la syphilis','la chlamydia et le gonocoque','toutes les IST'],'La vaccination contre les HPV est recommandée pour les filles et les garçons de 11 à 14 ans.',2],
   ['Après une prise de risque vis-à-vis du VIH, dans quel délai faut-il consulter pour un traitement post-exposition ?','le plus tôt possible, au plus tard 48 heures',['dans le mois','dans l’année','aucun traitement n’existe'],'Plus il est commencé tôt, plus il est efficace (aux urgences ou dans un CeGIDD).',2],
   ['Une personne a accepté un baiser mais refuse d’aller plus loin. Que dire de son consentement ?','il ne vaut que pour ce qu’elle a accepté et elle peut le retirer à tout moment',['elle a tout accepté','elle doit se justifier','son refus ne compte pas'],'Le consentement est libre, éclairé, spécifique et révocable.',2],
   ['Pourquoi l’alcool augmente-t-il les risques dans le domaine de la sexualité ?','il altère le jugement et favorise les décisions non réfléchies',['il protège des IST','il augmente la fertilité','il remplace le préservatif'],'Les substances psychoactives modifient le raisonnement et la vigilance.',3],
   ['Une IST bactérienne non soignée (comme la chlamydia) peut avoir quelle conséquence ?','une infertilité',['une meilleure immunité','aucune conséquence','une protection contre le VIH'],'Elle peut abîmer les trompes ; dépistée tôt, elle se soigne par antibiotiques.',3],
   ['Où un collégien peut-il trouver une aide gratuite et confidentielle sur la contraception ou les IST ?','auprès de l’infirmière scolaire, d’un centre de santé sexuelle ou d’un CeGIDD',['uniquement sur les réseaux sociaux','nulle part avant 18 ans','uniquement auprès de ses amis'],'Ces professionnels informent, dépistent et orientent, gratuitement et dans le respect de la confidentialité.',1],
   {tf:'Une personne qui paraît en bonne santé ne peut pas transmettre d’IST.',v:false,e:'De nombreuses IST sont sans symptôme : seul un dépistage permet de savoir.',d:2}]),4])},

{id:'svt3e',name:'Système nerveux, comportements et santé',icon:'🧠',domain:'Corps humain',
 refs:[REF4,E4(TH3)+' — « Activité cérébrale ; hygiène de vie : conditions d’un bon fonctionnement du système nerveux, perturbations par certaines situations ou consommations »'],
 tip:'Pour toute substance ou habitude, pose la question : que fait-elle aux SYNAPSES (communication entre neurones) et au temps de réaction ? Pour une distance, d = v × t avec v en m/s.',
 c:C(`Une soirée trop courte, un écran consulté au volant d’un vélo, un verre d’alcool : chacun de ces comportements modifie le fonctionnement du cerveau, parfois pour longtemps. Comment le cerveau traite-t-il l’information, et quelles conditions lui permettent de bien fonctionner ?`,
  [T('Un réseau de neurones qui communique',`<p>Le cerveau contient environ 86 milliards de <b>neurones</b>, reliés entre eux par des milliers de milliards de <b>synapses</b>. Le message nerveux est électrique le long d’un neurone ; à la synapse, il est transmis par des <b>neurotransmetteurs</b>, des molécules libérées par un neurone et captées par le suivant. Des <b>aires cérébrales</b> spécialisées (vision, audition, motricité, langage) travaillent ensemble.</p><p>Le cerveau est <b>plastique</b> : les connexions se renforcent quand on apprend ou s’entraîne, et se modifient tout au long de la vie, en particulier à l’adolescence. Le <b>sommeil</b> (8 à 10 heures recommandées à l’adolescence) est indispensable à la mémorisation et à l’attention ; la lumière des écrans le soir retarde l’endormissement.</p>`),
   T('Des perturbations du système nerveux',`<p>Les <b>substances psychoactives</b> agissent au niveau des synapses : l’alcool ralentit la transmission et allonge le <b>temps de réaction</b> ; le cannabis perturbe l’attention et la mémoire ; la nicotine du tabac et beaucoup de drogues agissent sur le <b>circuit de la récompense</b> et créent une <b>dépendance</b> (addiction). Le cerveau des adolescents, encore en maturation, y est particulièrement sensible. La vente d’alcool et de tabac est interdite aux mineurs.</p><p>Le <b>bruit</b> fort et prolongé (concerts, écouteurs à fort volume) détruit les cellules ciliées de l’oreille interne, qui ne se régénèrent pas : la perte d’audition est définitive. La fatigue, le téléphone au volant ou à vélo augmentent aussi le temps de réaction, donc la distance parcourue avant de réagir.</p>`)],
  [{q:'Un cycliste roule à 5 m/s. Son temps de réaction normal est 1 s ; en regardant son téléphone, il passe à 2 s. Quelle distance supplémentaire parcourt-il avant de freiner ?',s:['Distance parcourue pendant la réaction : d = v × t.','Normal : 5 × 1 = 5 m ; distrait : 5 × 2 = 10 m.','Il parcourt 5 m de plus sans freiner : le risque d’accident augmente.']}],
  ['Je repère la cible de la substance ou du comportement (synapse, oreille, sommeil).','Je décris l’effet sur le fonctionnement (attention, réaction, mémoire, audition).','Je distingue effets immédiats et effets à long terme (dépendance, perte définitive).','Pour une distance de réaction, je convertis km/h en m/s (÷ 3,6) puis d = v × t.'],
  ['Croire que « juste un peu » d’alcool ne change rien : le temps de réaction augmente dès de faibles doses.','Penser que l’on récupère toujours l’audition après un concert : les cellules ciliées détruites ne repoussent pas.','Croire que la dépendance est un manque de volonté : c’est une modification du fonctionnement du cerveau.'],
  ['Les neurones communiquent par des synapses grâce à des neurotransmetteurs.','Le cerveau est plastique : il se modifie avec l’apprentissage, le sommeil est indispensable.','Les substances psychoactives perturbent les synapses et peuvent créer une dépendance.','Bruit fort : perte d’audition définitive ; distraction et alcool : temps de réaction plus long.']),
 g:mix([d=>{const [kmh,ms]=P([[18,5],[36,10],[54,15],[72,20],[90,25],[108,30]]);const t1=P([1,1.5]),t2=P([2,2.5,3]);const k=d===1?0:R(0,1);
    if(k===0)return num(`Un véhicule roule à <b>${ms} m/s</b>. Son conducteur met <b>${nf(t2)} s</b> à réagir. Quelle distance parcourt-il avant de commencer à freiner ?`,rd(ms*t2),{unit:'m',expl:`d = v × t = ${ms} × ${nf(t2)} = <b>${nf(rd(ms*t2))} m</b>.`,hint:'d = v × t.'});
    return num(`Une voiture roule à <b>${kmh} km/h</b>. Après avoir bu de l’alcool, le temps de réaction du conducteur passe de ${nf(t1)} s à ${nf(t2)} s. Quelle distance supplémentaire parcourt-il avant de freiner ?`,rd(ms*(t2-t1)),{unit:'m',expl:`${kmh} km/h = ${kmh} ÷ 3,6 = ${ms} m/s ; ${ms} × ${nf(t2)} − ${ms} × ${nf(t1)} = ${nf(rd(ms*t2))} − ${nf(rd(ms*t1))} = <b>${nf(rd(ms*(t2-t1)))} m</b>.`,hint:'Convertis en m/s (÷ 3,6), puis calcule la distance pour chaque temps de réaction.'});},3],
  [pairs([['la synapse','zone de communication entre deux neurones'],['un neurotransmetteur','molécule qui transmet le message d’un neurone au suivant'],['la plasticité cérébrale','capacité du cerveau à modifier ses connexions'],['l’addiction','dépendance qui pousse à consommer malgré les effets néfastes'],['le circuit de la récompense','ensemble de neurones qui procure une sensation de plaisir'],['les cellules ciliées','cellules de l’oreille interne détruites par un bruit trop fort']],{q:'Que désigne « %s » ?',rq:'Quel terme correspond à cette définition : « %s » ?'}),2],
  [S({'favorable au bon fonctionnement du cerveau':['dormir 8 à 10 heures par nuit','apprendre régulièrement et réviser','pratiquer une activité physique','baisser le volume des écouteurs'],'perturbe le système nerveux':['consommer de l’alcool','fumer du cannabis','utiliser un écran tard le soir','écouter de la musique très fort pendant des heures']},'« %s » est…',{'favorable au bon fonctionnement du cerveau':'Ce comportement entretient l’attention, la mémoire ou les organes des sens.','perturbe le système nerveux':'Ce comportement perturbe les synapses, le sommeil ou les organes des sens.'}),2],
  [bank([['Comment les neurones communiquent-ils entre eux ?','par des synapses, grâce à des neurotransmetteurs',['par le sang uniquement','par des os','ils ne communiquent pas'],'Le message électrique est relayé par des molécules chimiques à la synapse.',1],
   ['Combien d’heures de sommeil sont recommandées à l’adolescence ?','8 à 10 heures',['4 à 5 heures','12 à 14 heures','le sommeil est inutile'],'Le sommeil permet la mémorisation et la récupération.',1],
   ['Quel effet l’alcool a-t-il sur le temps de réaction ?','il l’allonge',['il le raccourcit','aucun effet','il le supprime'],'L’alcool ralentit la transmission nerveuse.',1],
   ['Pourquoi une perte d’audition due au bruit est-elle définitive ?','les cellules ciliées détruites ne se régénèrent pas',['le tympan repousse toujours','le cerveau oublie les sons','les oreilles se bouchent'],'Il faut protéger ses oreilles : volume modéré, pauses, bouchons.',2],
   ['Qu’est-ce que la plasticité cérébrale ?','la capacité du cerveau à modifier ses connexions avec l’apprentissage',['la souplesse du crâne','la capacité du cerveau à grossir','un défaut du cerveau'],'L’entraînement renforce certaines connexions.',2],
   ['Sur quoi la nicotine agit-elle pour créer une dépendance ?','sur le circuit de la récompense du cerveau',['sur l’estomac','sur les os','sur les poumons uniquement'],'Elle modifie le fonctionnement de neurones impliqués dans le plaisir et l’envie.',2],
   ['Pourquoi utiliser un écran juste avant de dormir est-il déconseillé ?','la lumière des écrans retarde l’endormissement',['l’écran fatigue trop les muscles','cela fait grandir trop vite','cela n’a aucun effet'],'Le sommeil devient plus court et moins réparateur.',2],
   ['Pourquoi le cerveau des adolescents est-il particulièrement sensible aux drogues ?','il est encore en maturation et ses connexions se modifient beaucoup',['il est plus petit','il ne fait pas de synapses','il n’a pas de circuit de la récompense'],'Les consommations précoces augmentent le risque de dépendance.',3],
   {tf:'Un élève qui a peu dormi mémorise aussi bien ses leçons.',v:false,e:'Le sommeil joue un rôle clé dans la consolidation de la mémoire.',d:2}]),3])},

{id:'svt3f',name:'Écosystèmes et impacts des activités humaines',icon:'🏞️',domain:'Environnement',
 refs:[REF4,E4(TH1)+' — « Expliquer comment une activité humaine peut modifier l’organisation et le fonctionnement des écosystèmes en lien avec quelques questions environnementales globales »'],
 tip:'Pour un polluant qui s’accumule, multiplie sa concentration par le facteur à chaque maillon de la chaîne alimentaire : ce sont les grands prédateurs qui sont le plus contaminés.',
 c:C(`Dans les années 1960, des aigles et des faucons pondaient des œufs à coquille si fragile qu’ils se cassaient sous le poids des parents. Les oiseaux n’avaient jamais été pulvérisés d’insecticide : alors, d’où venait le produit ? Les activités humaines modifient les écosystèmes de façon parfois inattendue.`,
  [T('Les services rendus par les écosystèmes',`<p>Les écosystèmes rendent des <b>services</b> à l’être humain : production de nourriture et de bois, pollinisation des cultures, épuration de l’eau par les zones humides, stockage du carbone par les forêts et les sols, protection contre l’érosion et les crues, loisirs. Leur bon fonctionnement dépend de la biodiversité et des interactions entre les espèces.</p><p>Les activités humaines peuvent les dégrader : <b>artificialisation</b> des sols et fragmentation des milieux, <b>surexploitation</b> (surpêche), <b>pollutions</b> (plastiques, pesticides, engrais), <b>espèces invasives</b>, <b>réchauffement climatique</b> et acidification des océans liée au CO₂.</p>`),
   T('Quelques mécanismes de perturbation',`<p>Certains polluants peu dégradables (mercure, anciens insecticides comme le DDT, PCB) s’accumulent dans les êtres vivants : leur concentration augmente à chaque maillon de la chaîne alimentaire. C’est la <b>bioamplification</b> : les grands prédateurs, dont l’être humain, sont les plus contaminés.</p><p>L’excès d’<b>engrais</b> (nitrates, phosphates) entraîné vers les rivières provoque l’<b>eutrophisation</b> : les algues prolifèrent, puis meurent ; leur décomposition par les bactéries consomme le dioxygène de l’eau, et les poissons meurent asphyxiés. Des solutions existent : réduction des pesticides et des engrais, agroécologie, restauration de zones humides, <b>trames vertes et bleues</b>, aires protégées, traitement des eaux, sciences participatives pour suivre la biodiversité.</p>`)],
  [{q:'Un insecticide est présent à 0,002 mg/kg dans le plancton. Sa concentration est multipliée par 10 à chaque maillon : plancton → petit poisson → gros poisson → oiseau pêcheur. Concentration dans l’oiseau ?',s:['Trois maillons séparent le plancton de l’oiseau : on multiplie trois fois par 10.','0,002 × 10 × 10 × 10 = 0,002 × 1 000.','= 2 mg/kg : l’oiseau est 1 000 fois plus contaminé que le plancton.']}],
  ['J’identifie l’activité humaine et le milieu touché.','Je décris le mécanisme de perturbation étape par étape.','J’évalue les conséquences sur les populations et les services rendus.','Je propose une solution de préservation ou de restauration et j’en discute les limites.'],
  ['Croire qu’un polluant dilué dans l’eau devient sans danger : certains s’accumulent dans les chaînes alimentaires.','Penser que les engrais favorisent toujours la vie : en excès, ils asphyxient les rivières.','Croire que seules les actions à l’échelle mondiale comptent : les actions locales (haies, mares, jardins) aident aussi.'],
  ['Les écosystèmes rendent des services (nourriture, pollinisation, eau propre, stockage du carbone).','Artificialisation, surexploitation, pollutions, espèces invasives et climat menacent la biodiversité.','Bioamplification : la concentration de certains polluants augmente le long des chaînes alimentaires.','Eutrophisation : trop d’engrais → prolifération d’algues → manque de dioxygène.']),
 g:mix([d=>{const c0=P([0.001,0.002,0.003,0.005,0.01,0.02]),f=P([5,10]),k=d===1?2:R(2,4);const ch_=['plancton','petit poisson','gros poisson','oiseau pêcheur','aigle'].slice(0,k+1);const cf=rd(c0*f**k);
    return num(`Un polluant est présent à <b>${nf(c0)} mg/kg</b> dans le premier maillon d’une chaîne (${ch_.join(' → ')}). Sa concentration est multipliée par <b>${f}</b> à chaque maillon. Quelle est sa concentration dans le dernier maillon (${ch_[k]}) ?`,cf,{unit:'mg/kg',expl:`${k} maillons après le premier : ${nf(c0)} × ${Array(k).fill(f).join(' × ')} = ${nf(c0)} × ${nf(f**k)} = <b>${nf(cf)} mg/kg</b>. C’est la bioamplification.`,hint:'Multiplie par le facteur autant de fois qu’il y a de flèches.'});},3],
  [seqs([['Eutrophisation d’une rivière',['excès d’engrais lessivés vers la rivière','prolifération des algues','mort des algues','décomposition par les bactéries','baisse du dioxygène dans l’eau','mort des poissons']]]),2],
  [S({'service rendu par les écosystèmes':['la pollinisation des cultures','l’épuration de l’eau par une zone humide','le stockage de carbone par une forêt','la protection des sols contre l’érosion'],'menace pour les écosystèmes':['l’artificialisation des sols','la surpêche','la pollution plastique','l’introduction d’espèces invasives'],'solution de préservation':['la restauration d’une zone humide','la plantation de haies','la création d’une aire protégée','la réduction des pesticides']},'« %s » est…',{'service rendu par les écosystèmes':'C’est un bénéfice que l’être humain tire du fonctionnement des écosystèmes.','menace pour les écosystèmes':'Cette activité dégrade les milieux ou les populations.','solution de préservation':'Cette action protège ou restaure les écosystèmes.'}),2],
  [bank([['Pourquoi les grands prédateurs sont-ils les plus contaminés par certains polluants ?','le polluant s’accumule et sa concentration augmente à chaque maillon',['ils boivent plus d’eau','ils respirent plus','par hasard'],'C’est la bioamplification.',1],
   ['Quel service rendent les insectes pollinisateurs ?','ils permettent la production de nombreux fruits et graines',['ils purifient l’air','ils fabriquent du pétrole','ils empêchent les séismes'],'Une grande partie des cultures dépend des pollinisateurs.',1],
   ['Qu’est-ce que l’artificialisation des sols ?','le remplacement de milieux naturels ou agricoles par des routes, bâtiments, parkings',['la plantation d’arbres','le labour','l’arrosage des champs'],'Elle détruit et fragmente les habitats.',1],
   ['Pourquoi les poissons meurent-ils lors d’une eutrophisation ?','la décomposition des algues consomme le dioxygène de l’eau',['les engrais sont toxiques pour leurs écailles','les algues les mangent','l’eau devient trop froide'],'Les bactéries décomposeuses consomment le dioxygène dissous.',2],
   ['En quoi une zone humide est-elle utile ?','elle épure l’eau, stocke l’eau des crues et abrite une grande biodiversité',['elle produit du pétrole','elle n’a aucune utilité','elle provoque des séismes'],'Restaurer les zones humides est une solution de préservation.',2],
   ['Pourquoi l’océan devient-il plus acide ?','il absorbe une partie du CO₂ émis par les activités humaines',['à cause du sel','à cause des poissons','à cause des vagues'],'Le CO₂ dissous acidifie l’eau, ce qui fragilise coraux et coquillages.',3],
   ['Pourquoi les aigles des années 1960 pondaient-ils des œufs fragiles alors qu’ils n’avaient pas été traités ?','l’insecticide s’était accumulé dans leurs proies, puis dans leur corps',['ils étaient malades d’un virus','ils manquaient de soleil','par hasard'],'Le DDT, peu dégradable, s’est concentré le long de la chaîne alimentaire.',3],
   {tf:'Un polluant très dilué dans l’eau est toujours sans danger pour les êtres vivants.',v:false,e:'Certains polluants s’accumulent et se concentrent le long des chaînes alimentaires.',d:2}]),3])},

{id:'svt3g',name:'Climat : causes, évolutions et enjeux',icon:'🌡️',domain:'Climat',
 refs:[REF4,E4(TH1)+' — « Les changements climatiques passés (temps géologiques) et actuels (influence des activités humaines sur le climat notamment par l’émission de gaz à effet de serre) »'],
 tip:'Sépare toujours trois choses : le constat (températures, glaciers, niveau de la mer), la cause (gaz à effet de serre émis par les activités humaines) et les réponses (atténuation, adaptation).',
 c:C(`Il y a 20 000 ans, une grande partie de l’Europe du Nord était couverte de glace et le niveau de la mer était environ 120 m plus bas qu’aujourd’hui. Le climat a donc toujours changé… mais le réchauffement actuel est d’une rapidité exceptionnelle, et sa cause est connue : les activités humaines.`,
  [T('Effet de serre et gaz à effet de serre',`<p>La Terre reçoit l’énergie du Soleil et réémet de la chaleur (rayonnement infrarouge). Certains gaz de l’atmosphère, les <b>gaz à effet de serre</b> (vapeur d’eau, dioxyde de carbone CO₂, méthane CH₄, protoxyde d’azote), retiennent une partie de cette chaleur : c’est l’<b>effet de serre</b>. Sans lui, la température moyenne serait d’environ −18 °C au lieu de +15 °C.</p><p>Depuis le XIXe siècle, la combustion du charbon, du pétrole et du gaz, la déforestation, l’élevage et certaines cultures ont fortement augmenté la teneur en gaz à effet de serre : le CO₂ est passé d’environ 280 ppm (parties par million) avant l’ère industrielle à plus de 420 ppm aujourd’hui. L’effet de serre est renforcé : la température moyenne a augmenté d’environ 1,1 °C entre 1850-1900 et 2011-2020 (GIEC, 2021).</p>`),
   T('Climats passés, conséquences et réponses',`<p>Les climats passés sont reconstitués grâce à des <b>indices</b> : bulles d’air piégées dans les glaces polaires, pollens fossiles, sédiments, fossiles. Ils montrent une alternance de périodes glaciaires et interglaciaires au Quaternaire, liée à des variations de l’orbite terrestre, sur des dizaines de milliers d’années. Le réchauffement actuel se produit en quelques décennies.</p><p>Conséquences : recul des glaciers, élévation du niveau de la mer (environ 20 cm depuis 1900 : dilatation de l’eau et fonte des glaces continentales), vagues de chaleur et sécheresses plus fréquentes, déplacement d’espèces, acidification des océans. Réponses : l’<b>atténuation</b> (réduire les émissions : sobriété, énergies renouvelables, isolation, transports moins émetteurs ; protéger les puits de carbone comme les forêts et les sols) et l’<b>adaptation</b> (digues, cultures résistantes à la sécheresse, végétalisation des villes).</p>`)],
  [{q:'Un trajet de 15 km en voiture émet 150 g de CO₂ par km. Quelle masse de CO₂ est émise ? Et à vélo ?',s:['Voiture : 150 g/km × 15 km = 2 250 g.','2 250 g = 2,25 kg de CO₂.','À vélo, il n’y a pas de combustion : quasiment aucune émission pendant le trajet. Changer de mode de transport est une action d’atténuation.']}],
  ['Je distingue météo (quelques jours) et climat (moyenne sur au moins 30 ans).','J’exploite les données : je repère la tendance et son ordre de grandeur.','Je relie la tendance à sa cause avec des arguments scientifiques.','Je classe les solutions en atténuation ou adaptation.'],
  ['Croire que la fonte de la banquise fait monter le niveau de la mer : elle flotte déjà ; ce sont les glaciers et calottes continentales et la dilatation de l’eau qui le font monter.','Confondre le trou de la couche d’ozone et l’effet de serre : ce sont deux phénomènes différents.','Dire que le climat a toujours changé donc que l’humain n’y est pour rien : la rapidité et la cause du réchauffement actuel sont différentes.'],
  ['L’effet de serre naturel est indispensable ; son renforcement par les activités humaines réchauffe le climat.','CO₂ : environ 280 ppm avant l’ère industrielle, plus de 420 ppm aujourd’hui ; environ +1,1 °C.','Conséquences : glaciers, niveau de la mer, événements extrêmes, biodiversité, océans.','Atténuer (réduire les émissions) et s’adapter (se préparer aux conséquences).']),
 g:mix([d=>{const f=P([100,120,150,180,200]),k=P([5,10,15,20,50,100,250,500]);const g=f*k;return num(`Une voiture émet <b>${f} g de CO₂ par km</b>. Quelle masse de CO₂, en kg, émet-elle sur un trajet de <b>${k} km</b> ?`,g/1000,{unit:'kg',expl:`${f} × ${k} = ${nf(g)} g = <b>${nf(g/1000)} kg</b> de CO₂ (1 kg = 1 000 g).`,hint:'Multiplie, puis convertis les grammes en kilogrammes.'});},2],
  [d=>{const r=P([1.5,2,2.5]),n=P([10,20,30]),c1=R(330,380);const c2=rd(c1+r*n);const y1=P([1970,1980,1990]);return num(`Une station de mesure enregistre <b>${c1} ppm</b> de CO₂ en ${y1} et <b>${nf(c2)} ppm</b> en ${y1+n}. Quelle a été l’augmentation moyenne par an ?`,r,{unit:'ppm/an',expl:`(${nf(c2)} − ${c1}) ÷ ${n} = ${nf(rd(c2-c1))} ÷ ${n} = <b>${nf(r)} ppm par an</b>.`,hint:'Augmentation totale ÷ nombre d’années.'});},2],
  [S({'atténuation':['remplacer une chaudière au fioul par une pompe à chaleur','covoiturer','isoler les logements','protéger les forêts, puits de carbone'],'adaptation':['construire des digues','planter des arbres dans les cours d’école contre la chaleur','choisir des cultures résistantes à la sécheresse','déplacer des habitations menacées par la montée de la mer']},'« %s » relève de…',{'atténuation':'L’action réduit les émissions de gaz à effet de serre ou augmente leur stockage.','adaptation':'L’action prépare à vivre avec les conséquences du réchauffement.'}),2],
  [bank([['Quel gaz à effet de serre est le plus émis par la combustion du pétrole, du charbon et du gaz ?','le dioxyde de carbone',['le dioxygène','le diazote','l’hélium'],'C’est le principal gaz à effet de serre d’origine humaine.',1],
   ['Quelle est la teneur approximative en CO₂ de l’atmosphère aujourd’hui ?','plus de 420 ppm',['environ 280 ppm','environ 21 %','environ 78 %'],'Elle était d’environ 280 ppm avant l’ère industrielle.',1],
   ['De combien la température moyenne mondiale a-t-elle augmenté entre 1850-1900 et 2011-2020 ?','environ 1,1 °C',['environ 10 °C','environ 0,01 °C','elle a baissé'],'Valeur établie par le GIEC (2021).',1],
   ['Comment connaît-on la composition de l’atmosphère d’il y a 100 000 ans ?','grâce aux bulles d’air piégées dans les glaces polaires',['grâce aux livres anciens','grâce aux thermomètres de l’époque','on ne peut pas la connaître'],'Les carottes de glace conservent des échantillons d’air ancien.',2],
   ['La fonte de la banquise arctique fait-elle monter le niveau de la mer ?','très peu, car la banquise flotte déjà sur l’océan',['oui, de plusieurs mètres','oui, autant que les glaciers','elle le fait baisser'],'Ce sont les glaces continentales et la dilatation de l’eau qui élèvent le niveau marin.',3],
   ['Quels éléments expliquent la montée du niveau de la mer ?','la dilatation de l’eau qui se réchauffe et la fonte des glaciers et calottes continentales',['l’évaporation de l’océan','les marées','la pluie'],'Environ 20 cm depuis 1900.',2],
   ['Les glaciations du Quaternaire et le réchauffement actuel diffèrent surtout par…','leur rapidité et leur cause',['leur existence : les glaciations n’ont pas existé','rien du tout','le fait qu’ils concernent d’autres planètes'],'Les cycles glaciaires durent des dizaines de milliers d’années ; le réchauffement actuel se fait en quelques décennies, à cause des activités humaines.',3],
   ['Pourquoi la déforestation renforce-t-elle le réchauffement ?','les arbres coupés ou brûlés libèrent du carbone et ne stockent plus de CO₂',['les arbres produisent du méthane','la forêt refroidit le Soleil','elle n’a aucun effet'],'Les forêts sont des puits de carbone.',2],
   {tf:'Sans effet de serre, la Terre serait plus agréable à vivre.',v:false,e:'Sans effet de serre naturel, la température moyenne serait d’environ −18 °C.',d:2}]),3])},

{id:'svt3h',name:'Risques géologiques et aménagement des territoires',icon:'🏚️',domain:'Planète Terre',
 refs:[REF4,E4(TH1)+' — « Relier les connaissances scientifiques sur les risques naturels… aux mesures de prévention, de protection, d’adaptation ou d’atténuation »'],
 tip:'Magnitude = énergie libérée au foyer (une seule valeur par séisme) ; intensité = effets observés en un lieu (elle diminue en s’éloignant de l’épicentre). Le temps d’arrivée d’une onde : t = d ÷ v.',
 c:C(`En 2010, un séisme de magnitude 7 a fait plus de 200 000 morts en Haïti selon les estimations ; quelques semaines plus tard, un séisme bien plus puissant (magnitude 8,8) au Chili en a fait environ 500. Pourquoi une telle différence ? Parce que le risque dépend autant de la préparation des territoires que de la force du phénomène.`,
  [T('Séismes et éruptions : décrire l’aléa',`<p>Un <b>séisme</b> naît d’une rupture brutale des roches en profondeur, au <b>foyer</b>, le long d’une faille. Des <b>ondes sismiques</b> se propagent : les ondes P, les plus rapides (environ 6 km/s dans la croûte), arrivent les premières ; les ondes S, plus lentes, puis les ondes de surface, qui provoquent le plus de dégâts. Les <b>sismographes</b> enregistrent ces ondes.</p><p>La <b>magnitude</b> mesure l’énergie libérée au foyer : un seul nombre par séisme, sur une échelle ouverte. L’<b>intensité</b> décrit les effets observés en un lieu (de I à XII) : elle est en général maximale près de l’<b>épicentre</b> et diminue avec la distance. Les éruptions volcaniques sont un autre aléa géologique : coulées de lave, nuées ardentes, cendres, gaz, coulées de boue.</p>`),
   T('Aménager les territoires face aux risques',`<p>On ne sait pas prévoir la date d’un séisme, mais on connaît les zones exposées : la France est divisée en cinq zones de sismicité, de 1 (très faible) à 5 (forte, aux Antilles). La <b>prévention</b> repose sur les règles de construction parasismique, les plans de prévention des risques (qui interdisent ou encadrent les constructions), l’information de la population et les exercices.</p><p>Pour les volcans, la <b>surveillance</b> (sismicité, déformation du sol, gaz émis) permet souvent de prévoir une éruption et d’<b>évacuer</b> à temps, comme dans les observatoires volcanologiques de La Réunion, de Martinique et de Guadeloupe. La <b>vulnérabilité</b> d’un territoire dépend de la qualité des constructions, de la densité de population, de l’organisation des secours et de la préparation des habitants.</p>`)],
  [{q:'Une station est à 180 km de l’épicentre. En prenant 6 km/s pour les ondes P et 3 km/s pour les ondes S (valeurs simplifiées), quel est le décalage entre leurs arrivées ?',s:['Ondes P : t = 180 ÷ 6 = 30 s.','Ondes S : t = 180 ÷ 3 = 60 s.','Décalage : 60 − 30 = 30 s. Plus la station est loin, plus le décalage est grand : on s’en sert pour localiser l’épicentre.']}],
  ['Je décris l’aléa (type, magnitude ou intensité, localisation).','Je repère les enjeux et leur vulnérabilité.','J’identifie les mesures de prévision, de prévention et de protection adaptées.','Pour les ondes, j’utilise t = d ÷ v, puis je compare les temps d’arrivée.'],
  ['Confondre magnitude (énergie au foyer) et intensité (effets en un lieu).','Croire qu’un séisme de forte magnitude fait toujours plus de victimes : la vulnérabilité compte autant.','Penser qu’on peut prévoir la date d’un séisme comme celle d’une éruption surveillée.'],
  ['Foyer en profondeur, épicentre en surface ; ondes P (rapides) puis S puis ondes de surface.','Magnitude : énergie libérée ; intensité : effets observés, qui diminuent avec la distance.','Prévention : constructions parasismiques, zonage, plans de prévention, information, exercices.','La surveillance des volcans permet de prévoir des éruptions et d’évacuer.']),
 g:mix([d=>{const k=R(2,d===1?10:40);const dist=6*k;const q=d===1?0:R(0,2);
    if(q===0)return num(`Une station sismique est à <b>${dist} km</b> de l’épicentre. Les ondes P se propagent à environ <b>6 km/s</b>. Au bout de combien de secondes arrivent-elles ?`,k,{unit:'s',expl:`t = d ÷ v = ${dist} ÷ 6 = <b>${k} s</b>.`,hint:'t = d ÷ v.'});
    if(q===1)return num(`Une station est à <b>${dist} km</b> de l’épicentre. En prenant <b>3 km/s</b> pour les ondes S (valeur simplifiée), au bout de combien de secondes arrivent-elles ?`,2*k,{unit:'s',expl:`t = ${dist} ÷ 3 = <b>${2*k} s</b>.`,hint:'t = d ÷ v.'});
    return num(`Une station est à <b>${dist} km</b> de l’épicentre. Ondes P : 6 km/s ; ondes S : 3 km/s (valeurs simplifiées). Quel est le décalage entre l’arrivée des ondes P et celle des ondes S ?`,k,{unit:'s',expl:`P : ${dist} ÷ 6 = ${k} s ; S : ${dist} ÷ 3 = ${2*k} s ; décalage : ${2*k} − ${k} = <b>${k} s</b>.`,hint:'Calcule les deux temps d’arrivée, puis leur différence.'});},3],
  [S({'la magnitude':['une valeur unique pour un séisme donné','l’énergie libérée au foyer','une valeur calculée à partir des enregistrements des sismographes'],'l’intensité':['les effets observés en un lieu précis','une valeur qui diminue en s’éloignant de l’épicentre','une échelle de I à XII fondée sur les dégâts et les ressentis']},'« %s » caractérise…',{'la magnitude':'La magnitude mesure l’énergie du séisme au foyer.','l’intensité':'L’intensité décrit les effets du séisme en un lieu.'}),2],
  [S({'prévision':['la surveillance de la déformation d’un volcan','la mesure des gaz émis par un volcan'],'prévention':['les normes de construction parasismique','le zonage sismique du territoire','un exercice d’évacuation au collège','l’interdiction de construire au pied d’un volcan actif'],'protection':['un abri contre les retombées de cendres','des galeries de dérivation pour les coulées de boue']},'« %s » relève de…',{'prévision':'On surveille pour annoncer le phénomène.','prévention':'On réduit la vulnérabilité avant le phénomène.','protection':'On construit un ouvrage pour limiter les effets.'}),2],
  [bank([['Quelles ondes sismiques arrivent en premier à une station ?','les ondes P',['les ondes S','les ondes de surface','toutes en même temps'],'Ce sont les plus rapides.',1],
   ['Que mesure la magnitude d’un séisme ?','l’énergie libérée au foyer',['les dégâts en un lieu','la profondeur de l’océan','la durée des secousses uniquement'],'Il y a une seule magnitude par séisme.',1],
   ['Dans quelle zone de sismicité se trouvent les Antilles françaises ?','zone 5 (forte)',['zone 1 (très faible)','zone 2 (faible)','elles ne sont pas classées'],'Les Antilles sont situées sur une zone de subduction.',2],
   ['Pourquoi un séisme de magnitude 7 a-t-il fait beaucoup plus de victimes en Haïti qu’un séisme de magnitude 8,8 au Chili ?','les constructions et l’organisation étaient beaucoup plus vulnérables en Haïti',['le séisme d’Haïti était plus puissant','le Chili n’a pas de population','par hasard uniquement'],'Le Chili applique des normes parasismiques strictes ; la vulnérabilité fait le risque.',2],
   ['Pourquoi l’intensité d’un séisme diminue-t-elle quand on s’éloigne de l’épicentre ?','les ondes perdent de l’énergie en se propageant',['la magnitude change','le foyer se déplace','les sismographes sont moins précis'],'L’énergie se disperse et s’amortit avec la distance.',2],
   ['Peut-on prévoir une éruption volcanique ?','souvent oui, grâce à la surveillance (séismes, déformation, gaz)',['jamais','oui, au jour près plusieurs années à l’avance','seulement grâce à la météo'],'La surveillance permet souvent d’alerter et d’évacuer à temps.',2],
   ['Une ville en zone sismique veut réduire son risque. Quelle mesure est la plus efficace à long terme ?','appliquer les règles de construction parasismique',['construire des digues','prévoir la date du prochain séisme','interdire les sismographes'],'Les bâtiments adaptés résistent aux secousses : la vulnérabilité diminue.',3],
   ['Deux stations enregistrent un même séisme : décalage P-S de 10 s pour la première, 25 s pour la seconde. Laquelle est la plus proche de l’épicentre ?','la première',['la seconde','elles sont à la même distance','on ne peut pas le savoir'],'Le décalage augmente avec la distance parcourue par les ondes.',3],
   {tf:'Un séisme possède une seule magnitude mais plusieurs intensités selon les lieux.',v:true,e:'La magnitude caractérise le séisme ; l’intensité varie d’un lieu à l’autre.',d:2}]),3])}
]);

})();
